window.__D("text/zohar/c015",{"p":[[9520011618,"<p>(שמות ט״ו:ו׳) יְמִינְךָ יְיָ' נֶאְדָּרִי בַּכֹּחַ. אָמַר רַבִּי שִׁמְעוֹן, בְּשַׁעֲתָא דְּצַפְרָא נָהִיר, וְאַיַּלְתָּא קַיְּימָא בְּקִיּוּמָהּ, אִתְעַבְּרַת בְּסִטְרָהָא, וְעָאלַת בְּמָאתָן הֵיכָלִין דְּמַלְכָּא. בַּר נָשׁ דְּאִשְׁתַּדַּל <Nonei></i>בְּפַלְגוּת לֵילְיָא בְּאוֹרַיְיתָא, בְּשַׁעֲתָא דְּאִתְּעַר רוּחָא דְּצָפוֹן, (ס\"א ותיאובתא דאילתא) וְכַאִיבַת אַיַּלָתָּא לְאִתְּעָרָא בְּעָלְמָא, אָתֵי עִמָּהּ לְקַיְּימָא קֹדֶם מַלְכָּא, בְּשַׁעֲתָא דְּנָהִיר צַפְרָא (ס\"א וההוא בר נש צלי צלותיה וליחד שמיה קדישא כדקא יאות) מַשְׁכִין עָלֵיהּ חַד חוּטָא דְּחֶסֶד. (ק\"ל ע\"ב)</p>\n<p>מִסְתַּכֵּל בִּרְקִיעָא, שַׁרְיָא עָלֵיהּ נְהִירוּ דְּסָכְלְתָנוּ דְּדַעְתָּא קַדִּישָׁא, וּמִתְעַטֵּר בֵּיהּ בַּר נָשׁ, וְדָחֲלִין מִנֵּיהּ כֹּלָּא. כְּדֵין הַאי בַּר נָשׁ אִקְרֵי בְּרָא לְקוּדְשָׁא בְּרִיךְ הוּא, בַּר הֵיכָלָא דְּמַלְכָּא. עָאל בְּכָל תַּרְעוֹי, לֵית דְּיִמְחֵי בִּידֵיהּ.</p>\n<p>בְּשַׁעֲתָא דְּקָרֵי לְהֵיכָלָא דְּמַלְכָּא, עָלֵיהּ כְּתִיב, (תהילים קמ״ה:י״ח) קָרוֹב יְיָ' לְכָל קוֹרְאָיו לְכֹל אֲשֶׁר יִקְרָאוּהוּ בֶאֱמֶת. מַאי בֶאֱמֶת. כְּמָה דְּאוֹקִימְנָא, (מיכה ז׳:כ׳) תִּתֵּן אֱמֶת לְיַעֲקֹב, דְּיָדַע לְיַחֲדָא שְׁמָא קַדִּישָׁא בִּצְלוֹתֵיהּ (נ\"א בעלמא) כְּדְקָא יֵאוֹת. וְדָא פּוּלְחָנָא דְּמַלְכָּא (נ\"א דשמא) קַדִּישָׁא.</p>\n<p>וּמַאן דְּיָדַע לְיַחֲדָא שְׁמָא קַדִּישָׁא כְּדְקָא יֵאוֹת, אוֹקִים אוּמָא יְחִידָא בְּעָלְמָא, דִּכְתִּיב, (שמואל ב ז׳:כ״ג) וּמִי כְעַמְּךָ יִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ. וְעַל דָּא אוֹקִימְנָא, כָּל כֹּהֵן דְּלָא יָדַע לְיַחֲדָא שְׁמָא קַדִּישָׁא כְּדְקָא יֵאוֹת, לָאו פּוּלְחָנִיהּ פּוּלְחָנָא. דְּהָא כֹּלָּא בֵּיהּ תַּלְיָא, פּוּלְחָנָא עִלָּאָה, וּפוּלְחָנָא תַּתָּאָה. וּבָעֵי לְכַוְּונָא לִבָּא וּרְעוּתָא, בְּגִין דְּיִתְבָּרְכוּן עִלָּאֵי וְתַתָּאֵי.</p>\n<p>כְּתִיב (ישעיהו א׳:י״ב) כִּי תָבֹאוּ לֵרָאוֹת פָּנָי. כָּל בַּר נָשׁ דְּאָתֵי לְיַחֲדָא שְׁמָא קַדִּישָׁא, וְלָא אִתְכַּוָון בֵּיהּ בְּלִבָּא וּרְעוּתָא וּדְחִילוּ, בְּגִין דְּיִתְבָּרְכוּן בֵּיהּ עִלָּאֵי וְתַתָּאֵי, רָמָאן לֵיהּ צְלוֹתֵיהּ לְבַר, וְכֹלָּא מַכְרִיזֵי עָלֵיהּ לְבִישׁ. וְקוּדְשָׁא בְּרִיךְ הוּא קָרֵי עָלֵיהּ כִּי תָבֹאוּ לֵרָאוֹת פָּנָי.</p>\n<p>כִּי תָבוֹאוּ לִרְאוֹת מִבָּעֵי לֵיהּ, מַאי לֵרָאוֹת פָּנָי. אֶלָּא כָּל אִינּוּן אַנְפִּין דְּמַלְכָּא, טְמִירִין בְּעִמְקָא (נ\"א באתר) לְבָתַר חֲשׁוֹכָא (ס\"א ישת חשך סתרו וכל וכו') וְכָל אִינּוּן דְּיַדְעִין לְיַחֲדָא שְׁמָא קַדִּישָׁא כְּדְקָא יֵאוֹת מִתְבַקְעִין כָּל אִינּוּן כּוֹתָלֵי חֲשׁוֹכָא, וְאַנְפִּין דְּמַלְכָּא אִתְחַזְיָין, וְנָהֲרִין לְכֹלָּא. וְכַד אִינּוּן אִתְחַזְיָין וְנָהֲרִין, מִתְבָּרְכִין כֹּלָּא עִלָּאִין וְתַתָּאִין. כְּדֵין בִּרְכָּאן אִשְׁתְּכָחוּ בְּכֻלְּהוּ עָלְמִין, וּכְדֵין כְּתִיב לֵרָאוֹת פָּנָי.</p>\n<p>מִי בִקֵּשׁ זֹאת מִיֶּדְכֶם, מַאי קָא מַיְירֵי. אֶלָּא מַאן דְּאָתֵי לְיַחֲדָא שְׁמָא קַדִּישָׁא עִלָּאָה, בָּעֵי לְיַחֲדָא מִסִּטְרָא דְּזֹאת. כְּמָה דִּכְתִּיב, (ויקרא ט״ז:ג׳) בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. בְּגִין דְּיִזְדַּוְּוגֻן כַּחֲדָא, אִינּוּן תְּרֵין: צַדִּיק וְצֶדֶק, בְּזִוּוּגָא חֲדָא. בְּגִין דְּיִתְבָּרְכוּן כֹּלָּא מִנַּיְיהוּ וְאִלֵּין אִקְרוּן חֲצֵרֶךָ, כְּמָה דִּכְתִּיב, (תהילים ס״ה:ה׳) אֲשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶךָ.</p>\n<p>וְאִי אִיהוּ אָתֵי לְיַחֲדָא שְׁמָא קַדִּישָׁא, וְלָא יִתְכַּוָּון בֵּיהּ בִּרְעוּתָא דְּלִבָּא, בִּדְחִילוּ וּרְחִימוּ. קוּדְשָׁא בְּרִיךְ הוּא אָמַר, מִי בִקֵּשׁ זֹאת מִיֶּדְכֶם רְמוֹס חֲצֵרָי. זֹאת וַדַּאי, דְּהָא לא אִשְׁתְּכַח בְּהוּ בִּרְכָּאן. וְלָא דַּי דְּלָא אִשְׁתְּכָחוּ בְּהוּ בִּרְכָּאן, אֶלָּא דְּשַׁרְיָא בְּהוּ דִּינָא וְאִשְׁתְּכַח דִּינָא בְּכֹלָּא.</p>\n<p>תָּא חֲזֵי, יְמִינָא דְּקוּדְשָׁא בְּרִיךְ הוּא, מִנֵּיהּ מִתְעָרִין כָּל נְהִירוּ, כָּל בִּרְכָּאן, וְכָל חִדוּ. בֵּיהּ כָּלִיל שְׂמָאלָא כְּמָה דְּאִית בְּבַר נָשׁ יְמִינָא וּשְׂמָאלָא, וּשְׂמָאלָא אִתְכְּלִיל בִּימִינָא, וִימִינָא הוּא כָּלִיל כֹּלָּא. וְכַד אִתְּעַר יְמִינָא שְׂמָאלָא אִתְּעַר עִמֵּיהּ, דְּהָא בֵּיהּ אָחִיד וְאִתְכְּלִיל.</p>\n<p>וְתָּא חֲזֵי, בְּשַׁעֲתָא דְּאָרִים בַּר נָשׁ יְדֵיהּ בִּצְלוֹתָא, מְכַוְּון בְּאֶצְבְּעָן דִּילֵיהּ לְעֵילָּא. כְּמָה דִּכְתִּיב, (שמות י״ז:י״א) וְהָיָה כַּאֲשֶׁר יָרִים מֹשֶׁה יָדוֹ וְגָבַר יִשְׂרָאֵל. דְּהָא (פ\"ז ע\"א) בִּימִינָא תַּלְיָא כֹּלָּא. וּכְתִיב (ויקרא ט׳:כ״ב) וַיִשָּׂא אַהֲרֹן אֶת יָדָו, וּכְתִיב חָסֵר. וּכְדֵין אִתְכְּוַון לְבָרְכָה לְעֵילָּא.</p>\n<p>וְקוּדְשָׁא בְּרִיךְ הוּא לָאו הָכִי, בְּשַׁעֲתָא דְּאָרִים יְמִינָא לְעֵילָּא, וַוי לְהוּ לְתַתָּאֵי, דְּהָא כָּל סִיַּיעְתָּא וְכָל בִּרְכָּאן אִסְתָּלִיקוּ מִנַּיְיהוּ. מְנָלָן. דִּכְתִּיב נָטִיתָ יְמִינְךָ תִּבְלָעֵמוֹ אָרֶץ. מַאי נָטִיתָ יְמִינְךָ. כְּתַרְגּוּמוֹ, אֲרִימַת יְמִינְךָ. מִיָּד תִּבְלָעֵמוֹ אָרֶץ. וְכַד יְמִינָא אִשְׁתְּכַח, שְׂמָאלָא אִשְׁתְּכַח עִמֵּיהּ, וּכְדֵין לָא שַׁלְטִין דִּינִין בְּעָלְמָא, מַאי טַעְמָא, בְּגִין דִּימִינָא אִשְׁתְּכַח עִמֵּיהּ. וְאִי יְמִינָא אִסְתַּלָּקַת, הָא שְׂמָאלָא אִזְדַּמְּנַת, כְּדֵין דִּינִין מִתְעָרִין בְּעָלְמָא, וְדִינָא שַׁרְיָא בְּכֹלָּא.</p>\n<p>רַבִּי שִׁמְעוֹן כַּד הֲוָה מָטֵי לְהַאי קְרָא, הֲוָה בָּכֵי, דִּכְתִּיב, (איכה ב׳:ג׳) הֵשִׁיב אָחוֹר יְמִינוֹ. וְכִי אֶפְשָׁר דְּהֵשִׁיב אָחוֹר יְמִינוֹ. אֶלָּא בְּגִין דְּאַקְדִּים שְׂמָאלָא לְנַחְתָּא בְּעָלְמָא, וִימִינָא אִשְׁתַּאֲרַת בַּאֲתָר אַחֲרָא.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כְּתִיב (ישעיהו נ״ז:א׳) הַצַּדִּיק אָבָד. וְהָא אוֹקִימְנָא מִלֵּי, הַצַּדִּיק נֶאֱבַד לָא <Nonei></i>כְּתִיב, אֶלָּא הַצַּדִּיק אָבָד. מִכָּל אִינּוּן אַנְפֵּי מַלְכָּא, לָא אִשְׁתְּכַח דְּאָבַד, אֶלָּא צַדִּיק. אָבַד בִּתְרֵי סִטְרֵי: חַד, דְּלָא שָׁרָאן בֵּיהּ בִּרְכָּאן, כַּד בְּקַדְמִיתָא. וְחַד, דְּאִתְרְחִיקַת מִנֵּיהּ בַּת זוּגֵיהּ דְּהִיא כְּנֶסֶת יִשְׂרָאֵל. אִשְׁתְּכַח, דְּצַדִּיק אָבַד יַתִּיר מִכֹּלָּא. וּלְזִמְנָא דְּאָתֵי כְּתִיב, (זכריה ט׳:ט׳) גִּילִי מְאֹד בַּת צִיּוֹן הָרִיעִי בַּת יְרוּשָׁלַ ם הִנֵּה מַלְכֵּךְ יָבֹא לָךְ צַדִּיק וְנוֹשָׁע הוּא. צַדִּיק וּמוֹשִׁיעַ לָא כְּתִיב, אֶלָּא צַדִּיק וְנוֹשָׁע הוּא. הוּא נוֹשָׁע וַדַּאי. וְהָא אִתְּמַר.</p>\n<p>(שמות ט״ו:ו׳) יְמִינְךָ יְיָ' נְאְדָּרִי בַּכֹּחַ. מַאי נֶאְדָּרִי, נֶאְדָּר מִבָּעֵי לֵיהּ. אֶלָּא, בְּשַׁעֲתָא דִּשְׂמָאלָא אַתְיָא לְאִזְדַּוְּוגָא בִּימִינָא, כְּדֵין כְּתִיב נֶאְדָּרִי (ס\"א בכח, תרי, ולעולם וכו') תִּרְעַץ, וּלְעוֹלָם הָכִי הוּא בְּגִין דִּשְׂמָאלָא אִשְׁתְּכַח בִּימִינָא, וְאִתְכְּלִיל בֵּיהּ.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, כְּמָה דְּאוֹקִימְנָא הָכִי הוּא, דְּבַר נָשׁ אִשְׁתְּכַח דְּאִתְפְּלַג. מַאי טַעְמָא. בְּגִין לְקַבְּלָא עִמֵּיהּ בַּת זוּגֵיהּ, דְּיִתְעֲבִידוּ חַד גּוּפָא מַמָּשׁ. כַּד יְמִינְךָ, אִשְׁתְּכַח דְּאִתְפְּלַג. מַאי טַעְמָא. בְּגִין לְקַבְּלָא עִמֵּיהּ שְׂמָאלָא. וְהָכִי הוּא כֹּלָּא, חַד בְּחַד. וְעַל דָּא, בְּחַד מָחֵי וּמַסֵּי, הֲדָא הוּא דִכְתִיב יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב.</p>\n<p>תָּא חֲזֵי, שִׁירָתָא דָּא אִתְּמַר, עַל הַהוּא זִמְנָא, וְעַל זִמְנָא דְּאָתֵי, בְּיוֹמֵי דְּיִתְּעַר מַלְכָּא מְשִׁיחָא, דִּכְתִּיב, יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב, רָעַצְתְּ לָא כְּתִיב, אֶלָּא תִּרְעַץ. מַה כְּתִיב בְּקַדְמִיתָא, (איכה א׳:י״ג) הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵב, בְּהַהוּא זִמְנָא, הִיא תִּרְעַץ אוֹיֵב לְזִמְנָא דְּאָתֵי.</p>\n<p>וְכֹלָּא הָכִי הוּא, תַּהֲרוֹס קָמֶיךָ, הָרַסְתָּ לָא כְּתִיב, אֶלָּא תַּהֲרוֹס. תְּשַׁלַּח חֲרוֹנְךָ יֹאכְלֵמוֹ כַּקַּשׁ, כֹּלָּא לְזִמְנָא דְּאָתֵי. יְמִינְךָ יְיָ' נֶאְדָּרִי בַּכֹּחַ, בְּזִמְנָא דָּא, בְּעָלְמָא דֵּין. יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב, בְּזִמְנָא דְּמַלְכָּא מְשִׁיחָא. וּבְרוֹב גְּאוֹנְךָ תַּהֲרוֹס קָמֶיךָ, לְבִיאַת גּוֹג וּמָגוֹג. תְּשַׁלַּח חֲרוֹנְךָ יֹאכְלֵמוֹ כַּקַּשׁ, לִתְחִיַּית הַמֵּתִים. דִּכְתִּיב, (דניאל י״ב:ב׳) וְרַבִּים מִיְשֵׁינֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת וּלְדִרְאוֹן עוֹלָם.</p>\n<p>בְּהַהוּא זִמְנָא, אָמַר רִבִּי שִׁמְעוֹן, זַכָּאִין אִינּוּן דְּיִשְׁתַּאֲרוּן בְּעָלְמָא, וּמַאן אִינּוּן. תָּא חֲזֵי, לָא יִשְׁתְּאַר מִבְּנִי עָלְמָא, בַּר אִינּוּן גְּזִירִין, דְּקַבִּילוּ אָת קַיָּימָא קַדִּישָׁא, וְעָאלוּ בְּקַיְּימָא קַדִּישָׁא, בְּאִינּוּן תְּרֵין חוּלָקִין, כְּמָה דְּאוֹקִימְנָא. וְהוּא נָטִיר לֵיהּ לְהַהוּא קַיָּים, וְלָא עַיְילֵיהּ בְּאֲתָר דְּלָא אִצְטְרִיךְ, אִלֵּין אִינּוּן דְּיִשְׁתַּאֲרוּן, וְיִכָּתְבוּן לְחַיֵּי עָלְמָא.</p>\n<p>מְנָלָן. דִּכְתִּיב, (ישעיהו ד׳:ג׳) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּיְרוּשָׁלַ ם קָדוֹשׁ יֵאָמֶר לוֹ כָּל הַכָּתוּב לְחַיִּים בִּיְרוּשָׁלַ ם. מַשְׁמַע הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּיְרוּשָׁלַ ם, דְּכָל מַאן דְּאִתְגְּזַר, בְּאִלֵּין תְּרֵין דַּרְגִּין עָאל. וְאִי נָטִיר לְהַהוּא קַיָּים כַּדְקָא חֲזֵי, וְיִזְדְּהַר בֵּיהּ, עָלֵיהּ כְּתִיב הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּיְרוּשָׁלַ ם. אִלֵּין יִשְׁתַּאֲרוּן בְּהַהוּא זִמְנָא, וָבֹהוּ זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְחָדְתָּא עָלְמָא, וּלְמֵחדֵי בְּהוּ. עַל הַהוּא זִמְנָא כְּתִיב, (תהילים ק״ד:ל״א) יְהִי כְבוֹד יְיָ' לְעוֹלָם יִשְׂמַח יְיָ' בְּמַעֲשָׂיו.</p>\n<p>ר' חִיָּיא הֲוָה אָזִיל לְגַבֵּי רִבִּי אֶלְעָזָר, אַשְׁכָּחֵיהּ, דְּהֲוָה יָתִיב לְגַבֵּיהּ דְּרִבִּי יוֹסֵי בְּרַבִּי שִׁמְעוֹן בֶּן לָקוּנְיָיא חָמוּי. עַד דְּזָקִיף רֵישֵׁיהּ, חָמָא לֵיהּ לְרִבִּי חִיָּיא, אָמַר, (ישעיהו י״ט:כ״ד-כ״ה) בַּיּוֹם הַהוּא יִהְיֶה יִשְׂרָאֵל שְׁלִישִׁיָּה לְמִצְרַיִם וּלְאַשּׁוּר בְּרָכָה בְּקֶרֶב הָאָרֶץ אֲשֶׁר בֵּרַכוֹ יְיָ' צְבָאוֹת לֵאמֹר בָּרוּךְ עַמִּי מִצְרַיִם וּמַעֲשֵׂה יָדַי אַשּׁוּר וְנַחֲלָתִי יִשְׂרָאֵל, וְכִי אַשּׁוּר וּמִצְרַיִם קְרִיבִין אִינּוּן לְקוּדְשָׁא בְּרִיךְ הוּא?</p>\n<p>אֶלָּא, עַל גָּלוּתָא דְּיִסְקוּן מִמִּצְרַיִם וּמֵאַשּׁוּר אִתְּמַר, וְאִי אִתְּמַר עַל מִצְרַיִם וְעַל אַשּׁוּר, עַל אִינּוּן חֲסִידִין דִּלְהוֹן, דְּאַהַדְרוּ בְּתִיּוּבְתָּא, וְאִשְׁתַּאֲרוּן לְמִפְלַח לְיִשְׂרָאֵל וּלְמַלְכָּא מְשִׁיחָא, דִּכְתִּיב, (תהילים ע״ב:י״א) וְיִשְׁתַּחֲווּ לוֹ כָּל מְלָכִים. וּכְתִיב, (ישעיהו מ״ט:כ״ג) וְהָיוּ מְלָכִים אוֹמְנַיִךְ וְגוֹ'.</p>\n<p>אֲמַר לֵיהּ, מַאי דִּכְתִּיב, (משלי ג׳:י״ז) דְּרָכֶיהּ דַּרְכֵי נֹעַם אֲמַר לֵיהּ כַּמָּה טִפְּשִׁין כו' בְּנֵי עָלְמָא, דְּלָא יַדְעִין וְלָא מַשְׁגִּיחִין בְּמִלּוֹי דְּאוֹרַיְיתָא, דְּהָא מִלִּין דְּאוֹרַיְיתָא (נ\"א כמה רזין עלאין אית בהו) אִינּוּן אָרְחָא לְמִזְכֵּי בְּהַהוּא נֹעַם יְיָ' דִּכְתִּיב דְּרָכֶיהּ דַּרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם. דַּרְכֵי נֹעַם וַדַּאי. מַאי נֹעַם. כְּמָה דִּכְתִּיב, (תהילים כ״ז:ד׳) לַחֲזוֹת בְּנֹעַם יְיָ', וְהָא אוּקְמוּהָ, בְּגִין (נ\"א כך) דְּאוֹרַיְיתָא, וְאָרְחוֹי, מֵהַהוּא נֹעַם אַתְיָין, וְאִינּוּן אָרְחִין פְּרִישָׁן בֵּיהּ, וְעַל דָּא דְּרָכֶיהּ דַּרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם.</p>\n<p>אָמַר רִבִּי חִיָּיא, תָּנִינָן, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב אוֹרַיְיתָא לְיִשְׂרָאֵל, נָפַק נְהוֹרָא מֵהַהוּא נֹעַם, וְאִתְעַטָּר בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, וּמֵהַהוּא נֹעַם אַבְהִיקוּ זִיוָון דְּכֻלְּהוּ עָלְמִין <Nonei></i>דְּכֻלְּהוּ רְקִיעִין, דְּכֻלְּהוּ כִּתְרִין. עַל הַהִיא שַׁעֲתָא כְּתִיב, (שיר השירים ג׳:י״א) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלמֹה וְגוֹ'.</p>\n<p>וְהַהִיא שַׁעֲתָא דְּאִתְבְּנֵי מַקְדְּשָׁא, אִתְעַטָּר קוּדְשָׁא בְּרִיךְ הוּא בְּהַהוּא עֲטָּרָה, וְיָתִיב בְּכֻרְסְיָיא דִּילֵיהּ, וְאִתְעַטָּר בַּעֲטְרוֹי. וּמֵהַהוּא זִמְנָא דְּאִתְחָרַב בֵּי מַקְדְּשָׁא, לָא אִתְעַטָּר קוּדְשָׁא בְּרִיךְ הוּא בַּעֲטְרוֹי, וְהַהוּא נֹעַם אִתְטָמַּר וְאִתְגְּנִיז.</p>"],[9520011619,"<p>אָמַר רִבִּי אֶלְעָזָר, בְּשַׁעֲתָא דְּעָאל מֹשֶׁה בְּגוֹ עֲנָנָא, כְּמָה דִּכְתִּיב, (שמות כ״ד:י״ח) וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן, כְּבַר נָשׁ דְּהֲוָה אָזִיל בַּאֲתָר דְּרוּחָא. אִיעְרַע בֵּיהּ חַד (ויקרא ע\"ח ע\"ב) מַלְאָכָא רַבְרְבָא, וְתָאנָא, קְמוּאֵ\"ל שְׁמֵיהּ. וְהוּא מְמָנָא עַל תְּרֵיסָר אַלְפִין מְמָנָן שְׁלִיחָן. בָּעָא לְאִזְדַּוְּוגָא בֵּיהּ בְּמֹשֶׁה, פָּתַח מֹשֶׁה פּוּמֵיהּ, (בראשית ט\"ז ע\"א) בִּתְרֵיסַר אַתְוָון גְּלִיפָן דִּשְׁמָא קַדִּישָׁא דְּאוֹלִיף לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בַּסְּנֶה, וְאִתְרְחַק מִנֵּיהּ תְּרֵיסַר אַלְפִין פַּרְסִין, וַהֲוָה אָזַל מֹשֶׁה בַּעֲנָנָא, וְעֵינוֹי מְלַהֲטָן כְּגוּמְרִין דְּאֶשָּׁא.</p>\n<p>עַד דְּאִיעֲרַע בֵּיהּ חַד מַלְאָכָא, רַבְרְבָא וְיַקִּירָא מִן קַדְמָאָה, וְתָאנָא הֲדַרְנִיאֵ\"ל שְׁמֵיהּ, וְהוּא עִלָּאָה עַל שְׁאַר מַלְאָכִין, אֶלֶף וְשִׁתִּין רִבּוֹא פַּרְסִין, וְקָלֵיהּ אָזִיל בְּמָאתָן אֶלֶף רְקִיעִין, דְּמִסְתַּחֲרָאן בְּאֶשָּׁא חִיוָּורָא. כֵּיוָן דְּחָמָא לֵיהּ מֹשֶׁה, לָא יָכִיל לְמַלְּלָא. בָּעָא לְמִשְׁדֵּי גַּרְמֵיהּ מִגּוֹ עֲנָנָא.</p>\n<p>אֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, מֹשֶׁה, וְכִי אַנְתְּ הוּא דְּאַסְגִּית מִלִּין עִמִּי בַּסְּנֶה, דְּבָעִית לְמִנְדַּע רָזָא דִּשְׁמָא קַדִּישָׁא, וְלָא דָּחַלְתְּ. וְהַשְׁתָּא אַתְּ דָּחִיל מֵחָד מִשַּׁמָּשַׁי. כֵּיוָן דִּשְׁמַע מֹשֶׁה קַלֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, אִתְתַּקַּף. פָּתַח פּוּמֵיהּ, בְּע\"ב אַתְוָון דִּשְׁמָא עִלָּאָה, כֵּיוָן דִּשְׁמַע הֲדַרְנִי\"אֵל אַתְוָון דִּשְׁמָא קַדִּישָׁא, מִפּוּמֵיהּ דְּמֹשֶׁה, אִזְדַּעְזָע. קָרִיב לְגַבֵּיהּ, אֲמַר לֵיהּ, זַכָּאָה חוּלָקָךְ מֹשֶׁה, דְּאִתְגְלֵי לָךְ, מַה דְּלָא אִתְגְּלֵי לְמַלְאֲכֵי עִלָּאֵי.</p>\n<p>וַהֲוָה אָזִיל עִמֵּיהּ, עַד דְּמָטוּ לְאֶשָּׁא תַּקִּיפָא, דְּחָד מַלְאָכָא דִּי שְׁמֵיהּ סַנְדַּלְפוֹן. וְתָאנָא, סַנְדַּלְפוֹן עִלָּאָה הוּא עַל שְׁאַר חַבְרוֹי, חֲמֵשׁ מְאָה שְׁנִין. וְהוּא קָאִים בָּתַר פַּרְגּוֹדָא דְּמָארֵיהּ, וְקָשֵׁר לֵיהּ כִּתְרִין, מִבָּעוּתֵיהוֹן (בראשית קס\"ז ע\"ב) דִּצְלוֹתָא דְּיִשְׂרָאֵל. וּבְשַׁעֲתָא דְּמָטֵי הַאי כֶּתֶר לְרֵישֵׁיהּ דְּמַלְכָּא קַדִּישָׁא, הוּא מְקַבֵּל צְלוֹתֵהוֹן דְּיִשְׂרָאֵל. וְכֻלְּהוּ חַיָּילִין וְאֻכְלוֹסִין מִזְדַּעְזְעִין, וְנָהֲמִין וְאַמְרִין, בְּרִיךְ יְקָרָא דַּיְיָ' מֵאֲתַר בֵּית שְׁכִינְתֵּיהּ.</p>\n<p>אֲמַר לֵיהּ הֲדַרְנִיאֵל לְמֹשֶׁה, מֹשֶׁה, לֵית אֲנָא יָכִיל לִמְהַךְ עִמָּךְ, דְּלָא יוֹקִיד לִי אֶשָּׂא תַּקִּיפָא דְּסַנְדַּלְפוֹן. בֵּיהּ שַׁעֲתָא אִזְדַּעְזָע מֹשֶׁה, עַד דְּאַתְקִיף בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּמֹשֶׁה, וְאוֹתְבֵיהּ קָמֵיהּ, וְאוֹלִיף לֵיהּ אוֹרַיְיתָא. וְחָפָא לֵיהּ לְמֹשֶׁה, בְּהַהוּא נְהוֹרָא וְזִיוָא דְּהַהוּא נֹעַם, וַהֲווּ אַנְפּוֹי דְּמֹשֶׁה נְהִירִין בְּכָל אִינּוּן רְקִיעִין. וְכָל חֵילָא דִּשְׁמַיָּא הֲווֹ מִזְדַּעְזְעִין קָמֵיהּ, בְּשַׁעֲתָא דְּהֲוָה נָחִית בְּאוֹרַיְיתָא.</p>\n<p>כֵּיוָן דְּחָבוּ יִשְׂרָאֵל לְתַתָּא, נָטַל קוּדְשָׁא בְּרִיךְ הוּא (נ\"א ממשה) אֶלֶ\"ף חוּלָקִין מֵהַהוּא זִיוָא. בֵּיהּ שַׁעֲתָא, בָּעוּ מַלְאָכִין עִלָּאִין, וְכָל אִינּוּן אֹכְלוֹסִין, לְאוֹקְדָא לְמֹשֶׁה, בְּשַׁעֲתָא דְּאֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא (שמות ל״ב:ז׳) לֵךְ רֵד כִּי שִׁחֵת עַמְּךָ. אִזְדַּעְזָע מֹשֶׁה, וְלָא יָכִיל לְמַלְּלָא, עַד דְּאַסְגֵּי בִּצְלוֹתִין וּבָעוּתִין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>אֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, מֹשֶׁה, אַתְקִיף בְּכוּרְסְיָיא דִּילִי, עַד דְּגָעַר קוּדְשָׁא בְּרִיךְ הוּא בְּכָל אִינּוּן אֹכְלוֹסִין, בְּכָל אִינּוּן חַיָּילִין, וְאַתְקִיף מֹשֶׁה בִּתְרֵין לוּחִין דְּאַבְנִין, וְאָחִית לוֹן לְתַתָּא. וְדָא הוּא דִּכְתִּיב, (משלי כ״א:כ״ב) עִיר גִּבּוֹרִים עָלָה חָכָם וַיוֹרֶד עֹז מִבְטֶחָה. וּמֵהַהוּא זִיוָא דְּאִשְׁתְּאַר בֵּיהּ, הֲווֹ מַבְהִיקִין אַנְפּוֹי דְּמֹשֶׁה. וּמַה בְּהַאי דְּאִשְׁתְּאַר בֵּיהּ לָא הֲוֵי יַכְלִין לְאִסְתַּכְּלָא בְּאַנְפּוֹי, בְּהַהוּא דְּאִסְתַּלָּק מִינֵּיהּ עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>ר' חִיָּיא אָמַר, יְמִינְךָ יְיָ' נְאְדָּרִי בַּכֹּחַ, דָּא אוֹרַיְיתָא. וְעַל דָּא, יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב. דְּלֵית מִלָּה בְּעָלְמָא דְּיִתְבַּר חֵילֵיהוֹן דְּעַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, בַּר בְּשַׁעֲתָא דְּיִשְׂרָאֵל מִתְעַסְּקִין בְּאוֹרַיְיתָא. דְּכָל זְמָן דְּיִשְׂרָאֵל מִתְעַסְּקִין בְּאוֹרַיְיתָא, יְמִינָא אִתְתְּקַף, וְאִתְּבַּר חֵילָא וְתּוּקְפָּא דְּעוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וּבְגִינֵי כַּךְ אוֹרַיְיתָא אִקְרִית עֹז, כְּמָה דְאַתְּ אָמֵר (תהילים כ״ט:י״א) יְיָ' עֹז לְעַמּוֹ יִתֵּן.</p>\n<p>וּבְשַׁעֲתָא דְּיִשְׂרָאֵל לָא מִתְעַסְּקִין בְּאוֹרַיְיתָא שְׂמָאלָא אִתְתָּקַף, וְאִתְתָּקַף חֵילֵיהוֹן דְעוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וְשַׁלְטִין עָלַיְיהוּ, וְגַזְרִין עָלַיְיהוּ גִּזְרִין, דְּלָא יַכְלִין לְמֵיקָם בְּהוּ. וְעַל דָּא אִתְגְּלִיאוּ בְּנִי יִשְׂרָאֵל, וְאִתְבָּדָרוּ בֵּינִי עַמְמַיָּא.</p>\n<p>דְּהָא הוּא דִּכְתִּיב <Nonei></i>(ירמיהו ט׳:י״ב) עַל מָה אָבְדָה הָאָרֶץ וְגוֹ', וַיֹּאמֶר יְיָ' עַל עָזְבָם אֶת תּוֹרָתִי. דְּהָא כָּל זִמְנָא דְּיִשְׂרָאֵל יִשְׁתַּדְּלוּן בְּאוֹרַיְיתָא, אִתְּבַר חֵילָא וְתּוּקְפָּא דְּכָל עוֹבְדֵי עֲבוֹדַה זָרָה, הֲדָא הוּא דִכְתִיב יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב. אָמַר רִבִּי אֶלְעָזָר, וַדַּאי הָכִי הוּא, דְּכָל זִמְנָא דְּקָלֵיהוֹן דְּיִשְׂרָאֵל, אִשְׁתְּמַע בְּבָתֵּי כְּנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת וְכוּ', כְּמָה דְּתַנִּינָא (בראשית כ״ז:כ״ב) הַקּוֹל קוֹל יַעֲקֹב, וְאִי לָאו הַיָּדַיִם יְדֵי עֵשָׂו, וְהָא אוֹקִימְנָא.</p>"],[9520011620,"<p>(שמות ט״ו:ז׳) וּבְרֹב גְּאוֹנְךָ תַּהֲרוֹס קָמֶיךָ. ר' חִזְקִיָּה פָּתַח וְאָמַר, (תהילים י׳:א׳) לָמָּה יְיָ' תַּעֲמוֹד בְּרָחוֹק תַּעְלִים לְעִתּוֹת בַּצָּרָה, בְּשַׁעֲתָא דְּחוֹבֵי עָלְמָא גָּרְמוּ, קוּדְשָׁא בְּרִיךְ הוּא סָלִיק לְעֵילָּא לְעֵילָּא, וּבְנֵי נָשָׁא צַוְוחִין וְנַחְתִּין דִּמְעִין, וְלֵית מַאן דְּיִשְׁגַּח עָלַיְיהוּ. מַאי טַעְמָא. בְּגִין דְּאִיהוּ סָלִיק לְעֵילָּא לְעֵילָּא, וּתְשׁוּבָה אִתְמָנַּע מִנַּיְיהוּ, כְּדֵין כְּתִיב, וּבְרֹב גְּאוֹנְךָ תַּהֲרוֹס קָמֶיךָ.</p>\n<p>ר' יִצְחָק אָמַר, הַאי קְרָא, בְּשַׁעֲתָא דְּאִתְלָבַשׁ קוּדְשָׁא בְּרִיךְ הוּא גָּאוּתָא, עַל עֲמַמְיָא דְּיִתְכַּנְּשׁוּן עָלֵיהּ, כְּמָה דִּכְתִּיב, (תהילים ב׳:ב׳) וְרוֹזְנִים נוֹסְדוּ יַחַד עַל יְיָ' וְעַל מְשִׁיחוֹ. וְתָאנָא זְמִינִין אִינּוּן שִׁבְעִין קַסְטוֹרִין מִכָּל עִיבָר, (נ\"א עמין) לְאִתְכַּנְּשָׁא בְּהַהוּא זִמְנָא בְּאוֹכְלוֹסִין דְּכָל עָלְמָא, וּלְמֶעְבַּד קְרָבָא עַל יְרוּשָׁלַ ם קַרְתָּא קַדִּישָׁא, וּלְאַחֲדָא עֵיטִין עָלֵיהּ דְקוּדְשָׁא בְּרִיךְ הוּא. וּמַאי אַמְרֵי, נוֹקִים עַל פַּטְרוֹנָא בְּקַדְמִיתָא, וּלְבָתַר עַל עַמֵּיהּ, וְעַל הֵיכָלֵיהּ.</p>\n<p>כְּדֵין זַמִין קוּדְשָׁא בְּרִיךְ הוּא לְחַיְּיכָא עָלַיְיהוּ. דִּכְתִּיב, (תהילים ב׳:ד׳) יוֹשֵׁב בַּשָׁמַיִם יִשְׂחַק יְיָ' יִלְעַג לָמוֹ. בְּהַהוּא זִמְנָא יִלְבַּשׁ קוּדְשָׁא בְּרִיךְ הוּא גָּאוּותָא עָלַיְיהוּ, וִישֵׁיצִינוּן מִן עָלְמָא, כְּמָה דִּכְתִּיב, (זכריה י״ד:י״ב) וְזֹאת תִּהְיֶה הַמַּגֵּפָה אֲשֶׁר יִגֹּף יְיָ' אֶת כָּל הָעַמִּים אֲשֶׁר צָבְאוּ עַל יְרוּשָׁלַ ם הָמֵק בְּשָׂרוֹ וְהוּא עוֹמֵד עַל רַגְלָיו.</p>\n<p>רִבִּי אַבָּא אָמַר מִשְּׁמֵיהּ דְּרַב יֵיסָא סָבָא, וְהָכִי אָמַר רַבִּי שִׁמְעוֹן, זַמִין קוּדְשָׁא בְּרִיךְ הוּא לְאַחֲיָיא לְכָל אִינּוּן מַלְכִין, דְּעָקוּ לְיִשְׂרָאֵל וְלִיְרוּשָׁלַ ם, לְאַנְדְּרִיאָנוּס, לְלוּפִינוֹס, וּנְבוּכַדְנֶצַר, וּלְסַנְחֵרִיב, וּלְכָל שְׁאַר מַלְכֵי עַמִּין, דְּחָרִיבוּ בֵּיתֵיהּ, וּלְשַׁלְּטָאָה לוֹן כְּקַדְמִיתָא, וְיִתְכָּנְּשׁוּן עִמְּהוֹן שְׁאַר עַמִּין, וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאִתְפָּרְעָא מִנַּיְיהוּ בְּאִתְגַּלְּיָיא, סַחֲרָנֵי יְרוּשָׁלַם. הֲדָא הוּא דִכְתִיב, וְזֹאת תִּהְיֶה הַמַּגֵּפָה אֲשֶׁר יִגֹּף יְיָ' אֶת כָּל הָעַמִּים אֲשֶׁר צָבְאוּ עַל יְרוּשָׁלַ ם. אֲשֶׁר יִצְבְּאוּ לָא כְּתִיב, אֶלָּא אֲשֶׁר צָבְאוּ. כְּדֵין כְּתִיב, וּבְרֹב גְּאוֹנְךָ תַּהֲרוֹס קָמֶיךָ, וְדָא לְזִמְנָא דְּאָתָא מְשִׁיחָא, כְּתִיב, וְשִׁירָתָא דָּא שִׁירָתָא דְּעָלְמִין הִיא.</p>\n<p>(שמות ט״ו:ח׳) וּבְרוּחַ אַפֶּיךָ נֶעֶרְמוּ מַיִם, בְּהַהוּא זִמְנָא. וּבְגִין כַּךְ אִית בְּהַהוּא זִמְנָא, וּלְזִמְנָא דְּמַלְכָּא מְשִׁיחָא, וּלְזִמְנָא דְּגוֹג וּמָגוֹג. נִצְּבוּ כְּמוֹ נֵד, לְזִמְנָא דְּעָלְמָא דְּאָתֵי, דְּאִיהוּ חֶדְוָותָא דְּכָל עָלְמִין.</p>"],[9520011621,"<p>(שמות ט״ו:ט׳) אָמַר אוֹיֵב אֶרְדּוֹף אַשִּׂיג אֲחַלֵּק שָׁלָל. אָמַר אוֹיֵב, דָּא הַהוּא מְמָנָא רַבְרְבָא עַל מִצְרָאֵי, בְּשַׁעֲתָא דְּאִתְיְהִיב לֵיהּ שֻׁלְטָנוּתָא עַל יִשְׂרָאֵל, חָשִׁיב דְּיֵשֵׁיצִינוּן תְּחוֹת שֻׁלְטָנֵיהּ. אֶלָּא דְּדָכַר קוּדְשָׁא בְּרִיךְ הוּא טוּרֵי עָלְמָא, דַּהֲווֹ מְגִינִּין עָלַיְיהוּ. וְלָא תֵּימָא דָּא בִּלְחוֹדוֹי, אֶלָּא כָּל אִינּוּן רַבְרְבִין דִּמְמָנָן עַל כָּל עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וְכַד אִתְיְיהִיב לְהוּ רְשׁוּתָא וְשֻׁלְטָנוּתָא עַל יִשְׂרָאֵל, כֻּלְּהוּ בָּעָאן דִּישֵׁיצוּן יִשְׂרָאֵל תְּחוֹתַיְיהוּ.</p>\n<p>וְעַל דָּא, אִינּוּן עַמִּין דִּתְחוֹת שׁוּלְטָנֵיהוֹן דְּאִינּוּן מְמָנָן, כֻּלְּהוּ גַּזְירִין גְּזִרִין לְשֵׁיצָאָה לוֹן, אֶלָּא דְּקוּדְשָׁא בְּרִיךְ הוּא דְּכַר טוּרֵי עָלְמָא, וְאָגִין עָלַיְיהוּ. וְכַד חָמָא מֹשֶׁה דָּא, שָׁרָא לְשַׁבְּחָא לְקוּדְשָׁא בְּרִיךְ הוּא, וְאָמַר מִי כָמוֹכָה בָּאֵלִים יְיָ'.</p>"],[9520011622,"<p>אָמַר רַבִּי שִׁמְעוֹן, אִילָנָא חַד רַבְרְבָא עִלָּאָה, תַּקִּיפָא, בֵּיהּ אִתְּזָנוּ עִלָּאִין וְתַתָּאִין. וְהוּא אִתְּחַם בִּתְרֵיסַר תְּחוּמִין, אִתְתָּקַּף בְּאַרְבַּע סִטְרֵי עָלְמָא, דְאִסְתָחֲרָאן (נ\"א דאתחברן) בְּדוּכְתַּיְיהוּ. שִׁבְעִין עֲנָפִין סַלְּקִין בְּגַוֵּיהּ, וְאִתְּזָנוּ מִנֵּיהּ, בְּעִקַר שָׁרְשׁוֹי יַנְקִין אִינּוּן סַחֲרָנֵיהּ, וְאִינּוּן עֲנָפִין דְּמִשְׁתַּכְחִין בְּאִילָנָא.</p>\n<p>כַּד מָטֵי עִדַן שֻׁלְטָנֵיהּ דְּכָל עֲנָפָא וַעֲנָפָא, כֻּלְּהוּ בָּעָאן לְשֵׁיצָאָה כֹּלָּא גּוּפָא דְּאִילָנָא, דְּאִיהוּ עִקָרָא דְּכֻלְּהוּ עֲנָפִין, הַהוּא דְּשָׁלִיט עָלַיְיהוּ, וְיִשְׂרָאֵל אֲחִידָן בֵּיהּ. כַּד מָטָא עָלַיְיהוּ שֻׁלְטָנוּתָא דְּהַהוּא <Nonei></i>גּוּפָא דְּאִילָנָא, חוּלָקָא דְּיִשְׂרָאֵל. בָּעֵי לְנַטְרָא לוֹן, וּלְמֵיהַב שְׁלָמָא בְּכֻלְּהוּ. וְעַל דָּא שִׁבְעִים פָּרֵי הֶחָג, לְמִיהַב שְׁלָמָא לְשִׁבְעִין עֲנָפִין דִּבְגוֹ אִילָנָא.</p>\n<p>וְעַל דָּא מִי כָמוֹכָה בָּאֵלִים יְיָ'. (מאי באלים. אילנא. כמה דאת אמרז, (ישעיהו א׳:כ״ט) כי יבושו מאילים אשר חמדתם. דהוא אילנא, דהוו פלחין לחד דפוסא, דמחקקין בגויה. ואקרי אלים אילנא) מִי כָּמֹכָה דְּיַעֲבֵיד כְּעוֹבָדָךְ וִירַחֵם עַל כֹּלָּא. מִי כָּמֹכָה בְּכָל הַהוּא סַחֲרָנֵיהּ דְּאִילָנָא דְּאַף עַל גַּב דְּאִיהוּ שַׁלְטָא, נָטִיר לְכֹלָּא, נָטִיר לְכָל שְׁאַר, וְלָא בַּעְיָא לְמֶעְבַּד עִמְּהוֹן גְּמִירָא. מִי כָּמֹכָה נְאְדָּר בַּקֹּדֶשׁ, בְּהַהוּא חֵילָא עִלָּאָה דְּאִקְרֵי קֹדֶשׁ. נֶאְדָּר בַּקֹּדֶשׁ מַמָּשׁ, וְאִקְרֵי כֹּחַ יְיָ' נֹעַם יְיָ', וְהָא אוֹקִימְנָא מִילֵי.</p>\n<p>(שמות ט״ו:י״א) מִי כָּמֹכָה בָּאֵלִים יְיָ'. ר' יוֹסֵי פָּתַח (קהלת א׳:י״ד) רָאִיתִי אֶת כָּל הַמַּעֲשִׂים אֲשֶׁר נַעֲשׂוּ תַּחַת הַשָּׁמֶשׁ וְהִנִּה הַכֹּל הֶבֶל וּרְעוּת רוּחַ. שְׁלֹמֹה מַלְכָּא, דְּאִסְתַּלָּק בְּחָכְמְתָא יְתֵירָא עַל כָּל בְּנֵי עָלְמָא, הֵיךְ אָמַר דְּכָל עוֹבָדִין הֶבֶל וּרְעוּת רוּחַ. יָכוֹל אַף מַעֲשֵׂה הַצְּדָקָה, וְהָא כְּתִיב (ישעיהו ל״ב:י״ז) וְהָיָה מַעֲשֵׂה הַצְּדָקָה שָׁלוֹם. אֶלָּא הָא אוּקְמוּהָ, כָּל הַמַּעֲשִׂים אֲשֶׁר נַעֲשׂוּ תַּחַת הַשָּׁמֶשׁ כְּתִיב. שָׁאנִי מַעֲשֵׂה הַצְּדָקָה, דְּאִיהוּ לְעֵילָּא מִן שִׁמְשָׁא.</p>\n<p>וְהִנֵּה הַכֹּל הֶבֶל וּרְעוּת רוּחַ, מַאי קָא מַיְירֵי. אִי תֵּימָא הַכֹּל הֶבֶל כְּמָה דְּאוֹקִימְנָא, דְּאִיהוּ בְּרָזָא דְּחָכְמְתָא, כְּמָה דְאַתְּ אָמֵר הֲבֵל הֲבָלִים אָמַר קֹהֶלֶת, וְאִינּוּן הֲבָלִים קִיּוּמָא דְּעָלְמָא דִּלְעֵילָּא וְתַתָּא. מַאי תֵּימָא בְּהַאי, דִּכְתִּיב הָכָא, הַכֹּל הֶבֶל וּרְעוּת רוּחַ. (והא מלתא דא תחת השמש כתיב)</p>\n<p>אֶלָּא הָכִי אוּקְמוּהָ, וְהָכִי הוּא. תָּא חֲזֵי, בְּשַׁעֲתָא דְּעוֹבָדִין מִתְכַּשְּׁרָן לְתַתָּא, וּבַר נָשׁ אִשְׁתַּדַּל בְּפוּלְחָנָא דְּמַלְכָּא קַדִּישָׁא, הַהוּא מִלָּה דְּעָבִיד, הֶבֶל אִתְעָבִיד מִינֵּיהּ לְעֵילָּא. וְלֵית לָךְ הֶבֶל, דְּלֵית לֵיהּ קָלָא, דְּסָלִיק וְאִתְעַטָּר לְעֵילָּא, וְאִתְעָבִיד סַנֵּיגוֹרָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וְכָל אִינּוּן עוֹבָדִין דְּאִשְׁתַּדַּל בְּהוּ בַּר נָשׁ, דְּלָאו אִינּוּן פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, הַהוּא מִלָּה דְּעָבִיד, הַבָל יִתְעֲבִיד מִינֵּיהּ, וְאַזְלָא וְשָׁאטַת בְּעָלְמָא. וְכַד נַפְקַת נִשְׁמָתֵיהּ דְּבַר נָשׁ, הַהוּא הֶבֶל מְגַלְגְּלָא לֵיהּ בְּעָלְמָא, כְּאַבְנָא בְּקוּסְפִיתָא, כְּמָה דִּכְתִּיב, (שמואל א כ״ה:כ״ט) וְאֶת נֶפֶשׁ אוֹיְבֶיךָ יְקַלְעֶנָּה בְּתוֹךְ כַּף הַקָּלַע.</p>\n<p>מַאי יְקַלְעֶנָּה. הַהוּא הֶבֶל דִּמְגַלְגֵּל לֵיהּ סַחֲרָנֵיהּ בְּעָלְמָא, כְּדֵין כָּל מִלִּין דְּמִתְעַבְּדִין (ואינון דתחות שמשא) דְּלָאו אִינּוּן פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, הֶבֶל יִתְעֲבִיד מִנַּיְיהוּ, אִיהוּ תְּבִירָא דְּרוּחָא, דְּמִתָּבַּר לְרוּחָא דְּסָלִיק וְנָחִית וּמִתְגַּלְגֵּל בְּעָלְמָא, הֲדָא הוּא דִכְתִיב הֶבֶל וּרְעוּת רוּחַ.</p>\n<p>אֲבָל הַהִיא מִלָּה דְּאִיהִי פּוּלְחָנָא דְּמָרֵיהּ דָּא סָלִיק (אקרי) לְעֵילָּא מִן שִׁמְשָׁא, וְאִתְעָבִיד מִנֵּיהּ הֶבֶל קַדִּישָׁא, וְדָא הוּא זַרְעָא דְּזָרַע בַּר נָשׁ בְּהַהוּא עָלְמָא, וּמַה שְּׁמֵיהּ. צְדָקָה. דִּכְתִּיב, (הושע י׳:י״ב) זִרְעוּ לָכֶם לִצְדָקָה.</p>\n<p>הַאי מֵדֲבַּר לֵיהּ לְבַר נָשׁ, כַּד תִּיפּוּק נִשְׁמָתֵיהּ מִינֵּיהּ, וְסַלְּקָא לָהּ בְּאַתְרָא דְּכָבוֹד דִּלְעֵילָּא אִשְׁתְּכַח לְאִתְצַרְרָא בִּצְרוֹרָא דְּחַיֵּי, הֲדָא הוּא דִכְתִיב, (ישעיה כח) וְהָלַךְ לְפָנֶיךָ צִדְקֶךָ בְּגִין לְדַבְּרָא לָךְ, לְסַלְּקָא לָךְ, (מן אתר) לַאֲתָר דְּאִקְרֵי כְּבוֹד יְיָ'. דִּכְתִּיב, (ישעיה כח) כְּבוֹד יְיָ' יַאַסְפֶךָ.</p>\n<p>כָּל אִינּוּן נִשְׁמָתִין, דְּהַהוּא הֶבֶל קַדִּישָׁא מֵדֲבַּר לְהוּ, הַהוּא דְּאִקְרֵי כְּבוֹד יְיָ', כָּנִישׁ לוֹן בְּגַוֵּיהּ, וְאִתְצְרִירָן בֵּיהּ. (הדא הוא דכתיב כבוד ה' יאספך) וְדָא אִקְרֵי נַיְיחָא דְּרוּחָא. אֲבָל אַחֲרָא וּרְעוּת רוּחַ אִקְרֵי. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּכָל עוֹבָדֵיהוֹן לְעֵילָּא מִן שִׁמְשָׁא וְזַרְעִין זַרְעָא דִּצְדָקָה, לְמִזְכֵּי לוֹן לְעָלְמָא דְּאָתֵי, וְעַל דָּא כְּתִיב (מלאכי ג׳:כ׳) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, תָּא חֲזֵי, בְּקַדְמִיתָא כַּד אִתְבְּנִי בֵּי מַקְדְּשָׁא לְתַתָּא, לָא אִתְבְּנִי אֶלָּא בְּדִינָא וְרוּגְזָא, כְּמָה דִּכְתִּיב, (ירמיהו ל״ב:ל״א) כִּי עַל אַפִּי וְעַל חֲמָתִי וְגוֹ' בְּגִין דִּבַאֲתָר דְּדִינָא שַׁרְיָא. לְזִמְנָא דְּאָתֵי, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמִבְנֵי לֵיהּ, וּלְאַתְקְנָא לֵיהּ בְּדַרְגָּא אַחֲרָא עִלָּאָה דְּאִקְרֵי צְדָקָה, דִּכְתִּיב, (ישעיהו נ״ד:י״ד) בִּצְדָקָה תִּכּוֹנָנִי. בְּגִין כַּךְ אִתְקַיָּים, (ביה) וּשְׁמֵיהּ <Nonei></i>מַמָּשׁ צֶדֶק יִתְקְרֵי. מְנָלָן. דִּכְתִּיב, (ירמיהו כ״ג:ו׳) וְזֶה שְׁמוֹ אֲשֶׁר יִקְרֵאוֹ יְיָ' צִדְקֵנוּ.</p>"],[9520011623,"<p>(שמות ט״ו:י״ב) נָטִיתָ יְמִינְךָ תִּבְלָעֵמוֹ אָרֶץ. הָא אִתְּמַר, אֲרִימַת יְמִינְךָ. אָמַר רִבִּי יִצְחָק, הָא אִתְּעָרוּ בֵּיהּ חַבְרַיָּיא, דְּכַד אַפִּיק קוּדְשָׁא בְּרִיךְ הוּא לְמִצְרָאֵי מֵתִין מִתְּחוֹת מַיָּא, אָמַר לְאַרְעָא, כָּנִישׁ לוֹן בְּגַוָּוךְ, וְלָא בָּעָאת, עַד דְּאוֹשִׁיט קוּדְשָׁא בְּרִיךְ הוּא יְמִינָא לְקַבְּלָהּ, וְאוּמֵי לָהּ, כְּדֵין בְּלָעַתְינוּן אַרְעָא, הֲדָא הוּא דִכְתִיב תִּבְלָעֵמוֹ אָרֶץ. אָמַר ר' אֶלְעָזָר, נָטִיתָ יְמִינְךָ: לְאַפְרְשָׁא לָהּ מִשְּׂמָאלָא וּכְדֵין אִתְעָבִיד בְּהוּ דִּינָא.</p>\n<p>(שמות ט״ו:י״ג) נָחִיתָ בְּחַסְדְּךָ עַם זוּ גָּאָלְתָּ, כְּמָה דִּכְתִּיב, (תהלים מה) כִּי יְמִינְךָ וּזְרוֹעֲךָ וְאוֹר פָּנְיךָ כִּי רְצִיתָם. כִּי יְמִינְךָ: דָּא גְּדוֹלָה. נֵהַלְתָּ בְעָזְּךָ, דָּא דִּכְתִּיב וּזְרוֹעֲךָ, דָּא גְּבוּרָה. אֶל נְוֵה קָדְשֶׁךָ, דָּא דִּכְתִּיב, וְאוֹר פָּנְיךָ כִּי רְצִיתָם, דָּא צַדִּיק. וְכֻלְּהוּ מִשְׁתַּכְּחֵי בִּקְרָא.</p>\n<p>(שמות ט״ו:ט״ז) תִּפּוֹל עֲלֵיהֶם אֵימָתָה וָפַחַד. אֵימָתָה, אֵימָה מִבָּעֵי לֵיהּ, מַאי אֵימָתָה. דְּהָא לֵית לָךְ אָת אוֹ מִלָּה חֲדָא בְּאוֹרַיְיתָא, דְּלָא אִית בָּהּ רָזִין עִלָּאִין. מַאי אֵימָתָה. אָמַר רִבִּי שִׁמְעוֹן, כְּלוֹמַר דְּחִילוּ דִּשְׁכִינְתָּא.</p>\n<p>כְּהַאי גַּוְונָא, (שמות ט״ו:י״ז) תְּבִאֵמוֹ וְתִטָּעֵמוֹ בְּהַר נַחֲלָתְךָ וְגוֹ', תְּבִאֵמוֹ וְתִטָּעֵמוֹ, תְּבִאֵם וְתִטָּעֵם מִבָּעֵי לֵיהּ, מַאי תְּבִאֵמוֹ. אֶלָּא רוּחָא דְּקוּדְשָׁא אָמַר, עַל אִינּוּן דָּרָא בַּתְרָאָה, דְּגָזַר יְהוֹשֻׁעַ, וְאִתְגַּלְיָא בְּהוּ גִּלּוּיָא דִּרְשִׁימָא קַדִּישָׁא דִּשְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאִלֵּין אֲחִידָן בֵּיהּ בְּו', וְאִלֵּין אִתְחֲזִיאוּ לְמֵירַת אַרְעָא. כְּמָה דִּכְתִּיב, (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ. דְּכָל מַאן דְּאִתְגְּזַר, וְאִתְגַּלְיָא בֵּיהּ רְשִׁימָא קַדִּישָׁא, וְנָטִיר לֵיהּ, אִקְרֵי צַדִּיק, בְּגִין, כַּךְ, לְעוֹלָם יִירְשׁוּ אָרֶץ.</p>\n<p>וְעַל דָּא תְּבִאֵמוֹ, ו' יְתֵירָה, תְּבִיאֵמוֹ לְאִינוּן דַּאֲחִידָן בְּו'. וְתִטָּעֵמוֹ כְּמָה דְאַתְּ אָמֵר נִצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר. לְאִינוּן דַּאֲחִידָן בְּו', וּלְאִינּוּן בַּתְרָאֵי, אִתְּעַר מִלָּה. וְלֵית לָךְ מִלָּה בְּאוֹרַיְיתָא, אוֹ אָת זְעֵירָא בְּאוֹרַיְיתָא, דְּלֵית בָּהּ רָזִין עִלָּאִין, וְטַעֲמִין קַדִּישִׁין, זַכָּאָה חוּלָקֵיהוֹן דְּיַדְעִין בְּהוּ.</p>"],[9520011624,"<p><Noneb>רעיא מהימנא</b> פִּקּוּדָא לְמִבְנֵי מַקְדְּשָׁא לְתַתָּא, כְּגַוְונָא דְּבֵי מַקְדְּשָׁא דִּלְעֵילָּא, כְּמָה דְאַתְּ אָמֵר, מָכוֹן לְשִׁבְתְּךָ פָּעַלְתָּ יְיָ'. דְּאִצְטְרִיךְ לְמִבְנֵי בֵּי מַקְדְּשָׁא לְתַתָּא, וּלְצַלָּאָה בְּגַוֵּיהּ צְלוֹתָא בְּכָל יוֹמָא, לְמִפְלַח לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, דְּהָא צְלוֹתָא אִקְרֵי עֲבוֹדָה.</p>\n<p>וְהַהוּא בֵּי כְּנִשְׁתָּא, אִצְטְרִיךְ לְמִבְנֵי לֵיהּ בִּשְׁפִירוּ סַגְיָא, וּלְאַתְקְנָא לֵיהּ בְּכָל תִּקּוּנִין, דְּהָא בֵּי כְּנִשְׁתָּא דִּלְתַתָּא, קַיְּימָא לָקֳבֵל בֵּי כְּנִשְׁתָּא דִּלְעֵילָּא.</p>\n<p>בֵּית הַמִקְדָּשׁ לְתַתָּא, אִיהוּ קָאִים כְּגַוְונָא דְּבֵית הַמִּקְדָּשׁ דִּלְעֵילָּא, דְּקָאִים דָּא לָקֳבֵל דָּא. וְהַהוּא בֵּי מַקְדְּשָׁא, כָּל תִּקּוּנוֹי, וְכָל פּוּלְחָנוֹי, וְכָל אִינּוּן מָאנִין, וְשַׁמָּשִׁין, כֻּלְּהוּ אִינּוּן כְּגַוְונָא דִּלְעֵילָּא. מַשְׁכְּנָא דְּקָא עָבֵד מֹשֶׁה בְּמַדְבְּרָא, כֹּלָּא הֲוָה כְּגַוְונָא דִּלְעֵילָּא.</p>\n<p>בֵּי מַקְדְּשָׁא דְּבָנָא שְׁלמֹה מַלְכָּא, הוּא בֵּי נַיְיחָא כְּגַוְונָא עִלָּאָה, בְּכָל אִינּוּן תִּקּוּנִין, לְמֶהֱוֵי בְּתִקּוּנָא דִּלְעֵילָּא, בֵּי נַיְיחָא וְאַחֲסַנְתָּא. הָכִי בֵּי כְּנִשְׁתָּא, אִצְטְרִיךְ בְּכָל תִּקּוּנֵי שַׁפִּירוּ, לְמֶהֱוֵי כְּגַוְונָא עִלָּאָה, לְמֶהֱוֵי בֵּית צְלוֹתָא, לְאַתְקְנָא תִּקּוּנִין בִּצְלוֹתָא, כְּמָה דְּאוּקְמוּהָ.</p>\n<p>וְהַהוּא בֵּי מַקְדְּשָׁא דְּלֶיהֱוִי בֵּיהּ (רנ\"א ע\"א) חַלּוֹנוֹת, דִּכְתִּיב, (דניאלו) וְכַוִּון פְּתִיחָן. כְּגַוְונָא דִּלְעֵילָּא, וְעַל דָּא (שיר השירים ב׳:ט׳) מַשְׁגִּיחַ מִן הַחַלּוֹנוֹת מֵצִיץ מִן הַחֲרַכִּים. וְאִי תֵּימָא אֲפִילּוּ בְּחַקְלָא, בְּגִין דְּרוּחָא לֶהֱוֵי סָלִיק. לָאו הָכִי, דְּהָא אֲנָן צְרִיכִין בַּיִת וְלֵיכָּא. לְאִשְׁתַּכְּחָא בַּיִת לְתַתָּא, כְּגַוְונָא דְּבַיִת עִלָּאָה, לְנַחְתָּא דִּיּוּרָא עִלָּאָה לְדִיּוּרָא תַּתָּאָה.</p>\n<p>וְתוּ דְּהַהוּא צְלוֹתָא, וְהַהוּא רוּחָא, אִצְטְרִיךְ לְסַלְּקָא, וְּלְנָפְקָא מִגּוֹ עָאקוּ, בְּאֹרַח מֵישָׁר, לָקֳבֵל יְרוּשָׁלַם. <Nonei></i>וְעַל דָּא כְּתִיב, (תהילים קי״ח:ה׳) מִן הַמֵּצַר קָרָאתִי יָהּ, דְּאִצְטְרִיךְ אֲתָר דָּחִיק בְּעָאקוּ, לְשַׁדְּרָא בְּגַוֵּיהּ הַהוּא רוּחָא, דְּלָא יִסְטֵי לִימִינָא וְלִשְׂמָאלָא. וּבְחַקְלָא לָא יָכִיל קָלָא לְשַׁדְּרָא לֵיהּ הָכִי, דְּהָא כְּגַוְונָא דָּא קָלָא דְּשׁוֹפָר, אִתְדַּחְיָיא לְבַר בְּאֹרַח מֵישָׁר, מִגּוֹ אֲתָר דָּחִיק, וְאָזִיל וּבָקַע רְקִיעִין, וְסָלִיק בִּסְלִיקוּ, לְאַתְּעָרָא רוּחָא לְעֵילָּא.</p>\n<p>וְאִי תֵּימָא, הָא כְּתִיב, (בראשית כ״ד:ס״ג) וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה. שָׁאנֵי יִצְחָק, דְּמִלָּה אַחֲרָא הֲוָה בֵּיהּ, מַה דְּלָא הֲוָה בְּכָל עָלְמָא. וְתוּ דְּהַאי קְרָא לָאו לְהָכִי אָתָא, דְּוַדַּאי בַּשָּׂדֶה אַחֵר לָא הֲוָה מְצַלֵּי וְהָא אוֹקִימְנָא. (ע\"כ רעיא מהימנא).</p>\n<p>תַּנְיָא אָמַר רִבִּי אַבָּא, זַכָּאָה חוּלָקֵיהוֹן, דְּאִינּוּן דְּזַכָּאן לְמֵימָר שִׁירָתָא דָּא בְּהַאי עָלְמָא, דְּזַכָּאן לְמֵימָר לָהּ בְּעָלְמָא דְּאָתֵי. וְשִׁירָתָא דָּא, אִתְבְּנֵי בְּעֶשְׂרִין וּתְרֵין אַתְוָון קַדִּישִׁן גְּלִיפָן, וּבְעֶשֶׂר אֲמִירָן, וְכֹלָּא אִתְרְשִׁים בִּשְׁמָא קַדִּישָׁא, וְכֹלָּא שְׁלֵימוּתָא דִּשְׁמָא קַדִּישָׁא, וְהָא אִתְּעַרְנָא מִלֵּי.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, בְּהַהִיא שַׁעֲתָא דַּהֲווֹ קַיְימִין יִשְׂרָאֵל עַל יַמָּא, וַהֲווּ אַמְרֵי שִׁירָתָא, אִתְגְּלֵי קוּדְשָׁא בְּרִיךְ הוּא עָלַיְיהוּ, וְכָל רְתִיכוֹי וְחֵילוֹי, בְּגִין דְּיִנְדְּעוּן לְמַלְכֵּיהוֹן, דְּעָבַד לוֹן כָּל אִינּוּן נִסִּין וּגְבוּרָאן, וְכָל חַד וְחַד יָדַע וְאִסְתַּכַּל, מַה דְּלָא יָדְעוּ וְאִסְתַּכָּלוּ שְׁאַר נְבִיאֵי עָלְמָא.</p>\n<p>דְּאִי תֵּימָא דְּלָא יָדְעִין וְלָא אִדְבָּקוּ חָכְמְתָא עִלָּאָה, מִן שִׁירָתָא דָּא תֶּחמֵי, דְּכֻלְּהוּ בְּחָכְמְתָא אִסְתַּכָּלוּ, וְיָדְעוּ מִלִּין וְאָמְרוּ. דְּאִי לָאו הָכִי, אֵיךְ אָמְרוּ כֻּלְּהוּ מִלִּין אֲחְדִין, דְּלָא סָטוּ אִלֵּין מֵאִלֵּין, וּמַה דְּאָמַר דָּא, אָמַר דָּא, וְלָא אַקְדִּים מִלָּה דָּא, לְמִלָּה דָּא, אֶלָּא כֻּלְּהוּ בְּשִׁקּוּלָא חֲדָא, וְרוּחָא דְּקוּדְשָׁא בְּפוּמָא דְּכָל חַד וְחַד, וּמִלִּין אִתְּמָרוּ כֻּלְּהוּ כְּאִלּוּ נָפְקִין מִפּוּמָא חַד. אֶלָּא וַדַּאי כּוּלְּהוּ בְּחָכְמְתָא עִלָּאָה אִסְתַּכָּלוּ, וְיָדְעוּ מִילִין עִלָּאִין, וְרוּחָא דְּקוּדְשָׁא בְּפוּם כָּל חַד וְחַד.</p>\n<p>וַאֲפִילּוּ אִינּוּן דְּבִמְעֵי אִמְּהוֹן, הֲווֹ אַמְרֵי שִׁירָתָא כֻּלְּהוּ כַּחֲדָא, וַהֲווּ חָמָאן כֻּלְּהוּ, מַה דְּלָא חָמָא יְחֶזְקֵאל נְבִיאָה. וְעַל כַּךְ הֲווֹ כֻּלְּהוּ מִסְתַּכְּלֵי, כְּאִלּוּ חָמָאן עֵינָא בְּעֵינָא. וְכַד סִיְּימוּ מִלִּין, כֻּלְּהוּ מִתְבַּסְּמָאן בְּנַפְשַׁיְיהוּ, וְתָּאָבוֹן לְמֵחֱמֵי וּלְאִסְתַּכְּלָא, וְלָא הֲווֹ בָּעָאן לְנַטְלָא מִתַּמָּן, מִסְּגִיאוּת תִּיאוּבְתָּא.</p>\n<p>בְּהַהִיא שַׁעֲתָא, אָמַר מֹשֶׁה לְקוּדְשָׁא בְּרִיךְ הוּא, בָּנַיִךְ מִסְּגִיאוּת תִּיאוּבְתָּא לְאִסְתַּכְּלָא בָּךְ, לָא בָּעָאן לְנַטְלָא מִן יַמָּא. מַה עָבֵד קוּדְשָׁא בְּרִיךְ הוּא, אַסְתִּים יְקָרֵיהּ לְבַר לְמַדְבְּרָא, וְתַמָּן אִתְגְּלֵי וְלָא אִתְגְּלֵי. אָמַר לוֹן מֹשֶׁה לְיִשְׂרָאֵל, כַּמָּה (ס\"א זמנין לנטלא מתמן, ולא בעי') זִמְנִין אֲמֵינָא לְנַטְלָא מִתַּמָּן וְלָא בָּעִיתוּן עַד דִּי אַחְזֵי לוֹן זִיוָא יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא בְּמַדְבְּרָא, וּמִיַּד הֲווֹ תָּאָבִין,</p>\n<p>וְלָא נַטְלוּ, עַד דְּאָחִיד בְּהוּ מֹשֶׁה וְאַחְמֵי לוֹן זִיוָא יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא בְּמַדְבְּרָא, כְּדֵין מִסְּגִיאוּת תִּיאוּבְתָּא וּרְעוּתָא לְאִסְתַּכְּלָא, אַנְטִיל לוֹן מֹשֶׁה, הֲדָא הוּא דִכְתִיב וַיַסַּע מֹשֶׁה אֶת יִשְׂרָאֵל מִיָּם סוּף וַיֵּצְאוּ אֶל מִדְבַּר שׁוּר. מַאי מִדְבַּר שׁוּר. מַדְבְּרָא, דַּהֲווֹ בָּעָאן לְאִסְתַּכְּלָא בֵּיהּ, זִיוָא יְקָרָא דְּמַלְכָּא קַדִּישָׁא, וְעַל דָּא אִקְרֵי מִדְבַּר שׁוּר: אִסְתַּכְּלוּתָא שָׁם.</p>"],[9520011625,"<p>(שמות ט״ו:כ״ב) וַיֵּלְכוּ שְׁלֹשֶׁת יָמִים בַּמִּדְבָּר וְלֹא מָצְאוּ מָיִם. וְאֵין מַיִם אֶלָּא תּוֹרָה, שֶׁנֶּאֱמַר (ישעיהו נ״ה:א׳) הוֹי כָּל צָמֵא לְכוּ לַמַּיִם. אָמַר רִבִּי יֵיסָא, וְכִי מַאן יָהַב לְהוּ אוֹרַיְיתָא הָכָא, וְהָא עַד כְּעַן לָא אִתְיְהִיבַת לוֹן אוֹרַיְיתָא.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, אִינּוּן נָפְקוּ לְמַדְבְּרָא לְאִסְתַּכְּלָא, קוּדְשָׁא בְּרִיךְ הוּא נָטַל זִיוָא יְקָרָא דִּילֵיהּ מִתַּמָּן, וְאִינּוּן אָזְלוּ לְאִסְתַּכְּלָא (לקודשא בריך הוא) בֵּיהּ, וְלָא אַשְׁכְּחוּהוּ. וְאוֹלִיפְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא תּוֹרָה אִקְרֵי, וְאֵין מַיִם אֶלָּא תּוֹרָה, וְאֵין תּוֹרָה אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, עַד דַּהֲווֹ אַזְלֵי בְּמַדְבְּרָא, אִתְגְּלֵי עָלַיְיהוּ רְשׁוּתָא אַחֲרָא, דִּשְׁאַר עַמִּין, הַהוּא דְּשָׁלִיט בְּמַדְבְּרָא, וְאִעֲרָעוּ בְּהוּ תַּמָּן. חָמוּ יִשְׂרָאֵל, דְּלָא הֲוָה הַהוּא זִיוָא יְקָרָא דְּמַלְכֵּיהוֹן, הֲדָא הוּא דִּכְתִּיב, וַיָּבֹאוּ מָרָתָה וְלֹא יָכְלוּ לִשְׁתּוֹת מַיִם מִמָּרָה. מַאי טַעְמָא. כִּי מָרִים הֵם, לָא אִתְבְּסָם נַפְשַׁיְיהוּ כְּקַדְמִיתָא. וְלא עוֹד אֶלָּא דְּאָתֵי לְקַטְרְגָא עָלַיְיהוּ.</p>\n<p>מַה כְּתִיב, וְיִצְעַק אֶל יְיָ' וַיּוֹרֵהוּ יְיָ' עֵץ, <Nonei></i>וְאֵין עֵץ אֶלָּא תּוֹרָה, דִּכְתִּיב, (משלי ג׳:י״ח) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. וְאֵין תּוֹרָה, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא. רִבִּי אַבָּא אָמַר, אֵין עֵץ אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (דברים כ׳:י״ט) כִּי הָאָדָם עֵץ הַשָּׂדֶה, עֵץ הַשָּׂדֶה וַדַּאי, דָּא עֵץ שָׂדֶה דְּתַפּוּחִין קַדִּישִׁין. וְכַד אִתְגְּלֵי זִיו יְקָרָא דְּמַלְכֵּהוֹן עָלַיְיהוּ, כְּדֵין וַיַּשְׁלֵךְ אֶל הַמַּיִם וַיִּמְתְּקוּ הַמָּיִם. מַאי וַיִּמְתְּקוּ הַמָּיִם. דְּקַטֵּיגוֹרָא אִתְעָבִיד סַנֵּיגוֹרָא.</p>\n<p>אָמַר רִבִּי אַבָּא, תָּא חֲזֵי בְּקַדְמִיתָא כַּד עָאלוּ יִשְׂרָאֵל בְּקַיָימָא דְּקוּדְשָׁא בְּרִיךְ הוּא, לָא עָאלוּ כְּדְקָא יֵאוֹת. מַאי טַעֲמָא. בְּגִין דְּאִתְגְּזָרוּ וְלָא אִתְפְּרָעוּ, וְלָא אִתְגַּלְּיָיא רְשִׁימָא קַדִּישָׁא. כֵּיוָן דְּמָטוּ הָכָא, מַה כְּתִיב, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט. תַּמָּן עָאלוּ יִשְׂרָאֵל בִּתְרֵין חוּלָקִין קַדִּישִׁין, בְּהַהוּא גִּלּוּיָא דְּאִתְגַּלְיָא רְשִׁימָא דִּלְהוֹן, וְאִקְרוּן חֹק וּמִשְׁפָּט. חֹק: כְּמָה דְּאַתְּ אָמַר (משלי כא) וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ. וּמִשְׁפָּט: כְּמָה דְּאִתְּמַר (תהילים פ״א:ה׳) מִשְׁפַּט לֵאלֹהֵי יַעֲקֹב. וְשָׁם נִסָּהוּ, בְּהַהוּא אָת קַדִּישָׁא.</p>"],[9520011626,"<p>כְּמָה דְאַתְּ אָמֵר, כִּי חֹק לְיִשְׂרָאֵל הוּא. בְּסִפְרָא דְּרַב יִיִבָא סָבָא, אָמַר מִלָּה עַל הַהוּא חוּטְרָא קַדִּישָׁא. (שמות ט״ו:כ״ו) וַיֹּאמֶר אִם שָׁמוֹעַ תִּשְׁמַע לְקוֹל יְיָ' אֱלֹהֶיךָ. וַיֹּאמֶר, מַאי וַיֹּאמֶר. לָא כְּתִיב מַאן קָאָמַר דָּא. אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא אָמַר. רִבִּי חִזְקִיָּה אָמַר, שַׁמְעֵינָן (נ\"א משמע) אֲמִירָה סְתָם, מֵאֲמִירָה סְתָם. דִּכְתִּיב, (שמות כ״ד:א׳) וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל יְיָ'. אָמַר, לָא כְּתִיב מַאן קָאָמַר. אוּף הָכָא וַיֹּאמֶר סְתָם, וְלָא כְּתִיב מַאן קָאָמַר.</p>\n<p>אָמַר רִבִּי יוֹסֵי, מַשְׁמַע דִּכְתִּיב, וְיִצְעַק אֶל יְיָ' וַיּוֹרֵהוּ יְיָ' עֵץ, מֵהָכָא מַשְׁמַע וַיֹּאמֶר, וּמַשְׁמַע מַאן אָמַר מִלָּה. לְקוֹל יְיָ' אֱלהֶיךָ, לְקוֹלִי מִבָּעֵי לֵיהּ. אֶלָּא לְהַהוּא קוֹל דְּעָאלוּ בֵּיהּ.</p>\n<p>אָמַר רִבִּי אַבָּא, בָּתַר דְּאִתְגַּלְיָא בְּהוּ רְשִׁימָא קַדִּישָׁא, עָאלוּ בִּתְרֵין חוּלָקִין קַדִּישִׁין, כְּמָה דְּאִתְּמַר, וְכֵיוָן דְּעָאלוּ בְּאִלֵּין תְּרֵין, עָאלוּ בְּאִלֵּין תְּרֵין חוּלָקִין אַחֲרָנִין, דְּכַד יִסְתַּלְּקוּן בְּאִלֵּין תְּרֵין אַחֲרָנִין, יִתְחַבְּרוּן בְּאִלֵּין, וְלָא מִמַּנְעֵי בִּרְכָּאן, וּבְּגִין כָּךְ, בְּאִלֵּין מָטוּ בִּרְכָּאן, (ובגיני כך באלין מטין) עַד מַלְכָּא קַדִּישָׁא.</p>\n<p>וּמֵאַתְרֵיהּ דִּקְרָא אִשְׁתְּמַע מִלָּה, דִּכְתִּיב, וַיֹּאמֶר אִם שָׁמוֹעַ תִּשְׁמַע. וַיֹּאמֶר: דָּא מַלְכָּא קַדִּישָׁא. וּמַאי קָאָמַר, אִם שָׁמוֹעַ תִּשְׁמַע לְקוֹל יְיָ' אֱלהֶיךָ, כְּמָה דְאַתְּ אָמֵר (דברים ד׳:כ״ד) כִּי יְיָ' אֱלֹהֶיךָ אֵשׁ אוֹכְלָה הוּא, דָּא כְּנֶסֶת יִשְׂרָאֵל. וְהַיָּשָׁר בְּעֵינָיו תַּעֲשֶׂה: דָּא צַדִּיק. וְהַאֲזַנְתָּ לְמִצְוֹתָיו: דָּא נְצַח. וְשָׁמַרְתָּ כָּל חֻקָּיו: דָּא הוֹד. כֵּיוָן דְּעָאלוּ בְּאִלֵּין, הָא מָטוּ לְמַלְכָּא קַדִּישָׁא. לְבָתַר מַה כְּתִיב, כָּל הַמַּחֲלָה אֲשֶׁר שַׂמְתִּי בְּמִצְרַיִם לא אָשִׂים עָלֶיךָ כִּי אֲנִי יְיָ' רוֹפְאֶךָ. כִּי אֲנִי יְיָ': דָּא מַלְכָּא קַדִּישָׁא.</p>\n<p>אִשְׁתְּמַע, דְּכָל מַאן דְּנָטִיר לְהַאי רְשִׁימָא קַדִּישָׁא, מִנֵיהּ סָלִיק עַד מַלְכָּא קַדִּישָׁא עִלָּאָה. מַאי מַשְׁמַע. מַשְׁמַע אִינּוּן תְּרֵין, דְּאִתְכְּנַשׁ בְּהוּ זַרְעָא, וּמָשַׁח רְבוּת קוּדְשָׁא, דְּשַׁדְיָין לֵיהּ בְּפוּם אָמָה, (ועל דא) אִתְקַשָּׁרוּ כַּחֲדָא, וּמַלְכָּא עִלָּאָה עָלַיְיהוּ, וְאִתְקַשָּׁרוּ בֵּיהּ. וְעַל כַּךְ, מַאן דְּעָאל בְּאִלֵּין תְּרֵין, וְנָטִיר לוֹן, אִתְקָשָּׁר בִּתְרֵין אַחֲרָנִין, וְעָאל בְּהוּ, וּכְדֵין מָטֵי לְמַלְכָּא קַדִּישָׁא.</p>\n<p>אָמַר רִבִּי יִצְחָק, וַדַּאי מַאן דְּזָכֵי בְּצַדִיק, זָכֵי בְּנֶצַח וְהוֹד, וְאִלֵּין אִינּוּן תְּלָתָא, דְּאִתְבָּרְכָא בְּהוּ כְּנֶסֶת יִשְׂרָאֵל. וּמַאן דְּזָכוּ בְּהוּ, זָכֵי בְּמַלְכָּא קַדִּישָׁא, וְעָאל בְּכֻלְּהוּ אַרְבְּעָה.</p>\n<p>וְלָקֳבְלֵי אַרְבְּעָה אִלֵּין, נְטִירוּ לְהַאי רְשִׁימָא קַדִּישָׁא, מֵאַרְבַּע מִלִּין: נְטִירוּ דִּכְנְסֶת יִשְׂרָאֵל, אִסְתַּמְּרוּתָא דְּנִדָּה. נְטִירוּ דְּצַדִּיק, אִסְתַּמְּרוּתָא דְּשִׁפְחָה. נְטִירוּ דְּנֶצַח, אִסְתַּמְּרוּתָא דְּבַת עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. נְטִירוּ דְּהוֹד, אִסְתַּמְּרוּתָא דְּזוֹנָה. וְעַל דָּא לְקוֹל יְיָ' אֱלהֶיךָ, דָּא כְּנֶסֶת יִשְׂרָאֵל.</p>\n<p>בַּמֶּה זָכָאן יִשְׂרָאֵל לְקַבְּלָא אַפֵּי שְׁכִינְתָּא, בְּאִסְתַּמְּרוּתָא מִן נִדָּה. וְעַל דָּא כְּתִיב, (ויקרא י״ח:י״ט) וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לא תִקְרַב לְגַלּוֹת עֶרְוָתָהּ. מַאי לְגַלּוֹת עֶרְוָתָהּ דָּא כְּנֶסֶת יִשְׂרָאֵל. וּבְהַאי אֲחִידָן וּמִתְקַשְּׁרָן מִלִּין אַחֲרָנִין, דִּכְנֶסֶת יִשְׂרָאֵל אִתְקַשְּׁרַת בְּהוּ. וְהָא אוּקְמוּהָ מִלֵּי.</p>\n<p>וְהַיָּשָׁר בְּעֵינָיו תַּעֲשֶׂה: דָּא צַדִּיק. כְּמָה דִּכְתִּיב, (תהלים לה) עֵינֵי יְיָ' אֶל צַדִּיקִים, לְאִסְתַּמְּרָא מִשִּׁפְחָה. <Nonei></i>וְהָא אוֹקִימְנָא מִלֵּי. דִּכְתִּיב, (משלי ל׳:כ״ג) וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ, דְּגָרִים לַצַּדִּיק דְּאִתְדַּבָּק בְּשִׁפְחָה. וְהַאֲזַנְתָּ לְמִצְוֹתָיו: דָּא נֶצַח, לְאִסְתַּמְּרָא (דלא שקר ביה) דְּלָא יֵעוּל רְשִׁימָא דָּא בְּבַת אֵל נֵכָר, וְלא יְשַׁקֵּר בֵּיהּ בְּנֶצַח. דִּכְתִּיב, (שמואל א ט״ו:כ״ט) וְגַם נְצַח יִשְׂרָאֵל לא יְשַׁקֵּר. וּמַאן דְּנָטִיר הַאי, קִיֵּים מִצְוֹתָיו, דִּכְתִּיב, (שמות לה) כִּי לא תִשְׁתַּחֲוֶה לְאֵל אַחֵר. וְשָׁמַרְתָּ כָּל חֻקָּיו: דָּא הוֹד, לְאִסְתַּמְּרָא מִן זוֹנָה.</p>\n<p>וְאַזְלָא הָא, כְּמָה דְּתָנֵינָן, אָמַר רִבִּי יְהוּדָה, מַאי דִּכְתִּיב (תהילים מ״ה:ד׳) חֲגוֹר חַרְבְּךָ עַל יָרֶךְ גִּבּוֹר הוֹדְךָ וַהֲדָרֶךָ. אֶלָּא, כָּל מַאן דִּמְזָרֵז גַּרְמֵיהּ, וְשַׁוֵּי דְּחִילוּ דְּחַרְבָּא שִׁנָּנָא תַּקִּיפָא לָקֳבְלֵיהּ. עַל יָרֶךְ, מַאי עַל יָרֶךְ. דָּא רְשִׁימָא קַדִּישָׁא. כְּמָה דְאַתְּ אָמֵר, (בראשית כ״ד:ב׳) שִׂים נָא יָדְךָ תַּחַת יְרֵכִי.</p>\n<p>דָּבָר אַחֵר חֲגוֹר חַרְבְּךָ, כְּלוֹמַר, זָרֵז וְאַתְקִיף יִצְרְךָ בִּישָׁא, דְּאִיהוּ חַרְבְּךָ. עַל יָרֶךְ, עַל הַהוּא רְשִׁימָא קַדִּישָׁא לְנַטְרָא לֵיהּ. וְאִי נָטַר לֵיהּ, כְּדֵין אִקְרֵי גִּבּוֹר, וְקוּדְשָׁא בְּרִיךְ הוּא אַלְבִּישׁ לֵיהּ בִּלְבוּשׁוֹי, וּמַאן לְבוּשׁוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא. הוֹד וְנֶצַח. (נ\"א והדר) דִּכְתִּיב, (תהילים ק״ד:א׳) הוֹד וְהָדָר לָבָשְׁתָּ. אוּף הָכָא הוֹדְךָ וַהֲדָרֶךָ, וּכְדֵין אִתְדַּבַּק בַּר נָשׁ בְּמַלְכָּא קַדִּישָׁא כְּדְקָא יֵאוֹת.</p>\n<p>מִכָּאן וּלְהָלְאָה, כָּל הַמַּחֲלָה אֲשֶׁר שַׂמְתִּי בְּמִצְרַיִם לא אָשִׂים עָלֶיךָ כִּי אֲנִי יְיָ' רוֹפְאֶךָ. דָּא מַלְכָּא קַדִּישָׁא, וְעַל דָּא אַזְהַר לוֹן עַל הַהוּא מִלָּה מַמָּשׁ, דְּיָהַב וְרָשִׁים בְּהוּ, וְלָא יַתִּיר וְעַד כְּעַן לָא אִתְיְיהִיבַת לְהוּ אוֹרַיְיתָא, אֶלָּא כֵּיוָן דִּכְתִּיב, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט, מִיָּד וַיֹּאמֶר אִם שָׁמוֹעַ תִּשְׁמַע וְגוֹ'.</p>\n<p>תָּא חֲזֵי, כַּד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְאַזְהָרָא לְיִשְׂרָאֵל, עַל אוֹרַיְיתָא, בְּכַמָּה מִלִּין מָשִׁיךְ לְהוּ, בְּכַמָּה מְשִׁיכָן דַּחֲבִיבוּתָא, כְּבַר נָשׁ דְּמָשִׁיךְ בְּרֵיהּ לְבֵי רַב. וְתָּא חֲזֵי, לָא בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמֵיהַב לְהוּ אוֹרַיְיתָא, עַד דְּקָרִיבוּ בַּהֲדֵיהּ. וּבַמֶּה קְרִיבוּ בַּהֲדֵיהּ, בְּגִלּוּיָא דִּרְשִׁימָא דָּא, כְּמָה דְּאִתְּמַר.</p>\n<p>אָמַר ר' יְהוּדָה, לָא קְרִיבוּ יִשְׂרָאֵל לְטוּרָא דְּסִינַי, עַד דְּעָאלוּ בְּחוּלָקָא דְּצַדִּיק, וְזָכוּ בֵּיהּ. מְנָלָן, דִּכְתִּיב, (שמות י״ט:א׳) בַּיּוֹם הַזֶּה בָּאוּ מִדְבָּר סִינַי, בַּיּוֹם הַזֶּהִ מַמָּשׁ פרשת המן קִוִּינוּ לוֹ וגוֹ'.</p>"],[9520011627,"<p><Noneb>[פרשת המן]</b> (שמות ט״ז:ד׳) וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. רִבִּי יְהוּדָה פָּתַח וְאָמַר, (תהילים מ״א:ב׳) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְּטֵהוּ יְיָ'. הַאי קְרָא אוֹקִימְנָא לֵיהּ, בְּשַׁעֲתָא דְּבַר נָשׁ שָׁכִיב בְּבֵי מַרְעֵיהּ, הָא אִתְּפַס בְּאַטְרוֹנְיָא דְּמַלְכָּא, רֵישֵׁיהּ בְּקוּלְרָא, רַגְלוֹי בְּכוּפְסִירִין, (ס\"א בטפסרא) כַּמָּה חֵילִין נַטְרִין לֵיהּ, מֵהַאי גִּיסָא, וּמֵהַאי גִּיסָא. שַׁיְיפוֹי כֻּלְּהוּ בְּדוֹחֲקָא, מַגִּיחִין אִלֵּין בְּאִלֵּין. מֵיכְלָא אִתְעָדֵי מִנֵּיהּ.</p>\n<p>בְּהַהוּא זִמְנָא, פַּקְדִין עָלֵיהּ אַפּוֹטְרוֹפָא, לְמֵילַף עָלֵיהּ זְכוּת קָמֵי מַלְכָּא, דִּכְתִּיב, (איוב ל״ג:כ״ג) אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף. בְּהַהִיא שַׁעֲתָא, זַכָּאָה חוּלָקֵיהּ דְּבַּר נָשׁ דְּעָאל עָלֵיהּ, וְאוֹלִיף לֵיהּ אָרְחָא, לְשֵׁיזָבוּתֵיהּ מִן דִּינָא. הֲדָא הוּא דִכְתִיב אַשְׁרֵי מַשְׂכִּיל אֶל דָּל.</p>\n<p>וְהֵיךָ יָכִיל לְשֵׁזָבָא לֵיהּ, לְמֵילַף לֵיהּ אָרְחוֹי דְּחַיֵּי, לְאָתָבָא לְקָמֵי מָארֵיהּ, כְּדֵין אִתְעָבִיד אַפּוֹטְרוֹפוֹסָא עָלֵיהּ לְעֵילָּא. מַאי אַגְרֵיהּ. בְּיוֹם רָעָה יְמַלְּטֵהוּ יְיָ'. דָּבָר אַחֵר, אַשְׁרֵי מַשְׂכִּיל אֶל דָּל, כַּמָּה תַּקִּיפָא אַגְרָא דְּמִסְכְּנָא, קָמֵי קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>אָמַר רִבִּי חִיָּיא, תָּוַוהְנָא עַל הַאי קְרָא דִּכְתִּיב, (תהילים ס״ט:ל״ד) כִּי שׁוֹמֵעַ אֶל אֶבְיוֹנִים יְיָ', וְכִי אֶל אֶבְיוֹנִים שׁוֹמֵעַ וְלֹא לְאַחֲרָא. אָמַר רִבִּי שִׁמְעוֹן, בְּגִין דְּאִינּוּן קְרִיבִין יַתִּיר לְמַלְכָּא, דִּכְתִּיב, (תהילים נ״א:י״ט) לֵב נִשְׁבָּר וְנִדְכֶּה אֱלהִים לא תִבְזֶה. וְלֵית לָךְ בְּעָלְמָא, דְּאִיהוּ תָּבִיר לִבָּא כְּמִסְכְּנָא. תּוּ אָמַר רִבִּי שִׁמְעוֹן, תָּא חֲזֵי, כָּל אִינּוּן בְּנִי עָלְמָא, אִתְחַזְיָין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, בְּגוּפָא וְנַפְשָׁא, וּמִסְכְּנָא לָא אִתְחָזֵי אֶלָּא בְּנַפְשָׁא בִּלְחוֹדוֹי, וְקוּדְשָׁא בְּרִיךְ הוּא קָרִיב לְנַפְשָׁא יַתִּיר מִגּוּפָא.</p>\n<p>מִסְכְּנָא חַד הֲוָה בִּשְׁבִבוּתֵיהּ דְּר' יֵיסָא, וְלָא הֲוָה מַאן דְּאַשְׁגַּח בֵּיהּ, וְהוּא הֲוָה אַכְסִיף, וְלָא תַּקִּיף בִּבְנֵי נָשָׁא, <Nonei></i>יוֹמָא חַד חָלַּשׁ, עָאל עָלֵיהּ רִבִּי יֵיסָא, שָׁמַע חַד קָלָא דְּאָמַר, טִילְקָא טִילְקָא, הָא נַפְשָׁא פַּרְחָא גַּבָּאי, וְלָא מָטוּ יוֹמוֹי. וַוי לִבְנִי מָתֵיהּ דְּלָא אִשְׁתְּכַח בְּהוּ דְּיָתִיב נַפְשֵׁיהּ לְגַבֵּיהּ. קָם רִבִּי יֵיסָא, שַׁדֵּי בְּפוּמֵיהּ, מַיָּא דְּגַרְגְּרִין, אַפוּתָא דְּקוּנְטָא (ס\"א דקופתא) אִתְבְּזַע זִיִעָא בְּאַנְפּוֹי, וְתָב רוּחֵיהּ לְגַבֵּיהּ.</p>\n<p>לְבָתַר אָתָא וְשָׁאִיל לֵיהּ, אָמַר חַיֶּיךָ רִבִּי, נַפְשָׁא נַפְקַת מִנַּאי, וּמָטוּ לָהּ קָמֵי כּוּרְסְיָיא דְּמַלְכָּא, וּבָעָת לְאִשְׁתַּאֲרָא תַּמָּן, אֶלָּא דְּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְזַכָּאָה לָךְ, וְאַכְרִיזוּ עָלָךְ, זַמִּין הוּא רִבִּי (ויקרא ע\"ט ע\"א וקמ\"ד ע\"א) יֵיסָא, לְסַלְּקָא רוּחֵיהּ, וּלְאִתְקְשְּׁרָא בְּחַד אִדְרָא קַדִּישָׁא דִּזְמִינִין חַבְרַיָּיא לְאִתְּעָרָא בְּאַרְעָא, וְהָא אַתְקִינוּ תְּלַת כֻּרְסְיָאן, דְּקַיְימִן לָךְ וּלְחַבְרָךְ. מֵהַהוּא יוֹמָא הֲווֹ מַשְׁגִּיחִין בֵּיהּ בְּנֵי מָתֵיהּ.</p>\n<p>תּוּ, מִסְכְּנָא אַחֲרָא אַעְבָר קָמֵיהּ דְּר' יִצְחָק, וַהֲוָה בִּידֵיהּ פְּלַג מְעָה דְּכֶסֶף. אָמַר לֵיהּ לְרִבִּי יִצְחָק, אַשְׁלִים לִי וְלִבְנַי וְלִבְנָתַי נַפְשָׁאָן. אָמַר לֵיהּ וְהֵיךְ אַשְׁלִים נַפְשַׁיְיכוּ, דְּהָא לָא אִשְׁתְּכַח גַּבָּאי בַּר פְּלַג מְעָה. אָמַר לֵיהּ, בְּדָא אַשְׁלִימְנָא, בִּפְלַג אַחֲרָא דְּאִית גַּבָּאי, אַפְקֵיהּ וְיָהֲבֵיהּ לֵיהּ.</p>\n<p>אַחְזִיאוּ לֵיהּ בְּחֶלְמֵיהּ, דְּהֲוָה אַעְבָר בִּשְׂפָתָא דְּיַמָּא רַבָּא, וּבָעָאן לְמִשְׁדְּיֵיהּ בְּגַוֵּויהּ, (ויחי רי\"ח ע\"א) חָמָא לְרִבִּי שִׁמְעוֹן, דְּהֲוָה אוֹשִׁיט יְדוֹי לָקֳבְלֵיהּ, וְאָתֵי הַהוּא מִסְכְּנָא וְאַפְקֵיהּ, וְיָהֲבֵיהּ בִּידוֹי דְּרִבִּי שִׁמְעוֹן, וְאִשְׁתֵּזִיב. כַּד אִתְּעַר, נָפַל בְּפוּמֵיהּ, הַאי קְרָא, (תהילים מ״א:ב׳) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְּטֵהוּ יְיָ'.</p>\n<p>וְתָא חֲזֵי, כָּל יוֹמָא וְיוֹמָא, נָטִיף טַלָּא מֵעַתִּיקָא קַדִּישָׁא לִזְעֵיר אַפִּין, וּמִתְבָּרְכָאן כָּל חֲקַל תַּפּוּחִין קַדִּישִׁין. וּמֵהַהוּא טַלָּא אַנְגִּיד לְאִינוּן דִּלְתַתָּא, וּמַלְאָכִין קַדִּישִׁין אִתְּזָנוּ מִנֵּיהּ, כָּל חַד וְחַד כְּפוּם מֵיכָלֵיהּ, הֲדָא הוּא דִכְתִיב, (תהילים ע״ח:כ״ה) לֶחֶם אַבִּירִים אָכַל אִישׁ, וּמֵהַהוּא מְזוֹנָא אָכְלוּ יִשְׂרָאֵל בְּמַדְבְּרָא.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, כַּמָּה בְּנֵי נָשָׁא מִתְּזָנִין בְּהַאי זִמְנָא מִנֵּיהּ, וּמַאן אִינּוּן. אִלֵּין חַבְרַיָּיא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, יוֹמֵי וְלֵילֵי. וְכִי סַלְּקָא דַּעְתָּךְ מֵהַהוּא מְזוֹנָא מַמָּשׁ. לָא. אֶלָּא כְּעֵין הַהוּא מְזוֹנָא מַמָּשׁ, דְּשָׁקִיל עַל חַד תְּרֵין.</p>\n<p>תָּא חֲזֵי, יִשְׂרָאֵל כַּד עָאלוּ וְאִתְדְּבָקוּ בְּמַלְכָּא קַדִּישָׁא, בְּגִין גִּלּוּיָא דִּרְשִׁימָא קַדִּישָׁא, כְּדֵין זָכוּ לְמֵיכַל נַהֲמָא אַחֲרָא עִלָּאָה, יַתִּיר מִמַּה דְּהֲוָה בְּקַדְמִיתָא. בְּקַדְמִיתָא כַּד נָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, עָאלוּ בְּנָהֲמָא, דְּאִקְרֵי מַצָּה, וְהַשְׁתָּא זָכוּ, וְעָאלוּ לְמֵיכַל נַהֲמָא אַחֲרָא עִלָּאָה יַתִּיר, מֵאֲתָר עִלָּאָה, דִּכְתִּיב הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. מִן הַשָּׁמָיִם מַמָּשׁ. וּבְהַהוּא זִמְנָא אִשְׁתְּכַח לְהוּ לְיִשְׂרָאֵל. מֵאֲתָר דָּא. חַבְרַיָּיא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, מֵאֲתָר אַחֲרָא עִלָּאָה יַתִּיר אִתְּזָנוּ. מַאי הוּא. כְּמָה דִּכְתִּיב, (קהלת ז׳:י״ב) הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. אֲתָר עִלָּאָה יַתִּיר.</p>\n<p>אֲמַר לֵיהּ ר' אֶלְעָזָר, אִי הָכִי, אֲמַאי חַלְשָׁא נַפְשַׁיְיהוּ יַתִּיר מִשְּׁאָר בְּנֵי עָלְמָא, דְּהָא שְׁאַר בְּנֵי נָשָׁא, בְּחֵילָא וְתּוּקְפָּא יַתִּיר אִתְחָזוּן לְאִשְׁתַּכְּחָא. (ס\"א אינון יתיר) אָמַר לֵיהּ יֵאוֹת שָׁאִילְתָּא.</p>\n<p>תָּא חֲזֵי, כָּל מְזוֹנִי דִּבְנֵי עָלְמָא מִלְּעֵילָּא קָא אַתְיָין. הַהוּא מְזוֹנָא דְּאָתֵי מִן שְׁמַיָּא וְאַרְעָא, דָּא מְזוֹנָא דְּכָל עָלְמָא, וְהוּא מְזוֹנָא דְּכוֹלָא, וְהוּא מְזוֹנָא גַּס וְעָב. וְהַהוּא מְזוֹנָא דְּאָתֵי יַתִּיר מֵעֵילָּא, הוּא מְזוֹנָא יַתִּיר דָּקִיק, קָאַתְיַא מֵאֲתָר דְּדִינָא אִשְׁתְּכַח, וְדָא הוּא מְזוֹנָא דְּאַכְלוּ יִשְׂרָאֵל כַּד נָפְקוּ מִמִּצְרַיִם. (יתיר דקיקא) מְזוֹנָא דְּאִשְׁתְּכַח לְהוּ לְיִשְׂרָאֵל, בְּהַהוּא זִמְנָא בְּמַדְבְּרָא, מֵאֲתָר עִלָּאָה דְּאִקְרֵי שָׁמַיִם, הוּא מְזוֹנָא יַתִּיר דְּקִיקָא, דְּעָיִיל יַתִּיר לְנַפְשָׁא מִכֹּלָּא, וּמִתְפְּרַשׁ יַתִּיר מִגּוּפָא, וְאִקְרֵי לֶחֶם אַבִּירִים.</p>\n<p>מְזוֹנָא עִלָּאָה יַתִּיר מִכֹּלָּא, הוּא מְזוֹנָא דְּחַבְרַיָּיא, אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, דְּאַכְלֵי מְזוֹנָא דְּרוּחָא וְנִשְׁמְתָא, וְלָא אַכְלֵי מְזוֹנָא דְּגוּפָא כְּלָל, וְהַיְינוּ מֵאֲתָר עִלָּאָה יַקִּירָא עַל כֹּלָּא, וְאִקְרֵי חָכְמָה. בְּגִינֵי כַּךְ חָלִישׁ גּוּפָא דְּחַבְרַיָּיא, יַתִּיר מִבְּנֵי עָלְמָא, דְּהָא לָא אַכְלֵי מְזוֹנָא דְּגוּפָא כְּלָל. וְאַכְלֵי מְזוֹנָא דְּרוּחָא וְנִשְׁמְתָא, מֵאֲתָר רְחִיקָא עִלָּאָה, <Nonei></i>יַקִּירָא מִכֹּלָּא. וּבְגִינֵי כַּךְ הַהוּא מְזוֹנָא דָּקִיק מִן דְּקִיקָא, יַתִּיר מִכֹּלָּא. זַכָּאָה חוּלָקֵיהוֹן, הֲדָא הוּא דִכְתִיב, (קהלת ז׳:י״ב) הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. זַכָּאָה חוּלָקָא דְּגוּפָא, דְּיָכִיל לְאִתְּזָנָא בִּמְזוֹנָא דְּנַפְשָׁא.</p>\n<p>אֲמַר לֵיהּ ר' אֶלְעָזָר, וַדַּאי הָכִי הוּא. אֲבָל בְּהַאי זִמְנָא, אֵיךְ אִשְׁתַּכְּחֵי מְזוֹנֵי אִלֵּין. אֲמַר לֵיהּ וַדַּאי יֵאוֹת שָׁאִילְתָּא. תָּא חֲזֵי, וְדָא הוּא בְּרִירוּ דְּמִלָּה, מְזוֹנָא קַדְמָאָה, הוּא מְזוֹנָא דְּכָל עָלְמָא, הַהוּא דְּאַתְיָא מִן שְׁמַיָּא וְאַרְעָא, וְהוּא מְזוֹנָא דְּגוּפָא. (ס\"א דכלא)</p>\n<p>מְזוֹנָא דְּהוּא עִלָּאָה מִנֵּיהּ, הַהוּא דְּאִיהוּ דְּקִיקָא יַתִּיר, וְאָתָא מֵאֲתָר דְּדִינָא שַׁרְיָא, דְּאִקְרֵי צֶדֶק, וְדָא הוּא מְזוֹנָא דְּמִסְכְּנֵי. וְרָזָא דְּמִלָּה, מַאן דְּאַשְׁלִים לְמִסְכְּנָא, אַשְׁלִים לֵיהּ אָת חַד, וְאִתְעָבִיד צְדָקָה, וְרָזָא דָּא (משלי י״א:י״ז) גּוֹמֵל נַפְשׁוֹ אִישׁ חֶסֶד. גְּמִילוּת חֲסָדִים מַשְׁמַע, דְּהָא בְּדִינָא שַׁרְיָא, וְאַשְׁלִים לֵיהּ חֶסֶד, כְּדֵין הוּא רַחֲמֵי.</p>\n<p>מְזוֹנָא עִלָּאָה יַתִּיר מֵאִלֵּין, הוּא מְזוֹנָא עִלָּאָה וְיַקִּירָא, מֵאֲתָר דְּאִקְרֵי שָׁמַיִם, וְהוּא דָּקִיק מִכֻּלְּהוּ, וְהוּא מְזוֹנָא דִּבְנֵי מַרְעֵי, הֲדָא הוּא דִכְתִיב, (תהילים מ״א:ד׳) יְיָ' יִסְעָדֶנּוּ עַל עֶרֶשׂ דְּוָי כָּל מִשְׁכָּבוֹ הָפַכְתָּ בְחָלְיוֹ. יְיָ', דַּיְיקָא, מַאי טַעְמָא. בְּגִין דְּהָנֵי בְּנֵי מַרְעֵי, לָא אִתְּזְנֵי אֶלָּא בְּהַהוּא דְּקוּדְשָׁא בְּרִיךְ הוּא מַמָּשׁ. (ומאי איהו, חלב ודם. הדא הוא דכתיב (יחזקאל מה) להקריב לי חלב ודם. ודא הוא מזונא מאתר דאקרי שמים, והוא יקירא ועילאה דקיק מכלא)</p>\n<p>מְזוֹנָא עִלָּאָה קַדִּישָׁא וְיַקִּירָא דָּא הוּא מְזוֹנֵי דְּרוּחִין וְנִשְׁמָתִין, וְהוּא מְזוֹנָא דַּאֲתָר רְחִיקָא עִלָּאָה, (ס\"א מההוא אתר דאקרי נועם יי'.)</p>\n<p>וְיַקִּירָא מִכֹּלָּא, הוּא מְזוֹנָא דְּחַבְרַיָּיא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, וְהוּא מְזוֹנָא דְּאָתֵי מֵחָכְמָה עִלָּאָה. מַאי טַעְמָא מֵאֲתָר דָּא. בְּגִין דְּאוֹרַיְיתָא נַפְקָא (בראשית מ\"ז ע\"ב, ויקרא קפ\"ו ע\"ב וקצ\"ב ע\"ב) מֵחָכְמָה עִלָּאָה, וְאִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, עַיְילֵי בְּעִקָרָא דְּשָׁרְשָׁהָא, וְעַל דָּא, מְזוֹנָא דִּלְהוֹן, מֵהַהוּא אֲתָר עִלָּאָה קַדִּישָׁא קָא אַתְיָא.</p>\n<p>אָתָא ר' אֶלְעָזָר, וְנָשִׁיק יְדוֹי. אָמַר, זַכָּאָה חוּלָקִי דְּקָאִימְנָא בְּמִלִּין אִלֵּין. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא יְמָמָא וְלֵילֵי, דְּזָכֵי לוֹן בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי, דִּכְתִּיב, (דברים ל׳:כ׳) כִּי הוּא חַיֶּיךָ וְאוֹרֶךְ יָמֶיךָ.</p>\n<p>(שמות ט״ז:ד׳) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. רִבִּי יוֹסֵי פָּתַח, (תהילים קמ״ה:ט״ז) פּוֹתֵחַ אֶת יָדֶךָ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן. מַה כְּתִיב לְעֵילָּא, עֵינֵי כֹל אֵלֶיךָ יְשַׂבֵּרוּ. כָּל אִינּוּן בְּנִי עָלְמָא, מְצַפָּאן וְזַקְפָאן עַיְינִין לְקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין כַּךְ, (ס\"א אבל) כָּל אִינּוּן בְּנֵי מְהֵימָנוּתָא בָּעָאן (ס\"א אצטריכן למבעי) בְּכָל יוֹמָא וְיוֹמָא, לְשָׁאָלָא מְזוֹנַיְיהוּ מִּקוּדְשָׁא בְּרִיךְ הוּא, וּלְצַלָּאָה צְלוֹתֵהוֹן עָלֵיהּ.</p>\n<p>מַאי טַעְמָא. בְּגִין דְּכָל מַאן דִּמְצַלֵי צְלוֹתֵיהּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא עַל מְזוֹנֵיהּ, גָּרִים דְּיִתְבָּרֵךְ כָּל יוֹמָא עַל יְדוֹי, הַהוּא אִילָנָא דְּמָזוֹן דְּכֹלָּא בֵּיהּ. (וטעמא דמלה (תהילים ס״ח:כ׳) ברוך ה' יום יום) וְאַף עַל גַּב דְּאִשְׁתְּכַח עִמֵּיהּ, בָּעֵי לְמִשְׁאַל קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וּלְצַלָּאָה צְלוֹתָא עַל מְזוֹנָא כָּל יוֹמָא, בְּגִין דְּיִשְׁתְּכָחוּ עַל יְדוֹי בִּרְכָּאן כָּל יוֹמָא וְיוֹמָא לְעֵילָּא, וְדָא הוּא בָּרוּךְ יְיָ' יוֹם יוֹם.</p>\n<p>ועַל דָּא, לָא לִבָעֵי לֵיהּ לֶאֱינָשׁ לְבַשְּׁלָא מְזוֹנָא, מִן יוֹמָא לְיוֹמָא אַחֲרִינָא, דְּלָא לְעַכֵּב יוֹמָא לְיוֹמָא אַחֲרָא. הֲדָא הוּא דִכְתִיב וְיָצָא הָעָם וְלָקְטוּ דְּבַר יוֹם בְּיוֹמוֹ. יוֹם בְּיוֹמוֹ, דַּיְיקָא. בַּר מֵעֶרֶב שַׁבָּת לְשַׁבָּת, כְּמָה דְּאוֹקִימְנָא. וּכְדֵין אִשְׁתְּכַח קוּדְשָׁא בְּרִיךְ הוּא מָלֵא בִּרְכָּאן בְּכָל יוֹמָא. וּכְדֵין כְּתִיב פּוֹתֵחַ אֶת יָדֶךָ וְגוֹ'. מַאי רָצוֹן. הַהוּא רָצוֹן דְּאִשְׁתְּכַח מֵעַתִּיקָא קַדִּישָׁא, וְנָפִיק מִנֵּיהּ רָצוֹן, לְאִשְׁתַּכְּחָא מְזוֹנֵי לְכֹלָּא. וּמַאן דְּשָׁאִיל מְזוֹנֵי בְּכָל יוֹמָא וְיוֹמָא, הַהוּא אִקְרֵי בְּרָא מְהֵימָנָא, בְּרָזָא דִּבְגִינֵיהּ מִשְׁתַּכְחָן בִּרְכָּאן לְעֵילָּא.</p>\n<p>ר' אַבָּא פָּתַח וְאָמַר, (תהילים קמ״ז:י״א) רוֹצֶה יְיָ' אֶת יְרֵאָיו אֶת הַמְיַחֲלִים לְחַסְדּוֹ, כַּמָּה אִית לְהוּ לִבְנֵי נָשָׁא לְמֵהַךְ בְּאָרְחוֹי דְּמַלְכָּא קַדִּישָׁא, וּלְמֵהַךְ בְּאָרְחוֹי דְּאוֹרַיְיתָא, בְּגִין דְּיִשְׁתַּכְּחוּן בִּרְכָּאן לְכֻלְּהוּ, לְעִלָּאֵי וּלְתַתָּאֵי.</p>\n<p>דְּתַנְיָא, מַאידִּכְתִּיב, (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר. אֶתְפָּאָר ודַּאי. מַאי מַשְׁמַע. דִּבְגִין <Nonei></i>יִשְׂרָאֵל לְתַתָּא, קוּדְשָׁא בְּרִיךְ הוּא מִתְפָּאַר לְעֵילָּא. וּמַאי פְּאֵרָא דִּילֵיהּ. דְּאִתְחַבָּשׁ בִּתְפִילִין, דְּמִתְחַבְּרָא גַּוְונִי לְאִתְפָּאַרָא.</p>\n<p>תָּאנָא, רוֹצֶה יְיָ' אֶת יְרֵאָיו, רוֹצֶה יְיָ' בִּירֵאָיו מִבָּעֵי לֵיהּ. מַאי רוֹצֶה יְיָ' אֶת יְרֵאָיו, אֶלָּא רוֹצֶה יְיָ' אֶת יְרֵאָיו, כְּלוֹמַר, אַפִּיק הַאי רָצוֹן, וּמִתְרָעֵי (נ\"א ואתידע) בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא, לִירֵאָיו דְּדָחֲלִין לֵיהּ. וּמַאן אִינּוּן יְרֵאָיו דְּאַפִּיק לוֹן הַאי רָצוֹן. הָדַר וְאָמַר, אֶת הַמְיַחֲלִים לְחַסְדּוֹ, אִינּוּן דִּמְצָפָאן וּמְחַכָּאן בְּכָל יוֹמָא וְיוֹמָא, לְמִבָּעֵי מְזוֹנַיְיהוּ מִן קוּדְשָׁא בְּרִיךְ הוּא, מַשְׁמַע דִּכְתִּיב אֶת הַמְיַחֲלִים לְחַסְדּוֹ.</p>\n<p>רִבִּי יֵיסָא סָבָא, לָא אַתְקִין סְעוּדָתָא בְּכָל יוֹמָא, עַד דְּבָעָא בָּעוּתֵיהּ קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, עַל מְזוֹנֵי. אָמַר, לָא נַתְקִין סְעוּדָתָא, עַד דְּתִתְיְהִיב מִבֵּי מַלְכָּא. לְבָתַר דְּבָעֵי בָּעוּתֵיהּ קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, הֲוָה מְחַכֶּה שַׁעֲתָא חֲדָא, אָמַר הָא עִידָן דְּתִתְיְהִיב מִבֵּי מַלְכָּא, מִכָּאן וּלְהָלְאָה אַתְקִינוּ סְעוּדָתָא. וְדָא הוּא אָרְחָא, דְּאִינּוּן דַּחֲלֵי קוּדְשָׁא בְּרִיךְ הוּא, דַּחֲלֵי חַטָּאָה.</p>\n<p>אִינּוּן חַיָּיבַיָּא דְּאַזְלִין עֲקִימִין בְּאָרְחֵי אוֹרַיְיתָא, מַה כְּתִיב בְּהוּ. (ישעיהו ה׳:י״א) הוֹי מַשְׁכִּימֵי בַבֹּקֶר שֵׁכָר יִרְדֹּפוּ. וְעַל דָּא רוֹצֶה יְיָ' אֶת יְרֵאָיו אֶת הַמְיַחֲלִים לְחַסְדּוֹ. לְחַסְדּוֹ דַּיְיקָא. (ס\"א ובהא) אִשְׁתְּמוֹדְעָן אִינּוּן בְּנֵי מְהֵימָנוּתָא בְּכָל יוֹמָא וְיוֹמָא, הֲדָא הוּא דִּכְתִּיב, וְיָצָא הָעָם וְלָקְטוּ דְּבַר יוֹם בְּיוֹמוֹ. יוֹם בְּיוֹמוֹ קָאָמַר, וְלֹא דְּבַר יוֹם לְיוֹם אַחֵר.</p>\n<p>וְכָל כַּךְ לָמָּה. לְמַעַן אֲנַסֶּנּוּ הֲיֵלֶךְ בְּתוֹרָתִי אִם לא בְּכָאן אִשְׁתְּמוֹדְעָן אִינּוּן בְּנֵי מְהֵימָנוּתָא, דְּכָל יוֹמָא וְיוֹמָא אִינּוּן אַזְלֵי בְּאֹרַח מֵישָׁר בְּאוֹרַיְיתָא. רִבִּי יִצְחָק אָמַר מֵהָכָא, (משלי י״ג:כ״ה) צַדִּיק אוֹכֵל לְשׂוֹבַע נַפְשׁוֹ, בָּתַר דְּשָׂבַע נַפְשֵׁיהּ מִלְּצַלֵּי וּלְמִקְרֵי בְּאוֹרַיְיתָא.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, תָּא חֲזֵי, עַד לָא יָהַב קוּדְשָׁא בְּרִיךְ הוּא אוֹרַיְיתָא לְיִשְׂרָאֵל, אַבְחִין בֵּין אִינּוּן בְּנִי מְהֵימָנוּתָא, וּבֵין אִינּוּן חַיָּיבַיָּא דְּלָאו אִינּוּן בְּנִי מְהֵימָנוּתָא, וְלָא קַיְימִין בְּאוֹרַיְיתָא. וּבַמֶּה אַבְחִין לוֹן. בַּמָּן. כְּמָה דְּאִתְּמַר אֲנַסֶּנּוּ. וְכָל אִינּוּן דְּאִשְׁתְּכָחוּ דְּאִינּוּן בְּנֵי מְהֵימָנוּתָא, רָשִׁים לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, בִּרְשִׁימוּ דְּכִתְרָא דְּחֶסֶ\"ד, כְּמָה דְאַתְּ אָמֵר הַמְיַחֲלִים לְחַסְדּוֹ, וְעַל דָּא לְמַעַן אֲנַסֶּנּוּ. וְכָל אִינּוּן דְּלָא מִשְׁתַּכְּחֵי בְּנִי מְהֵימָנוּתָא, אַעְדֵּי מִנַּיְיהוּ כִּתְרָא עִלָּאָה דָּא. וּמָנָא אַכְרִיז וְאָמַר, (משלי י״ג:כ״ה) וּבֶטֶן רְשָׁעִים תֶחְסַר. וְעִם כָּל דָּא לֹא הֶעְדִּיף הַמַּרְבֶּה וְהַמַּמְעִיט לא הֶחְסִיר.</p>\n<p>תָּאנָא, בְּהַהוּא שַׁעֲתָא אִשְׁתְּלִימוּ יִשְׂרָאֵל לְתַתָּא, כְּגַוְונָא דִּלְעֵילָּא, כְּמָה דְּאוֹקִימְנָא, דִּכְתִּיב, (שמות ט״ו:כ״ז) וַיָּבוֹאוּ אֵלִימָה וְשָׁם שְׁתֵּים עֶשְׂרֵה עֵינוֹת מַיִם וְשִׁבְעִים תְּמָרִים וְגו'. וְאִתְתָּקַּף אִילָנָא קַדִּישָׁא, בִּתְרֵיסַר תְּחוּמִין, בְּאַרְבַּע סִטְרֵי עָלְמָא. וְאִתְתָּקַּף בְּשִׁבְעִין עַנְפִין, וְכֹלָּא כְּגַוְונָא דִּלְעֵילָּא.</p>\n<p>בְּהַהִיא שַׁעֲתָא, נָטִיף טַלָּא קַדִּישָׁא, מֵעַתִּיקָא סְתִימָאָה, וּמַלְיָא לְרֵישֵׁיהּ דִּזְעֵיר אַנְפִּין, אֲתָר דְּאִקְרֵי שָׁמַיִם. וּמֵהַהוּא טַלָּא דִּנְהוֹרָא עִלָּאָה קַדִּישָׁא, הֲוָה נָגִיד וְנָחִית מָנָא לְתַתָּא. וְכַד הֲוָה נָחִית, הֲוָה מִתְפְּרַשׁ גְּלִידִין גְּלִידִין, וְאַקְרִישׁ לְתַתָּא. הֲדָא הוּא דִּכְתִּיב דַּק כַּכְּפוֹר עַל הָאָרֶץ.</p>\n<p>כָּל אִינּוּן בְּנֵי מְהֵימָנוּתָא, נַפְקֵי וְלַקְטֵי, וּמְבָרְכָאן שְׁמָא קַדִּישָׁא עָלֵיהּ. וְהַהוּא מָנָא, הֲוָה סָלִיק רֵיחִין דְּכָל בּוּסְמִין דְּגִנְתָּא דְּעֵדֶן, דְּהָא בֵּיהּ אִתְמְשַׁךְ וְנָחִית לְתַתָּא. שַׁוְיֵהּ לְקַמֵיהּ, בְּכָל טַעֲמָא דְּאִיהוּ בָּעֵי, הָכִי טָעִים לֵיהּ, וּמְבָרֵךְ לְמַלְכָּא קַדִּישָׁא עִלָּאָה.</p>\n<p>וּכְדֵין מִתְבָּרֵךְ בְּמֵעוֹי, וַהֲוָה מִסְתַּכֵּל וְיָדַע לְעֵילָּא, וְאִסְתָּכֵי בְּחָכְמָה עִלָּאָה, וְעַל דָּא אִקְרוּן דּוֹר דֵּעָה. וְאִלֵּין הֲווֹ בְּנֵי מְהֵימָנוּתָא, וּלְהוֹן אִתְיְהִיבַת אוֹרַיְיתָא לְאִסְתַּכְּלָא בָּהּ, וּלְמִנְדַּע אָרְחָהָא.</p>\n<p>וְאִינּוּן דְּלָא אִשְׁתְּכָחוּ בְּנִי מְהֵימָנוּתָא, מַה כְּתִיב בְּהוּ, (במדבר י״א:ח׳) שָׁטוּ הָעָם וְלָקְטוּ. מַאי שָׁטוּ. שְׁטוּתָא הֲווֹ נַסְבֵּי לְגַרְמַיְיהוּ, בְּגִין דְּלָא הֲווֹ בְּנֵי מְהֵימָנוּתָא. מַה כְּתִיב בְּהוּ. וְטָחֲנוּ בָרֵחַיִם אוֹ דָכוּ בַּמְּדוֹכָה וְגוֹ'. מַאן אַטְרַח <Nonei></i>לוֹן כָּל הַאי. אֶלָּא דְּאִינּוּן לָא הֲווֹ בְּנֵי מְהֵימָנוּתָא.</p>\n<p>כְּגַוְונָא דָּא, אִינּוּן דְּלָא מְהֵימְנֵי בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, לָא בָּעָאן לְאִסְתַּכְּלָא בְּאָרְחוֹי, וְאִינּוּן בָּעָאן לְאַטְרְחָא גַּרְמַיְיהוּ כָּל יוֹמָא בָּתַר מְזוֹנָא, יְמָמָא וְלֵילֵי, דִּלְמָא לָא סָלִיק בִּידַיְיהוּ פִּתָּא דְּנַהֲמָא. מַאן גָּרִים לוֹן הַאי. בְּגִין דְּלָאו אִינּוּן בְּנֵי מְהֵימָנוּתָא.</p>\n<p>אוּף הָכָא, שָׁטוּ הָעָם וְלָקְטוּ, שָׁטוּ בִּשְׁטּוּתָא דְּגַרְמַיְיהוּ, וּבָעָאן לְאַטְרְחָא עָלֵיהּ, הֲדָא הוּא דִּכְתִּיב, וְטָחֲנוּ בָרֵחַיִם. בָּתַר כָּל טִרְחָא דָּא, לָא סָלִיק בִּידַיְיהוּ, אֶלָּא דִּכְתִּיב וְהָיָה טַעְמוֹ כְּטַעַם לְשַׁד הַשָּׁמֶן. וְלָא יַתִּיר. מַאן גָּרִים לוֹן הַאי, בְּגִין דְּלָא הֲווֹ בְּנֵי מְהֵימָנוּתָא.</p>\n<p>אָמַר רִבִּי יוֹסֵי, מַאי לְשַׁד הַשָּׁמֶן. אִיכָּא דְּאַמְרֵי, דְּלִישׁ בְּמִשְׁחָא, כְּתַרְגּוּמוֹ. וְאִיכָּא דְּאַמְרֵי, מַה הַשֵּׁד אִתְחֲזָר לְכַמָּה גַּוְונִין, אוּף מָנָא, אִתְחֲזָר לְכַמָּה גַּוְונִין. רִבִּי יְהוּדָה אָמַר, לְשַׁד הַשָּׁמֶן, יְנִיקָא דְּמִשְׁחָא.</p>\n<p>רִבִּי יִצְחָק אָמַר, אִישׁ לְפִי אָכְלוֹ לָקָטוּ. וְכִי מַאן דְּאָכִיל קִמְעָא, לָקִיט קִמְעָא, וּמַאן דְּאָכִיל יַתִּיר, לָקִיט יַתִּיר, וְהָא כְּתִיב לֹא הֶעְדִּיף הַמַּרְבֶּה וְהַמַּמְעִיט לא הֶחְסִיר. אֶלָּא לְפוּם אִינּוּן דְּאַכְלִין לַקְטִין. מַשְׁמַע אָכְלוֹ, מַאן דְּהֲוָה אָכִיל לֵיהּ, וּבְגִינֵי כָּךְ לָא כְּתִיב אֲכִילָתוֹ.</p>\n<p>מַאי קָא מַיְירֵי. אָחִיד בַּר נָשׁ בְּעַבְדָּא, אוֹ בְּאָמָתָא, וְאָמַר דְּהוּא דִּילֵיהּ. אָתָא חַבְרֵיהּ, וְאָמַר, הַאי עַבְדָּא דִּילִי הוּא. קְרִיבוּ לְקַמֵיהּ דְּמֹשֶׁה לְדִינָא, אָמַר לוֹן כַּמָּה נַפְשָׁאָן בְּבֵיתֶךָ, וְכַמָּה נַפְשָׁאָן בְּבֵיתֵיהּ דְּדֵין, אָמַר כַּךְ וְכָךְ. וְהַהוּא שַׁעֲתָא אָמַר לוֹן מֹשֶׁה, לָקָטוּ מָחָר, וְכָל חַד מִנַּיְיכוּ יֵיתֵי לְגַבָּאי. לְמָחָר, נָפְקוּ וְלָקְטוּ, וְאַתְיָין קָמֵי מֹשֶׁה, שַׁוְויָין קָמֵיהּ מָנָא, הֲוָה מָדִיד לֵיהּ. אִי הַהוּא עַבְדָּא דְּדֵין, אַשְׁכַּח הַהוּא עוֹמְרָא דְּעַבְדָּא, בְּהַאי מָנָא. דְּהָא חַד עוֹמְרָא לְכָל נֶפֶשׁ וְנֶפֶשׁ מִבֵּיתֵיהּ. מָדִיד לְדֵין, וְאִשְׁתְּכַח חַסְרָא, הַהוּא מֵיכְלָא דְּעַבְדָּא, בְּהַהוּא מָנָא דִּילֵיהּ, וְחַד עוֹמְרָא לְכָל נֶפֶשׁ וְנֶפֶשׁ מִבֵּיתֵיהּ. אָמַר עַבְדָּא דְּדֵין הוּא, הֲדָא הוּא דִכְתִיב אִישׁ לְפִי אָכְלוֹ לָקָטוּ וּכְתִיב עֹמֶר לַגֻּלְגֹּלֶת מִסְפַּר נַפְשֹׁתֵיכֶם.</p>\n<p>אָמַר ר' (נ\"א ייסא) חִיָּיא, כְּתִיב, (שמות ט״ז:ו׳-ז׳) עֶרֶב וִידַעְתֶּם כִּי יְיָ' הוֹצִיא אֶתְכֶם מֵאֶרֶץ מִצְרַיִם וּבֹקֶר וּרְאִיתֶם אֶת כְּבוֹד יְיָ'. עֶרֶב וִידַעְתֶּם, בְּמַאי יִנְדְּעוּן. אֶלָּא הָכִי תָּאנָא, בְּכָל יוֹמָא וְיוֹמָא אִשְׁתְּכָחוּ נִימוּסֵי קוּדְשָׁא בְּרִיךְ הוּא. בְּצַפְרָא, אִתְּעַר חֶסֶד בְּעָלְמָא. בְּהַהוּא זִמְנָא דְּאִקְרֵי עֶרֶב, תַּלְיָא דִּינָא בְּעָלְמָא, וְהָא אוּקְמוּהָ, דִּבְגִינֵי כַּךְ, יִצְחָק תִּקֵּן תְּפִלַּת הַמִּנְחָה. (מאי קא מיירי) וְעַל דָּא, עֶרֶב וִידַעְתֶּם, כַּד אִתְּעַר דִּינָא בְּעָלְמָא, תִּנְדְּעוּן, דִּבְהַהוּא דִּינָא אַפִּיק יְיָ' יַתְכוֹן מִמִּצְרַיִם. וּבֹקֶר וּרְאִיתֶם אֶת כְּבוֹד יְיָ' דְּהָא בְּהַהוּא זִמְנָא אִתְּעַר חֶסֶד בְּעָלְמָא וְיִתֵּן לְכוּ לְמֵיכַל.</p>\n<p>ר' חִיָּיא אָמַר אִיפְּכָא, מַה כְּתִיב לְעֵילָּא, בְּשִׁבְתֵּנוּ עַל סִיר הַבָּשָׂר וְגוֹ'. בֵּיהּ שַׁעֲתָא, אִתְּעַר עֶרֶב, דְּהַהוּא זִמְנָא דְּאִתְּעַר דִּינָא, אִתְּעַר נָמֵי חֶסֶד בְּעָלְמָא. הֲדָא הוּא דִכְתִיב, וִידַעְתֶּם כִּי יְיָ' הוֹצִיא אֶתְכֶם מֵאֶרֶץ מִצְרָיִם. תִּנְדְּעוּן הַהוּא חֶסֶד דְּעָבַד עִמְּכוֹן, בְּזִמְנָא דְּדִינָא וְאַפִּיק יַתְכוֹן מֵאַרְעָא דְּמִצְרַיִם. וּבֹקֶר וּרְאִיתֶם אֶת כְּבוֹד יְיָ', כְּבוֹד יְיָ' הָא יְדִיעַ. וְכָּל כַּךְ לָמָּה. בִּשְׁמוֹעַ יְיָ' אֶת תְּלֻנּוֹתֵיכֶם וְגוֹ'.</p>\n<p>אָמַר ר' יֵיסָא, לָא שָׁנֵי קוּדְשָׁא בְּרִיךְ הוּא נִימוּסוֹי, בַּר דְּאִינּוּן חַיָּיבֵי עָלְמָא שַׁנְיָין לוֹן, וּמְהַפְּכֵי רַחֲמֵי לְדִינָא, כְּמָה דְּאִתְּמַר.</p>\n<p>תָּאנֵי ר' אֶלְעָזָר, מֵהַאי מָנָא זְמִינִין צַדִּיקַיָּיא לְמֵיכַל לְעָלְמָא דְּאָתֵי, וְאִי תֵּימָא בְּהַאי גַּוְונָא. לָא. אֶלָּא יַתִּיר, דְּלָא הֲוָה כֵּן לְעָלְמִין. מַאי אִיהוּ. כְּמָה דְּאוֹקִימְנָא דִּכְתִּיב, (תהילים כ״ז:ד׳) לַחֲזוֹת בְּנֹעַם יְיָ' וּלְבַקֵּר בְּהֵיכָלוֹ. וּכְתִיב (ישעיהו ס״ד:ג׳) עַיִן לא רָאָתָה אֱלהִים זוּלָתְךָ וְגוֹ'.</p>\n<p>(שמות ט״ז:כ״ט) רְאוּ כִּי יְיָ' נָתַן לָכֶם הַשַּׁבָּת. ר' חִזְקִיָּה פָּתַח (תהילים ק״ל:א׳) שִׁיר הַמַּעֲלוֹת מִמַּעֲמַקִּים קְרָאתִיךָ יְיָ'. שִׁיר הַמַּעֲלוֹת סָתַם, וְלָא פָּרִישׁ מַאן אָמָרוּ. אֶלָּא שִׁיר הַמַּעֲלוֹת, דִּזְמִינִין <Nonei></i>כָּל בְּנֵי עָלְמָא לְמֵימַר, דְּזַמִּין הַאי שִׁיר לְמֵימְרֵיהּ לְדָרֵי עָלְמָא.</p>\n<p>וּמַאי הוּא מִמַּעֲמַקִּים קְרָאתִיךָ. הָכִי תָּאנָא, כָּל מַאן דִּמְצַלֵי צְלוֹתָא קָמֵי מַלְכָּא קַדִּישָׁא, בָּעֵי לְמִבָּעֵי בָּעוּתֵיהּ, וּלְצַלָּאָה (ויקרא ע\"א) מֵעִמְקָא דְּלִבָּא, בְּגִין דְּיִשְׁתְּכַח לִבֵּיהּ שְׁלִים בְּקוּדְשָׁא בְּרִיךְ הוּא, וִיכַוֵּין לִבָּא וּרְעוּתָא. וּמִי אָמַר דָּוִד הָכִי, וְהָא כְּתִיב, (תהילים קי״ט:י׳) בְּכָל לִבִּי דְּרַשְׁתִּיךָ. וְדָא קְרָא סַגִּי, מַאי בָּעֵי מִמַּעֲמַקִּים.</p>\n<p>אֶלָּא הָכִי תָּאנָא, כָּל בַּר נָשׁ דְּבָעֵי בָּעוּתֵיהּ קָמֵי מַלְכָּא, בָּעֵי לְכַוְּונָא דַּעְתָּא (נ\"א לבא) וּרְעוּתָא, מֵעִיקָּרָא דְּכָל עִקָרִין, לְאַמְשָׁכָא בִּרְכָּאן מֵעִמְקָא דְּבֵירָא, (נ\"א דכלא) בְּגִין דְּיַנְגִּיד בִּרְכָּאן מִמַּבּוּעָא דְּכֹלָּא. וּמַאי הוּא. הַהוּא אֲתָר דְּנָפִיק מִנֵּיהּ, וְאִשְׁתְּכַח מִנֵּיהּ, הַהוּא נָהָר, דִּכְתִּיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן. וּכְתִיב (תהילים מ״ו:ה׳) נָהָר פְּלָגָיו יְשַׂמְחוּ עִיר אֱלהִים. וְדָא אִקְרֵי מִמַּעֲמַקִּים. (מ\"ט ע\"א) עִמְקָא דְּכֹלָּא, עִמְקָא דְּבֵירָא, דְּמַבּוּעִין נָפְקִין וְנַגְדִּין לְבָרְכָא כֹּלָּא. וְדָא הוּא שֵׁרוּתָא לְאַמְשָׁכָא בִּרְכָּאן מֵעֵילָּא לְתַתָּא.</p>\n<p>אָמַר רִבִּי חִזְקִיָּה, (בראשית רל\"ד ע\"א, ויקרא רפ\"ה א' ב', רצ\"ז ע\"ב) כַּד עַתִּיקָא סְתִימָאָה דְּכָל סְתִימִין, בָּעֵי לְזַמְנָא בִּרְכָּאן לְעָלְמִין, אַשְׁרֵי כֹּלָּא, וְאַכְלִיל כֹּלָּא, בְּהַאי עֲמִיקָא עִלָּאָה, וּמֵהָכָא שָׁאִיב וְאִתְנְגִיד בֵּירָא (נ\"א נהרא) דְּנַחֲלִין וּמַבּוּעִין אִתְנְגִידוּ מִנֵּיהּ, וּמִתְשַׁקְיָין מִנֵּיהּ כֻּלְּהוּ. וּמַאן דִּמְצַלֵי צְלוֹתֵיהּ, בָּעֵי לְכַוְּונָא לִבָּא וּרְעוּתָא, לְאַמְשָׁכָא בִּרְכָּאן מֵהַהוּא עֲמִיקָא דְּכֹלָּא, בְּגִין דְּיִתְקַבַּל צְלוֹתֵיהּ, וְיִתְעֲבִיד רְעוּתֵיהּ.</p>\n<p>וַיֹּאמֶר מֹשֶׁה אֲלֵיהֶם אִישׁ אַל יוֹתֵר מִמֶּנּוּ עַד בֹּקֶר. אָמַר רִבִּי יְהוּדָה, בְּכָל יוֹמָא וְיוֹמָא, מִתְבָּרֵךְ עָלְמָא מֵהַהוּא יוֹמָא עִלָּאָה, דְּהָא כָּל שִׁיתָא יוֹמִין מִתְבָּרְכָאן מִיּוֹמָא שְׁבִיעָאָה. וְכָל יוֹמָא יָהִיב מֵהַהוּא בְּרָכָה דְּקַבִּיל בְּהַהוּא יוֹמָא דִּילֵיהּ.</p>\n<p>וְעַל דָּא מֹשֶׁה אָמַר, אִישׁ אַל יוֹתֵר מִמֶּנּוּ עַד בֹּקֶר. מַאי טַעְמָא. בְּגִין דְּלָא יָהִיב, וְלָא יוֹזִיף יוֹמָא דָּא לְחַבְרֵיהּ, אֶלָּא כָּל חַד וְחַד שָׁלִיט בִּלְחוֹדוֹי, בְּהַהוּא יוֹמָא דִּילֵיהּ. דְּהָא לָא שָׁלִיט יוֹמָא בְּיוֹמָא דְּחַבְרֵיהּ.</p>\n<p>בְּגִינֵי כַּךְ, כָּל אִינּוּן (נ\"א אמר רבי יהודה כל יומא ויומא מתברך מההוא יומא עילאה יומא שביעאה ומתברכן כל שיתא יומין כל חד וחד בלחודוי וכל יומא יהיב ביומא דיליה מההוא ברכה דקביל מההוא יומא עילאה ועל דא משה אמר איש אל יותר ממנו עד בקר דהא לא שליט יומא ביומא דלאו דיליה וכל אינון) חֲמִשָּׁא יוֹמִין שַׁלִּיטִין בְּיוֹמַיְיהוּ, וְאִשְׁתְּכַח בֵּיהּ, מַה דְּקַבִּילוּ, וְיוֹמָא שְׁתִיתָאָה אִשְׁתְּכַח בֵּיהּ יַתִּיר. וְאַזְלָא הָא, כְּהָא דְּאָמַר רִבִּי אֶלְעָזָר, מַאי דִּכְתִּיב יוֹם הַשִּׁשִּׁי, וְלָא אִתְּמַר הָכִי בְּכָל שְׁאַר יוֹמִין. אֶלָּא הָכִי אוּקְמוּהָ, הַשִּׁשִּׁי. דְּאִזְדַּוְּוגָא (דאזדמנא) בֵּיהּ מַטְרוֹנִיתָא. לְאַתְקְנָא פָּתוֹרָא לְמַלְכָּא, וּבְּגִין כָּךְ, אִשְׁתְּכָחוּ בֵּיהּ תְּרֵין חוּלָקִין, חַד לְיוֹמֵיהּ, וְחַד לְתִקּוּנָא, בְּחֶדְוָותָא דְּמַלְכָּא בְּמַטְרוֹנִיתָא.</p>\n<p>וְהַהוּא לֵילְיָא, חֶדְוָותָא דְּמַטְרוֹנִיתָא בְּמַלְכָּא, וְזִוּוּגָא דִּלְהוֹן, וּמִתְבָּרְכָאן כָּל שִׁיתָא יוֹמִין, כָּל חַד וְחַד בִּלְחוֹדוֹי. בְּגִין כַּךְ, בָּעֵי בַּר נָשׁ לְסַדְּרָא פָּתוֹרֵיהּ בְּלֵילְיָא דְּשַׁבְּתָא, בְּגִין דְּשָׁארִי עָלֵיהּ בִּרְכָּאן מִלְּעֵילָּא, וּבִרְכָּתָא לָא אִשְׁתְּכַח עַל פָּתוֹרָא רֵיקַנְיָא, (וההוא ליליא חדותא דמטרוניתא במלכא וזווגא דלהון) בְּגִין כָּךְ, תַּלְמִידֵי חֲכָמִים דְּיַדְעִין רָזָא דָּא, זִוּוּגָא דִּלְהוֹן מְעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת.</p>\n<p>רְאוּ כִּי יְיָ' נָתַן לָכֶם הַשַּׁבָּת, מַאי שַׁבָּת. יוֹמָא דְּבֵיהּ נַיְיחִין שְׁאַר יוֹמִין, וְהוּא כְּלָלָא דְּכָל אִינּוּן שִׁיתָא אַחֲרָנִין, וּמִנֵּיהּ מִתְבָּרְכִין. רִבִּי יֵיסָא אָמַר, וְכֵן נָמֵי כְּנֶסֶת יִשְׂרָאֵל אִקְרֵי שַׁבָּת, בְּגִין דְּאִיהִי בַּת זוּגוֹ, וְדָא הִיא כַּלָּה. דִּכְתִּיב (שמות ל״א:י״ד) וּשְׁמַרְתֶּם אֶת הַשַּׁבָּת כִּי קֹדֶשׁ הִיא לָכֶם. לָכֶם וְלָא לִשְׁאַר עַמִּין, הֲדָא הוּא דִכְתִיב, (שמות ל״א:י״ד) בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל. וְדָא הִיא אַחֲסָנַת יְרוּתַת עָלְמִין לְיִשְׂרָאֵל. וְעַל דָּא, כְּתִיב (ישעיהו נ״ח:י״ג) אִם תָּשִׁיב מִשַּׁבָּת רַגְלְךָ וְגוֹ' וּבְאַתְרִיהּ אוֹקִימְנָא מִלֵּי.</p>\n<p>כְּתִיב אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ בַּיּוֹם הַשְּׁבִיעִי. מִמְּקוֹמוֹ. תָּנֵינָן, מֵהַהוּא מָקוֹם דְּאִתְחָזֵי לְמֵהַךְ. וְרָזָא דְּמִלָּה דִּכְתִּיב, (יחזקאל ג׳:י״ב) בָּרוּךְ כְּבוֹד יְיָ' מִמְּקוֹמוֹ, וְדָא אִיהוּ מָקוֹם. וְדָא אִיהוּ רָזָא דִּכְתִּיב, (שמות ג׳:ה׳) כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו אַדְמַת קֹדֶשׁ הוּא. אֲתָר יְדִיעָא קָרֵינָן לֵיהּ מָקוֹם דְּאִשְׁתְּמוֹדְעָא יְקָרָא עִלָּאָה.</p>\n<p>וּבְגִין כַּךְ, אַזְהָרוּתָא לְבַר נָשׁ, דְּקָא מִתְעַטְּרָא בְּעִטּוּרָא קַדִּישָׁא דִּלְעֵילָּא, דְּלָא יִפּוּק מִנֵּיהּ בְּפוּמֵיהּ מִלּוּלָא (ע\"א ע\"ב) דְּחוֹל, בְּגִין דְּאִי יִפּוּק מִנֵּיהּ, קָא <Nonei></i>מְחַלֵּל יוֹמָא דְּשַׁבְּתָא, בִּידוֹי בְּעוֹבַדְתָּא. בְּרַגְלוֹי, לְמֵהַךְ לְבַר מִתְּרֵין אַלְפִין אַמִּין. כָּל אִלֵּין חִלּוּלָא דְּשַׁבְּתָא אִינּוּן.</p>\n<p>אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ, דָּא אִיהוּ אֲתָר יַקִּירָא דִּקְדוּשָּׁה, דְּהָא לְבַר מִנֵּיהּ, אֱלהִים אֲחֵרִים נִינְהוּ. בָּרוּךְ כְּבוֹד יְיָ', דָּא כָּבוֹד דִּלְעֵילָּא. מִמְּקוֹמוֹ, דָּא כָּבוֹד דִּלְתַתָּא. דָּא אִיהוּ רָזָא דַּעֲטָּרָא דְּשַׁבָּת, בְּגִין כַּךְ אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ. זַכָּאָה חוּלָקֵיהּ מַאן דְּזָכֵי לִיקָרָא דְּשַׁבְּתָא זַכָּאָה אִיהוּ בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.</p>"],[9520011628,"<p>(שמות י״ז:ה׳) וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה עֲבוֹר לִפְנֵי הָעָם וְגוֹ'. רִבִּי חִיָיא פָּתַח, (תהלים לה) חוֹנֶה מַלְאַךְ יְיָ' סָבִיב לִירֵאָיו וַיְחַלְּצֵם. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בִּיקָרֵיהוֹן, יַתִּיר עַל דִּילֵיהּ. תָּא חֲזֵי, כַּמָּה אִינּוּן בְּנֵי עָלְמָא, דִּמְחָרְפֵי וּמְגַדְּפֵי לְעֵילָּא, כְּגוֹן סַנְחֵרִיב חֵרֵף וְגִדֵּף, וְאָמַר (מלכים ב י״ח:ל״ה) מִי בְּכָל אֱלהֵי הָאֲרָצוֹת וְגוֹ'. וְקוּדְשָׁא בְּרִיךְ הוּא מָחִיל, וְלָא תָּבַע מִנִּיהּ. כֵּיוָן דְּאוֹשִׁיט יְדֵיהּ עַל חִזְקִיָּה, מַה כְּתִיב (מלכים ב י״ט:ל״ה) וַיֵּצֵא מַלְאַךְ יְיָ' וַיַּךְ בְּמַחֲנִה אַשּׁוּר וְגוֹ'.</p>\n<p>יָרָבְעָם בֶּן נְבָט הֲוָה פָּלַח לְעֲבוֹדָה זָרָה, וּמְקָטַר לָהּ, וּמְזָבַח לָהּ, וְקוּדְשָׁא בְּרִיךְ הוּא לָא תָּבַע מִנֵּיהּ. וְכַד אָתָא עִדוֹ נְבִיאָה, וְאִתְנַבֵּי עָלֵיהּ, וְאוֹשִׁיט יָרָבְעָם יְדָא לְקָבְלֵיהּ, מַה כְּתִיב (מלכים א י״ג:ד׳) וַתִּיבַשׁ יָדוֹ וְגוֹ', וְלֹא יָכֹל לַהֲשִׁיבָהּ אֵלָיו. (ועל דפלח לעבודה זרה לא תבע ליה קודשא בריך הוא)</p>\n<p>פַּרְעֹה חֵרֵף וְגִדֵּף, וְאָמַר (שמות ה) מִי יְיָ' וְגוֹ'. וְקוּדְשָׁא בְּרִיךְ הוּא לָא תָּבַע מִנֵּיהּ, עַד דְּסָרִיב בְּהוּ בְּיִשְׂרָאֵל, דִּכְתִּיב, (שמות ט׳:י״ז) עוֹדְךָ מִסְתּוֹלֵל בְּעַמִּי. (שמות ט׳:י״ז) הִנֵּה יַד יְיָ' הוֹיָה בְּמִקְנְךְ וְגוֹ', וְכֵן בְּכָל אֲתָר, קוּדְשָׁא בְּרִיךְ הוּא תָּבַע עֶלְבּוֹנָא דְּצַדִּיקַיָּיא יַתִּיר עַל דִּילֵיהּ.</p>\n<p>הָכָא מֹשֶׁה, אָמַר עוֹד מְעַט וּסְקָלוּנִי, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, מֹשֶׁה לָאו עִידָּן הוּא לְמִתְבַּע עֶלְבּוֹנָךְ, אֶלָּא עֲבוֹר לִפְנֵי הָעָם, וְאַחְמֵי מַאן יוֹשִׁיט יְדוֹי לָקֳבְלָךְ, וְכִי בִּרְשׁוּתַיְיהוּ אַתְּ קָאִים, אוֹ בִּרְשׁוּתִי.</p>"],[9520011629,"<p>וּמַטְּךָ אֲשֶׁר הִכִּיתָ בּוֹ אֶת הַיְאוֹר קַח בְּיָדְךָ וְהָלָכְתָּ. מַאי טַעְמָא. מִשּׁוּם דִּמְחַקֵּק בַּנִּסִּין הֲוָה, וּשְׁמָא קַדִּישָׁא עִלָּאָה רְשִׁימָא בֵּיהּ. בְּקַדְמִיתָא נָחָשׁ, כְּמָה דְּאִתְּמַר, (משלי ל׳:י״ט) דֶּרֶךְ נָחָשׁ עֲלֵי צוּר. נָחָשׁ, הָא אִתְיְדַע דְּאִתְּעַר צוּר. (נ\"א ואתמר צור) בְּאָן אֲתָר אִתְגְּלֵי, הָכָא אִתְגְּלֵי דִּכְתִּיב הִנְנִי עוֹמֵד לְפָנֶיךָ שָׁם עַל הַצּוּר. וּמַאן צוּר. כְּמָה דְאַתְּ אָמֵר (דברים לכ) הַצּוּר תָמִים פָּעֳלוֹ, וְתַמָּן יָדַע מֹשֶׁה הֵיךְ קָאִים נָחָשׁ עָלֵי צוּר. וְהָא אוֹקִימְנָא מִלֵּי.</p>\n<p>אָמַר רִבִּי יְהוּדָה, אִי לִישְׁתִּיק קְרָא יֵאוֹת שָׁאִילְתָּא. אֶלָּא הָא כְּתִיב, וְהִכִּיתָ בַצּוּר וַיָּצְאוּ מִמֶּנּוּ מַיִם. אָמַר לֵיהּ, וַדַּאי הָכִי הוּא, דְּלֵית לָךְ כָּל שְׁמָא וּשְׁמָא, מֵאִינּוּן שְׁמָהָן קַדִּישִׁין דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּלָא עָבֵד נִסִּין וּגְבוּרָאן, וְאַפִּיק כֹּלָּא דְּאִצְטְרִיךְ לְעָלְמָא, כָּל שֶׁכֵּן לְאַפָּקָא הָכָא מַיָּא.</p>\n<p>אֲמַר לֵיהּ, אִי הָכִי, הָא כְּתִיב, (תהילים ע״ח:כ׳) הֵן הִכָּה צוּר וַיָּזוּבוּ מַיִם. מַאן מָחֵי לִשְׁמֵיהּ. אֲמַר לֵיהּ, פַּטִּישָׁא חֲרִיפָא, בְּקִטְרוֹי יְדִיעַ, וְאַתְּ שָׁאִיל דָּא. אֶלָּא תָּא חֲזֵי, בְּכָל אֲתָר צוּר גְּבוּרָה, וְכַד בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְמַחֲאָה, אוֹ לְאַלְקָאָה, אִתְּעַר גְּבוּרָה דָּא וְהַהוּא גְּבוּרָה מָחֵי וְלָקֵי, וְדָא הוּא דִּכְתִּיב, הֵן הִכָּה צוּר וַיָּזוּבוּ מַיִם. וְאִי לָאו דְּאִתְּעַר צוּר, וְלָקֵי בְּאֲתָר דְּאִצְטְרִיךְ, לָא נַבִיעִין מַיָּא.</p>\n<p>אֲמַר לֵיהּ, אִי הָכִי, הָא כְּתִיב, (דברים ל״ב:י״ח) צוּר יְלָדְךָ תֶּשִׁי. וְתָנֵינָן מַאי תֶּשִׁי, כְּלוֹמַר חַלָּשְׁת לֵיהּ. אֲמַר לֵיהּ וַדַּאי הָכִי הוּא, דְּאִלְמָלֵי יִנְדְּעוּן חַיָּיבַיָּא, דְּהַאי צוּר זְמִינָא לְאִתְּעָרָא לָקֳבְלַיְיהוּ, וּלְאַלְקָאָה לוֹן, יִמָּנְעוּן מִלְּמֵיחָב קָמֵיהּ, אֶלָּא חַלְשָׁא אִיהִי בְּעֵינַיְיהוּ, הוֹאִיל וְלָא מִסְתַּכְּלֵי בָּהּ, וְלָא מִסְתַּכְּלֵי בְּאֹרְחַיְּיהוּ (ס\"א בכרסייהו) וְעַל דָּא צוּר יְלָדְךָ תֶּשִׁי.</p>\n<p>ר' אַבָּא אָמַר, אִית צוּר, וְאִית צוּר, מִסִּטְרָא דְּצוּר עִלָּאָה, נָפַק צוּר אַחֲרָא. וּמַאי צוּר עִלָּאָה. צוּר דְּכָל צוּרִים. וּמַאי אִיהוּ, הַהוּא דְּאוֹלִידַת לְיִשְׂרָאֵל, דִּכְתִּיב צוּר יְלָדְךָ תֶּשִׁי. דְּהָא מִסִּטְרָא דְּצוּר עִלָּאָה דִּלְעֵילָּא, נָפְקָא צוּר אַחֲרָא. מִסִּטְרָא דְּאִימָא, נָפְקָא גְּבוּרָה.</p>\n<p>וְאַזְלָא הָא כְּהָא דְּאָמַר רִבִּי אֶלְעָזָר, כְּתִיב (תהילים ק״ו:ב׳) מִי (פ\"ג ע\"א) יְמַלֵּל גְּבוּרוֹת יְיָ'. מַאי גְּבוּרוֹת יְיָ'. לְאַכְלְלָא אִימָא עִלָּאָה דְּכֹלָּא, דְּאַף עַל גַּב דְּלָאו אִיהִי דִּינָא, מִסִּטְרָהָא אִשְׁתְּכַח, דְּהָא מִסִּטְרָהָא <Nonei></i>גְּבוּרָה אִשְׁתְּכַח, וּבְגִינֵי כַּךְ צוּר עִלָּאָה אִקְרֵי. (דברים ל״ב:י״ח) וַתִּשְׁכַּח אֵל מְחוֹלְלֶךָ, דָּא נְהִירוּ דְּאַבָּא. מַאי נִיהוּ. חֶסֶד עִלָּאָה, דְּאִיהוּ נְהִירוּ דְּאַבָּא.</p>\n<p>תּוּ אָמַר רִבִּי אַבָּא, מַיִם בְּכָל מָקוֹם, הָא יְדִיעָא, וְקוּדְשָׁא בְּרִיךְ הוּא בְּהַאי צוּר אִתְּעַר לְאַרְקָא מַיָּא, דְּהָא לָא אִתְחָזֵי, (אלא מגדולה) וְדָא הוּא אָת וְנִיסָא דְּקוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא שָׁבַח דָּוִד וְאָמַר, (תהילים קי״ד:ח׳) הַהֹפְכִי הַצּוּר אֲגַם מָיִם וְגוֹ'. וּמַשְׁמַע הַהֹפְכִי, דְּהָא לָאו אָרְחוֹי דְּצוּר בְּכַךְ.</p>\n<p>וְעַל דָּא, בְּצוּר עִלָּאָה, אַפִּיק מַיָּא מֵאֲתָר דִּלְתַתָּא. וּמַה שְׁמֵיהּ דְּהַהוּא דִּלְתַתָּא. סֶלַע. דִּכְתִּיב, (במדבר כ׳:ח׳) וְהוֹצֵאתָ לָהֶם מַיִם מִן הַסֶּלַע. וּבַמֶּה אַפִּיק הַאי סֶלַע מַיָּא. בְּחֵילָא דְּצוּר דִּלְעֵילָּא.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, (דברים ל״ב:ד׳) הַצּוּר תָמִים פָּעֳלוֹ מַאי מַשְׁמַע הַצּוּר תָמִים פָּעֳלוֹ. דְּאִתְהַפָּךְ צוּר, לְמֶעְבַּד פָּעֳלוֹ דְּתָמִים. וּמַאי אִיהוּ. אַבְרָהָם. דִּכְתִּיב בֵּיהּ (בראשית י״ז:א׳) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים. וְדָא הוּא הַהֹפְכִי הַצּוּר אֲגַם מָיִם, וּמַשְׁמַע תָמִים פָּעֳלוֹ, וְדָא אַבְרָהָם.</p>\n<p>בְּשַׁעֲתָא דָּא, אִתְהַדַּר הַצּוּר, תָמִים. בְּשַׁעֲתָא אַחֲרָא תִּנְיָינָא, כַּד (אתענש) בָּעָא מֹשֶׁה לְאַפָּקָא מַיָּא בְּהַאי צוּר, בְּחוֹבַיְיהוּ דְּיִשְׂרָאֵל, לָא אִתְהַדַּר תָמִים, כְּקַדְמִיתָא. בֵּיהּ זִמְנָא, אִתְרָעַם מֹשֶׁה וְאָמַר, צוּר יְלָדְךָ תֶּשִׁי. כְּלוֹמַר, חַלָּשְׁת לֵיהּ מִמַּה דְּהֲוָה בְּקַדְמִיתָא, דִּבְגִינָךְ לָא אִשְׁתְּכַח תָּמִים הַשְׁתָּא, וְאִתְעָבִיד (ביה) דִּינָא, מַה דְּלָא הֲוָה בְּיוֹמֵי יְלָדְךָ, כְּלוֹמַר עוּלֵימָךְ.</p>"],[9520011630,"<p>אָמַר רִבִּי אַבָּא, מַאי דִּכְתִּיב הֲיֵשׁ יְיָ' בְּקִרְבֵּנוּ אִם אָיִן. וְכִי טִפְּשִׁין הֲווֹ יִשְׂרָאֵל דְּלָא יַדְעֵי מִלָּה דָּא, וְהָא חָמוּ שְׁכִינְתָּא קָמַיְיהוּ, וַעֲנֵנִי כָּבוֹד עָלַיְיהוּ דְּסַחְרוֹן לוֹן, וְאִינּוּן אָמְרוּ הֲיֵשׁ יְיָ' בְּקִרְבֵּנוּ אִם אָיִן, גּוּבְרִין דְּחָמוּ זִיו יְקָרָא דְּמַלְכֵּיהוֹן עַל יַמָּא, וְתָנֵינָן, רָאָתָה שִׁפְחָה עַל הַיָּם מַה שֶּׁלֹּא רָאָה יְחֶזְקֵאל, אִינּוּן אִשְׁתְּכָחוּ טִפְּשִׁין, וְאָמְרוּ הֲיֵשׁ יְיָ' בְּקִרְבֵּנוּ אִם אָיִן.</p>\n<p>אֶלָּא (נשא קכ\"ט ע\"א) הָכִי קָאָמַר רַבִּי שִׁמְעוֹן, בָּעוּ לְמִנְדַּע, בֵּין עַתִּיקָא סְתִימָאָה דְּכָל סְתִימִין, דְּאִקְרֵי אַיִן. וּבֵין זְעֵיר אַפִּין דְּאִקְרֵי יְיָ'. וְעַל דָּא, לָא כְּתִיב הֲיֵשׁ יְיָ' בְּקִרְבֵּנוּ אִם לא, כְּמָה דִּכְתִּיב הֲיֵלֶךְ בְּתוֹרָתִי אִם לֹא. אֶלָּא הֲיֵשׁ יְיָ' בְּקִרְבֵּנוּ אִם אָיִן.</p>\n<p>אִי הָכִי אֲמַאי אִתְעַנְשׁוּ. אֶלָּא עַל דַּעֲבִידוּ פִּרוּדָא, וַעֲבִידוּ בְּנִסְיוֹנָא, דִּכְתִּיב וְעַל נַסּוֹתָם אֶת יְיָ'. אָמְרוּ יִשְׂרָאֵל, אִי הַאי נִשְׁאַל בְּגַוְונָא חַד. וְאִי הַאי נִשְׁאַל בְּגַוְונָא אַחֲרָא. וְעַל דָּא מִיָּד וַיָּבֹא עֲמָלֵק.</p>"],[9520011631,"<p>(שמות י״ז:ח׳) וַיָּבֹא עֲמָלֵק וַיִּלָּחֶם עִם יִשְׂרָאֵל בִּרְפִידִים. רִבִּי יוֹסֵי פָּתַח, (ישעיהו ל״ב:כ׳) (ו' ע\"א) אַשְׁרֵיכֶם זוֹרְעֵי עַל כָּל מָיִם מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר. אַשְׁרֵיכֶם זוֹרְעֵי עַל כָּל מָיִם, תַּמָּן תָּנִינָן, כַּמָּה מַיִם וְכַמָּה מַיִם מִשְׁתַּכְּחִין. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּלֵית זַרְעָא לְהוּ, אֶלָּא עַל הַמַּיִם, דִּכְתִּיב וְיַּחֲנוּ שָׁם עַל הַמָּיִם, אִינּוּן דַּהֲווֹ תְּחוֹת עַנְפֵי אִילָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>דְּתַנְיָא, אִילָנָא אִית לְקוּדְשָׁא בְּרִיךְ הוּא, וְהוּא אִילָנָא רַבְרְבָא וְתַקִּיפָא, וּבֵיהּ אִשְׁתְּכַח מְזוֹנָא לְכֹלָּא. וְהוּא אִתְּחַם בִּתְרֵיסַר תְּחוּמִין, בְּמַתְקְלָא, וְאִתְתַּקַּף בְּאַרְבַּע רוּחֵי עָלְמָא. וְע' עַנְפִּין אֲחִידָן בֵּיהּ וְיִשְׂרָאֵל מִשְׁתַּכְּחֵי בְּגוּפָא דְּהַהוּא אִילָנָא. וְאִינּוּן שִׁבְעִין עַנְפִּין סַחֲרָנָא דִּלְהוֹן.</p>\n<p>וְהַיְינוּ דִּכְתִּיב, וַיָּבֹאוּ אֵלִימָה וְשָׁם שְׁתֵּים עֶשְׂרֵה עֵינוֹת מַיִם וְשִׁבְעִים תְּמָרִים, וְהָא אוּקְמוּהָ, וְאִתְּמַר בְּכַמָּה אֲתָר. מַאי וְיַּחֲנוּ שָׁם עַל הַמָּיִם. אֶלָּא בְּהַהוּא זִמְנָא, שָׁלִיטוּ עַל אִינּוּן מַיָּא, דְּאִינּוּן תְּחוֹת עַנְפִּין דְּאִילָנָא, דְּאִקְרוּן (תהילים קכ״ד:ה׳) הַמַּיִם הַזֵּידוֹנִים. וְעַל דָּא אַשְׁרֵיכֶם זוֹרְעֵי עַל כָּל מָיִם.</p>\n<p>מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר, אִינּוּן תְּרֵין כִּתְרֵי שְׂמָאלָא, דַּאֲחִידָן בְּהוּ עַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, דְּאִקְרוּן שׁוֹר וַחֲמוֹר. וְהַיְינוּ דִּכְתִּיב, (בראשית לכ) וַיְהִי לִי שׁוֹר וַחֲמוֹר. בְּגִין דְּלָבָן חַכִּים הֲוָה בַּחֲרָשִׁין וּבְאִינּוּן כִּתְרִין תַּתָּאִין, וּבְאִינּוּן בָּעָא לְאוֹבָדָא לְיַעֲקֹב, כְּמָה דִּכְתִּיב, (דברים כ״ו:ה׳) אַרָמִי אוֹבֵד אָבִי, וְהָא אִתְּמַר. וּכְשֶׁיִּשְׂרָאֵל זַכָּאִין, מְשַׁלְּחֵי לְהוּ, וְלָא יַכְלֵי לְשַׁלְּטָאָה עָלַיְיהוּ, הֲדָא הוּא דִכְתִיב מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר דְּלָא שַׁלְטֵי בְּהוּ.</p>\n<p>אָמַר רִבִּי אַבָּא, כַּד מִזְדַּוְּוגֵי כַּחֲדָא, לָא יַכְלֵי בְּנֵי עָלְמָא לְמֵיקָם בְּהוּ, וְעַל דָּא <Nonei></i>כְּתִיב (דברים כ״ב:י׳) לא תַחֲרוֹשׁ בְּשׁוֹר וּבַחֲמוֹר יַחְדָּיו. יַחְדָּיו דַּיְיקָא. וְתָנֵינָן, לָא יָהִיב אִינִישׁ דּוּכְתָּא לְזִינִין בִּישִׁין, דְּהָא בְּעוֹבָדָא דְּבַּר נָשׁ (לתתא), אִתְּעַר מַה דְּלָא אִצְטְרִיךְ. וְכַד מִזְדַּוְּוגֵי כַּחֲדָא, (לא יכלין למיקם בהו. מבין סטרא דלהון נפיק) מִתְּקִיפוּתָא דִּלְהוֹן דְּאִקְרֵי כֶּלֶב, וְדָא חֲצִיפָא מִכֻּלְּהוּ, הֲדָא הוּא דִכְתִיב, (שמות י״א:ז׳) וּלְכָל בְּנֵי יִשְׂרָאֵל לא יֶחרַץ כֶּלֶב לְשׁוֹנוֹ. (נ\"א מתקיפותא דלהון אפיק ההוא דאקרי כלב, ודא חציפא מכלהו) אָמַר קוּדְשָׁא בְּרִיךְ הוּא, אַתּוּן אֲמַרְתּוּן, הֲיֵשׁ יְיָ' בְּקִרְבֵּנוּ אִם אָיִן, הֲרֵי אֲנִי מוֹסֵר אֶתְכֶם לַכֶּלֶב. מִיָּד וַיָּבֹא עֲמָלֵק.</p>\n<p>ר' יְהוּדָה אָמַר, (במדבר כ״ד:כ׳) רֵאשִׁית גּוֹיִם עֲמָלֵק וְאַחֲרִיתוֹ עֲדֵי אוֹבֵד. וְכִי רֵאשִׁית גּוֹיִם עֲמָלֵק, וַהֲלֹא כַּמָּה לִישָׁנִין וְעַמִּין וְאוּמִין הֲווֹ בְּעָלְמָא, עַד לָא אָתָא עֲמָלֵק.</p>\n<p>אֶלָּא, כַּד נַפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, דְּחִילוּ וְאֵימָתָא נָפְלָה עַל כָּל עַמִּין דְּעָלְמָא מִיִּשְׂרָאֵל, הֲדָא הוּא דִכְתִיב, (שמות ט״ו:י״ד) שָׁמְעוּ עַמִּים יִרְגָּזוּן חִיל אָחַז יוֹשְבֵי פְּלָשֶׁת. וְלָא הֲווֹ עַמָּא דְּלָא הֲוָה דָּחִיל מִגְּבוּרָאן עִלָּאִין דְּקוּדְשָׁא בְּרִיךְ הוּא, וַעֲמָלֵק לָא הֲוָה דָּחִיל, הֲדָא הוּא דִכְתִיב, וְלֹא יָרֵא אֱלהִים. לָא דָּחִיל לְמִקְרַב לְגַבָּךְ. וְעַל דָּא רֵאשִׁית גּוֹיִם.</p>\n<p>(עמלק הוי קדמאה) דְּאָתוּ לְאַגָּחָא קְרָבָא בְּיִשְׂרָאֵל עֲמָלֵק הֲוָה. וּבְגִינֵי כַּךְ וְאַחֲרִיתוֹ עֲדֵי אוֹבֵד, דִּכְתִּיב כִּי מָחֹה אֶמְחֶה אֶת זֵכֶר עֲמָלֵק. וּכְתִיב, (דברים כ״ה:י״ט) תִּמְחֶה אֶת זֵכֶר עֲמָלֵק, הֲדָא הוּא דִכְתִיב וְאַחֲרִיתוֹ עֲדֵי אוֹבֵד. עֲדֵי אָבְדוֹ מִבָּעֵי לֵיהּ. אֶלָּא עַד דְּיֵיתֵי קוּדְשָׁא בְּרִיךְ הוּא וְיֹאבַד לֵיהּ, (כלומר עד דקודשא בריך הוא יהא אובד ליה) דִּכְתִּיב כִּי מָחֹה אֶמְחֶה וְגוֹ'. אָמַר ר' אֶלְעָזָר, תָּא חֲזֵי, אַף עַל גַּב דְּהַצּוּר תָמִים פָּעֳלוֹ, וְעָבִיד עִמְּהוֹן חֶסֶד לְאַפָּקָא לוֹן מַיָּא, לָא שָׁבַק דִּידֵיהּ, דְּהָא כְּתִיב וַיָּבֹא עֲמָלֵק.</p>\n<p>ר' אַבָּא פָּתַח וְאָמַר, (קהלת ה׳:י״ב) יֵשׁ רָעָה חוֹלָה רָאִיתִי תַּחַת הַשָּׁמֶשׁ. כַּמָּה בְּנֵי נָשָׁא אֲטִימִין לִבָּא, בְּגִין דְּלָא מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא. יֵשׁ רָעָה חוֹלָה, וְכִי יֵשׁ רָעָה דְּהִיא חוֹלָה, וְיֵשׁ רָעָה דְּלָאו הִיא חוֹלָה. אֶלָּא וַדַּאי יֵשׁ רָעָה חוֹלָה, דְּתָנֵינָן, מִסִּטְרָא דִּשְׂמָאלָא, נַפְקֵי כַּמָּה גַּרְדִּינִי נִימּוּסִין, דְּבַקְעָן בַּאֲוִירָא.</p>\n<p>וְכַד בַּעְיָין לְמֵיפַק, אַזְלִין וְאִשְׁתַּאֲבִין בְּנוּקְבָא דִּתְהוֹמָא רַבָּה, לְבָתַר נָפְקִין וּמִתְחַבְּרָן כַּחֲדָא, וּבְקָעִין אֲוִירִין, וְשָׁאטִין בְּעָלְמָא, וּמִתְקָרְבִין לְגַבַּיְיהוּ דִּבְנֵי נָשָׁא, וְכָל חַד אִקְרֵי רָעָה, כְּמָה דְאַתְּ אָמֵר (תהילים צ״א:י׳) לא תְאוּנֶּה אֵלֶיךָ רָעָה. מַאי לא תְאוּנֶּה. בְּגִין דְּאַתְיָא בְּתַסְקוּפָא עַל בְּנִי נָשָׁא.</p>\n<p>חוֹלָה אֲמַאי הִיא חוֹלָה. כַּד שַׁרְיָא הַאי עַל בְּנֵי נָשָׁא, עָבִיד לוֹן קַמְצָנִין מִמָּמוֹנֵיהוֹן, אַתְיָין גַּבָּאי צְדָקָה גַּבֵּיהּ, הִיא מָחָאת בִּידֵיהּ. אֲמַר לֵיהּ לֹא תִּיפּוּק מִדִּידָךְ. אַתְיָין מִסְכְּנֵי, הִיא מָחָאת בִּידֵיהּ. אָתֵי הוּא לְמֵיכַל מִמָּמוֹנֵיהּ, מָחָאת בִּידֵיהּ, בְּגִין לְנַטְרָא לֵיהּ לְאָחֳרָא. וּמִן יוֹמָא דְּשַׁרְיָא עָלֵיהּ דְּבַר נָשׁ, הִיא חוֹלָה, כְּהַאי שָׁכִיב מֵרַע דְּלָא אָכִיל וְלָא שְׁתֵּי. וְעַל דָּא הִיא רָעָה חוֹלָה.</p>\n<p>וּשְׁלמֹה מַלְכָּא צָוַוח בְּחָכְמְתָא וְאָמַר, (קהלת ו׳:ב׳) אִישׁ אֲשֶׁר יִתֵּן לוֹ הָאֱלֹהִים עֹשֶׁר וּנְכָסִים וְכָבוֹד וְגוֹ'. הַאי קְרָא, לָאו רֵישֵׁיהּ סֵיפֵיהּ, וְלָאו סֵיפֵיהּ רֵישֵׁיהּ, כְּתִיב אִישׁ אֲשֶׁר יִתֵּן לוֹ הָאֱלהִים עֹשֶׁר וּנְכָסִים וְכָבוֹד וְגוֹ', מַאי וְלֹא יַשְׁלִיטֶנּוּ הָאֱלֹהִים לֶאֱכוֹל מִמֶּנּוּ. אִי הָכִי, לָאו בִּרְשׁוּתֵיהּ הוּא דְּבַּר נָשׁ.</p>\n<p>אֶלָּא, אִי כְּתִיב וְלֹא יַעַזְבֶנוּ הָאֱלהִים לֶאֱכוֹל מִמֶּנּוּ, הֲוֵינָא אָמַר הָכִי. אֶלָּא וְלא יַשְׁלִיטֶנּוּ, דִּבְגִין דְּהוּא הֵימְנֵיהּ לְהַהִיא רָעָה, וְאָחִיד בָּהּ. קוּדְשָׁא בְּרִיךְ הוּא לָא שַׁלְטֵיהּ עָלֵיהּ, לְאִתְבָּרָאָה תְּחוֹתֵיהּ, עַל דְּהוּא אִתְרְעֵי בָּהּ, וְאָחִיד בָּהּ.</p>\n<p>וְכָל אָרְחוֹי כִּשְׁכִיב מֵרַע, דְּלָא אָכִיל וְלָא שְׁתֵי, וְלָא קָרִיב לְמָמוֹנֵיהּ, וְלָא אַפִּיק מִינֵּיהּ, וְנָטִיר לֵיהּ עַד דְּהוּא יִפּוּק מֵעָלְמָא, וְיֵיתֵי אַחֲרָא, וְיִטּוֹל לֵיהּ, דְּהוּא בְּעָלָיו.</p>\n<p>וּשְׁלמֹה מַלְכָּא צָוַוח וְאָמַר, (קהלת ה׳:י״ב) עֹשֶׁר שָׁמוּר לִבְעָלָיו לְרָעָתוֹ. מַאן בְּעָלָיו. דָּא אַחֲרָא דְּיָרִית לֵיהּ. וְלָמָּה זָכָה הַאי אַחֲרָא לְמֶהֱוֵי בְּעָלָיו דְּהַהוּא עֻתְרָא. בְּגִין דְּהַאי הֵימִין לְהַהִיא רָעָה, וְאִתְּרָעֵי בָּה (הדא הוא דכתיב לרעתו בשביל ההוא רע) וְאִתְדָבַּק בָּה. בְּגִין כָּךְ, הַאי אַחֲרָא דְּלָא אִתְדַּבָּק בְּהַהִיא רָעָה, זָכָה (האי) לְמֶהֱוֵי בְּעָלָיו דְּהַהוּא עֻתְרָא הֲדָא הוּא דִכְתִיב לְרָעָתוֹ, כְּלוֹמַר בְּגִין רָעָתוֹ דְּהֲוָה מִתְדָּבַק בָּהּ, רָוַוח לֵיהּ הַאי.</p>\n<p>דָּבָר אַחֵר יֵשׁ רָעָה חוֹלָה, הַאי מַאן דְּיָתִיב בְּחוּלָקָא טָבָא, בְּבֵית אֲבוֹי, וְהוּא אָזִיל לָקֳבֵל אֲבוֹי, <Nonei></i>בְּתַסְקוּפֵי מִלִּין, הָא אִתְדְּבַק בְּהַהוּא רָעָה חוֹלָה, כְּבַר נָשׁ שָׁכִיב מֵרַע דְּכָל אָרְחוֹי בְּתַסְקוּפָא, דָּא בְּעֵינָא, וְדָא לָא בְּעֵינָא, וּבְגִין הַאי עוּתְרָא אִתְדָּבַּק בַּר נָשׁ בְּרָעָה חוֹלָה, וְאִתְעֲנָשׁ בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי, וְדָא הוּא עוֹשֶׁר שָׁמוּר לִבְעָלָיו לְרָעָתוֹ.</p>\n<p>כַּךָ יִשְׂרָאֵל, קוּדְשָׁא בְּרִיךְ הוּא נָטִיל לוֹן עַל גַּדְפֵּי נִשְׁרִין, אַסְחַר לוֹן בַּעֲנָנִי יְקָרָא, שְׁכִינְתֵּיהּ נָטִיל קָמַיְיהוּ, נָחַת לוֹן מָנָא לְמֵיכַל, אַפִּיק לוֹן מַיָּיא מְתוּקִין, וְאִינּוּן הֲווֹ אַזְלִין עִמֵּיהּ בְּתַסְקוּפִין. מִיַּד וַיָּבֹא עֲמָלֵק.</p>\n<p>(שמות י״ז:ח׳) וַיָּבֹא עֲמָלֵק, אָמַר רִבִּי שִׁמְעוֹן, רָזָא דְּחָכְמְתָא הָכָא, מִגִּזְרַת דִּינָא קַשְׁיָא, קָא אַתְיָא קְרָבָא דָּא. וּקְרָבָא דָּא אִשְׁתְּכַח לְעֵילָּא וְתַתָּא. וְלֵית לָךְ מִלָּה בְּאוֹרַיְיתָא, דְּלָא אִית בָּהּ רָזִין עִלָּאִין דְּחָכְמְתָא, דְּמִתְקַשְּׁרִין בִּשְׁמָא קַדִּישָׁא. כִּבְיָכוֹל, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, כַּד יִשְׂרָאֵל אִינּוּן זַכָּאִין לְתַתָּא, אִתְגַּבָּר חֵילָא דִּילִי עַל כֹּלָּא. וְכַד לָא אִשְׁתְּכָחוּ זַכָּאִין, כִּבְיָכוֹל, מַתִּישִׁין חֵילָא דִּלְעֵילָּא, וְאִתְגַּבַּר חֵילָא דְּדִינָא קַשְׁיָא.</p>\n<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּחָבוּ יִשְׂרָאֵל לְתַתָּא, מַה כְּתִיב, וַיָּבֹא עֲמָלֵק וַיִּלָּחֶם עִם יִשְׂרָאֵל, אָתָא לְקַטְרְגָא דִּינָא בְּרַחֲמֵי. דְּכֹלָּא אִשְׁתְּכַח לְעֵילָּא וְתַתָּא. בִּרְפִידִים: בְּרָפוּי יָדַיִם, דְּרָפוּ יְדֵיהוֹן מֵאוֹרַיְיתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּאוֹקִימְנָא. אָמַר ר' יְהוּדָה, תְּרֵי זִמְנֵי אַגָּח קְרָבָא עֲמָלֵק בְּיִשְׂרָאֵל, חַד הָכָא. וְחַד דִּכְתִּיב, (במדבר י״ד:מ״ה) וַיֵּרֶד הָעֲמָלֵקֵי וְהַכְּנַעֲנִי וְגוֹ'.</p>\n<p>אָמַר ר' שִׁמְעוֹן, לְעֵילָּא וְתַתָּא. קִטְרוּגָא דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה, לְעֵילָּא, כְּמָה דְּאִתְּמַר. לְתַתָּא בְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה, דַּהֲווֹ נַסְבֵּי לְגַבְרֵי, וְגַזְרֵי לוֹן עָרְלָתָא (ס\"א אתא) דִּרְשִׁימָא קַדִּישָׁא, וְנַטְלֵי לְהוּ וְאַרְמוּ לוֹן לְעֵילָּא, וְאַמְרֵי טוֹל לָךְ מַה דְּאִתְרְעִית. וְעַל כָּל פָּנִים דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה (כל קובלנא כלא) (ס\"א קבלא) כֹּלָּא.</p>\n<p>(שמות י״ז:ט׳) וַיֹּאמֶר מֹשֶׁה אֶל יְהוֹשֻׁעַ בָּחַר לָנוּ אֲנָשִׁים וְצֵא הִלָּחֵם בַּעֲמָלֵק. וְכִי מַה חָמָא מֹשֶׁה, דְּסָלִיק גַּרְמֵיהּ, מֵהַאי קְרָבָא קַדְמָאָה דְּקוּדְשָׁא בְּרִיךְ הוּא פָּקִיד. אֶלָּא מֹשֶׁה זַכָּאָה חוּלָקֵיהּ, דְּאִסְתַּכַּל וְיָדַע עִקָרָא דְּמִלָּה. אָמַר מֹשֶׁה, אֲנָא אַזְמִין גַּרְמִי לְהַהוּא קְרָבָא דִּלְעֵילָּא, וְאַנְתְּ יְהוֹשֻׁעַ זַמִּין גַּרְמָךְ לְקָרְבָא דִּלְתַתָּא.</p>\n<p>וְהַיְינוּ דִּכְתִּיב, וְהָיָה כַּאֲשֶׁר יָרִים מֹשֶׁה יָדוֹ וְגָבַר יִשְׂרָאֵל: יִשְׂרָאֵל דִּלְעֵילָּא. וּבְגִין כַּךְ סָלִיק מֹשֶׁה גַּרְמֵיהּ מִקְּרָבָא דִּלְתַתָּא, בְּגִין לְאִזְדָּרְזָא בִּקְרָבָא דִּלְעֵילָּא, וְיִתְנְצַח עַל יְדוֹי.</p>\n<p>אָמַר ר' שִׁמְעוֹן, וְכִי קַלָהּ הִיא בְּעֵינֶיךָ, קְרָבָא דָּא דַּעֲמָלֵק. תָּא חֲזֵי, מִן יוֹמָא דְּאִתְבְּרֵי עָלְמָא, עַד הַהוּא זִמְנָא, וּמֵהַהוּא זִמְנָא, עַד דְּיֵיתֵי מַלְכָּא מְשִׁיחָא, וַאֲפִילּוּ בְּיוֹמוֹי דְּגוֹג וּמָגוֹג, לָא יִשְׁתְּכַּח כְּוָותֵיהּ. לָאו בְּגִין חַיָּילִין תַּקִּיפִין וְסַגִּיאִין, אֶלָּא בְּגִין דִּבְכָל סִטְרִין דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה.</p>\n<p>וַיֹּאמֶר מֹשֶׁה אַל יְהוֹשֻׁעַ, אֲמַאי לִיהוֹשֻׁעַ, וְלָא לְאָחֳרָא, וְהָא בְּהַהוּא זִמְנָא רַבְיָא הֲוָה, דִּכְתִּיב, (שמות ל״ג:י״א) וִיהוֹשֻׁעַ בִּן נוּן נַעַר, וְכַמָּה הֲווֹ בְּיִשְׂרָאֵל תַּקִּיפִין מִנֵּיהּ. אֶלָּא מֹשֶׁה בְּחָכְמְתָא אִסְתָּכַּל וְיָדַע. מַאי חָמָא. חָמָא לסמאל דְּהֲוָה נָחִית מִסִּטְרָא דִּלְעֵילָּא, לְסַיְּיעָא לַעֲמָלֵק לְתַתָּא. אָמַר מֹשֶׁה, וַדַּאי קְרָבָא הָכָא תַּקִּיפָא אִתְחָזִיִ.</p>\n<p>יְהוֹשֻׁעַ בְּהַהוּא זִמְנָא בְּדַרְגָּא עִלָּאָה יַתִּיר אִשְׁתְּכַח. אִי תֵּימָא דִּבְשְׁכִינְתָּא אִשְׁתְּכַח בְּהַהוּא זִמְנָא לָאו הָכִי, דְּהָא בְּמֹשֶׁה אִתְנְסִיבַת וְאִתְאַחֲדַת, אִשְׁתְּכַח יְהוֹשֻׁעַ דְּאִתְאַחֲד לְתַתָּא מִינָּהּ. וּבַמֶּה. אָמַר ר' שִׁמְעוֹן, בְּהַהוּא אֲתָר, דְּאִתְקְרֵי נַעַ\"ר.</p>\n<p>וְהַיְינוּ דְּאָמַר רִבִּי יְהוּדָה, מַאי דִּכְתִּיב, (ישעיהו ל״ג:כ׳) עֵינֶיךָ תִּרְאֶינָה יְרוּשָׁלַ ם נָוְה שַׁאֲנָן אֹהֶל בַּל יִצְעָן בַּל יִסַּע יְתֵדוֹתָיו לָנֶצַח. יְרוּשָׁלַ ם: יְרוּשָׁלַ ם דִּלְעֵילָּא, דְּאִקְרֵי אֹהֶל בַּל יִצְעָן, דְּלָא יִשְׁתְּכַּח יַתִּיר לְמֵהַךְ בְּגָלוּתָא, וְדָא הוּא רָזָא דִּכְתִּיב, וִיהוֹשֻׁעַ בִּן נוּן נַעַר. נַעַר וַדַּאי. לא יָמִישׁ מִתּוֹךְ הָאֹהֶל, הַהוּא דְּאִקְרֵי אֹהֶל בַּל יִצְעָן. מְלַמֵּד דִּבְכָל יוֹמָא וְיוֹמָא, הֲוָה יָנִיק מִשְׁכִינְתָּא, כְּמָה דְּהַהוּא נַעַר דִּלְעֵילָּא, לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל, וְיָנִיק מִנֵּיהּ תָּדִירָא. כַּךְ הַאי נַעַר <Nonei></i>דִּלְתַתָּא לא יָמִישׁ מִתּוֹךְ הָאֹהֶל, וְיָנִיק מִנָּהּ תָּדִירָא.</p>\n<p>בְּגִין כַּךְ, כַּד חָמָא מֹשֶׁה, לסמאל, נָחִית לְסַיְּיעָא לַעֲמָלֵק, אָמַר מֹשֶׁה, וַדַּאי הַאי נַעַר יְקוּם לָקֳבְלֵיהּ, וְיִשְּׁלוֹט עָלֵיהּ, לְנַצְּחָא לֵיהּ. מִיַּד וַיֹּאמֶר מֹשֶׁה אֶל יְהוֹשֻׁעַ בָּחַר לָנוּ אֲנָשִׁים וְצֵא הִלָּחֵם בַּעֲמָלֵק, דִּילָךְ הַאי קְרָבָא דִּלְתַתָּא, וַאֲנָא אִזְדָּרֵז לִקְרָבָא דִּלְעֵילָּא. בָּחַר לָנוּ אֲנָשִׁים, זַכָּאִין בְּנֵי זַכָּאִין, דְּיִתְחֲזוּן לְמֵהַךְ עִמָּךְ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּשַׁעֲתָא דְּנָפִיק יְהוֹשֻׁעַ נַעַר. אִתְּעַר נַעַר דִּלְעֵילָּא, וְאִתְתָּקַּן בְּכַמָּה תִּיקּוּנִין בְּכַמָּה זַיְינִין, דְּאַתְקִינַת לֵיהּ אִמֵיהּ, לִקְרָבָא דָּא, לְנַקְמָא נוּקְמָא דִּבְרִית. וְהַיְינוּ דִּכְתִּיב, (ויקרא כ״ו:כ״ה) חֶרֶב נוֹקֶמֶת נְקַם בְּרִית, וְדָא הוּא רָזָא דִּכְתִּיב, וַיַּחֲלשׁ יְהוֹשֻׁעַ אֶת עֲמָלֵק וְאֶת עַמּוֹ לְפִי חָרֶב. לְפִי חֶרֶב וַדַּאי, וְלָא לְפוּם רוּמְחִין וְזַיְינִין, אֶלָּא בַּחֶרֶב וַדַּאי הִיא, הַאי דְּאִקְרֵי חֶרֶב נוֹקֶמֶת נְקַם בְּרִית.</p>\n<p>וּמֹשֶׁה אִתְתָּקַּן לִקְרָבָא דִּלְעֵילָּא, וִידֵי מֹשֶׁה כְּבֵדִים: כְּבֵדִים מַמָּשׁ, יַקִּירִין, קַדִּישִׁין, לָא אִסְתַאְבָן לְעָלְמִין. יְקִרִין דְּאִתְחָזוּן לְאַגָּחָא בְּהוּ קְרָבָא דִּלְעֵילָּא. וַיִקְחוּ אֶבֶן וַיָּשִׂימוּ תַחְתָּיו וַיֵּשֶׁב עָלֶיהָ, בְּגִין דְּיִשְׂרָאֵל שַׁרְיָין בְּצַעֲרָא, וִיהֵא עִמְּהוֹן בְּצַעֲרֵיהוֹן.</p>\n<p>וְאַהֲרֹן וְחוּר תָּמְכוּ בְיָדָיו מִזֶּה אֶחָד וּמִזֶּה אֶחָד וַיְהִי יָדָיו אֱמוּנָה וְגוֹ', מַאי תָּמְכוּ בְיָדָיו. אֱמוּנָה. (אמונה, מהימנותא ודא) וְכִי עַל דְּאַהֲרֹן וְחוּר תְּמִיכוּ לִידוֹי, הֲווֹ יְדוֹי אֱמוּנָה. אֶלָּא, מֹשֶׁה כֹּלָּא בְּחָכְמְתָא עָבִיד מַה דְּעָבִיד. אַהֲרֹן וְחוּר, דָּא מִסִּטְרָא דִּילֵיהּ, וְדָא מִסִּטְרָא דִּילֵיהּ, וְיָדוֹי בְּאֶמְצָעִיתָא, וְעַל דָּא וַיְהִי יָדָיו אֱמוּנָה, מְהֵימָנוּתָא. אַהֲרֹן בְּגִין דְּיִתְּעַר סִטְרָא דִּילֵיהּ, (חוקת קל\"א ע\"ב) וְחוּר בְּגִין דְּיִתְּעַר סִטְרָא דִּילֵיהּ, וַהֲווּ אֲחִידָן בִּידוֹי מִכָּאן וּמִכָּאן, דְּאִשְׁתַּכְחָא סִיוּעָא דִּלְעֵילָּא.</p>\n<p>(שמות י״ז:י״א) וְהָיָה כַּאֲשֶׁר יָרִים מֹשֶׁה יָדוֹ וְגָבַר יִשְׂרָאֵל. כַּאֲשֶׁר יָרִים: דְּזָקִיף יְמִינָא עַל שְׂמָאלָא, וְאִתְכָּוַּון בִּפְרִישׁוּ דְּיָדוֹי. וְגָבַר יִשְׂרָאֵל: יִשְׂרָאֵל דִּלְעֵילָּא. וְכַאֲשֶׁר יָנִיחַ יָדוֹ וְגָבַר עֲמָלֵק, בְּשַׁעֲתָא דְּיִשְׂרָאֵל לְתַתָּא, מִשְׁתַּכְּכִין מִצְּלוֹתָא, לָא יַכְלִין יְדֵי מֹשֶׁה לְמֵיקָם בִּזְקִיפוּ, וְגָבַר עֲמָלֵק. מִכָּאן אוֹלִיפְנָא, אַף עַל גַּב דְּכַהֲנָא פָּרִישׂ יְדוֹי, בְּקָרְבְּנָא, לְתַקְּנָא גַּרְמֵיהּ בְּכֹלָּא, יִשְׂרָאֵל בַּעְיָין לְאִשְׁתַּכְּחָא בִּצְלוֹתְהוֹן, עִמֵּיהּ.</p>\n<p>תָּאנָא, בִּקְרָבָא דָּא דַּעֲמָלֵק, אִשְׁתְּכָחוּ עִלָּאִין וְתַתָּאִין, וְעַל דָּא, וַיְהִי יָדָיו אֱמוּנָה, בְּהֵימְנוּתָא כַּדְקָא חֲזֵי. וַיְהִי יָדָיו אֱמוּנָה. וַיִּהְיוּ יָדָיו מִבָּעֵי לֵיהּ. אֶלָּא, בְּגִין דְּתַלְיָא כֹּלָּא בִּימִינָא, כְּתִיב וַיְהִי. וּכְתִיב יָדָיו, בְּגִין דְּהוּא עִקָרָא דְּכֹלָּא. וּכְתִיב, (שמותטו) יְמִינְךָ יְיָ' נְאְדָּרִי בַּכֹּחַ יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב.</p>\n<p>(שמות י״ז:י״ד) וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה כְּתֹב זֹאת זִכָּרוֹן בְּסֵפֶר וְגוֹ'. תָּא חֲזֵי, מַה כְּתִיב לְעֵילָּא, וַיַּחֲלוֹשׁ יְהוֹשֻׁעַ אֶת עֲמָלֵק וְאֶת עַמּוֹ לְפִי חָרֶב. וַיַּחֲלשׁ, וַיַּהֲרוֹג מִבָּעֵי לֵיהּ. אֶלָּא, וַיַּחֲלשׁ, כְּמָה דְּאִתְּמַר, (ישעיהו י״ד:י״ב) חוֹלֵשׁ עַל גּוֹיִם. יְהוֹשֻׁעַ הֲוָה חוֹלֵשׁ עָלַיְיהוּ, וְהַהוּא חֶרֶב נוֹקֶמֶת נְקַם בְּרִית קָטִיל לוֹן, דִּכְתִּיב לְפִי חָרֶב כְּמָה דְּאִתְּמַר.</p>\n<p>כְּתֹב זֹאת זִכָּרוֹן, זֹאת דַּיְקָא. וְשִׂים בְּאָזְנֵי יְהוֹשֻׁעַ, דְּהָא הוּא זָמִין לְקָטְלָא מַלְכִין אַחֲרָנִין. כִּי מָחֹה אֶמְחֶה. מָחֹה: לְעֵילָּא. אֶמְחֶה: לְתַתָּא. זֵכֶר, דּוּכְרָנָא דִּלְעֵילָּא וְתַתָּא.</p>\n<p>אָמַר רִבִּי יִצְחָק, כְּתִיב כִּי מָחֹה אֶמְחֶה, וּכְתִיב (דברים כ״ה:י״ט) תִּמְחֶה אֶת זֵכֶר עֲמָלֵק. אֶלָּא, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, אַתּוּן מָחוּן דּוּכְרָנֵיהּ לְתַתָּא, וַאֲנָא אֶמְחֶה דּוּכְרָנֵיהּ לְעֵילָּא.</p>\n<p>אָמַר רִבִּי יוֹסֵי, עֲמָלֵק עַמִּין אַחֲרָנִין אַייתִין עִמֵּיהּ, וְכֻלְּהוּ דְּחִילוּ לְקָרְבָא בְּהוּ בְּיִשְׂרָאֵל, בַּר אִיהוּ. וּבְגִין כַּךְ, יְהוֹשֻׁעַ הֲוָה חוֹלֵשׁ עָלַיְיהוּ. רִבִּי יֵיסָא אָמַר, וַיַּחֲלֹשׁ יְהוֹשֻׁעַ, דְּתָבַר חֵילָא דִּלְהוֹן מִלְּעֵילָּא.</p>\n<p>(שמות י״ז:ט״ו) וַיִּבֶן מֹשֶׁה מִזְבֵּחַ וַיִּקְרָא שְׁמוֹ יְיָ' נִסִּי. וַיִּבֶן מֹשֶׁה מִזְבֵּחַ, לָקֳבֵל הַהוּא דִּלְעֵילָּא. וַיִּקְרָא שְׁמוֹ הַהוּא מֹשֶׁה (נ\"א דההוא מזבח) יְיָ' נִסִּי. מַאי יְיָ' נִסִּי. בְּגִין דְּאַנְקִים נִקְמָתָא דְּהַהוּא רְשִׁימָא <Nonei></i>קַדִּישָׁא דְּיִשְׂרָאֵל, וּמֵהַהוּא זִמְנָא אִתְקְרֵי, חֶרֶב נוֹקֶמֶת נְקַם בְּרִית.</p>\n<p>רִבִּי יוֹסֵי אָמַר, וַיִּבֶן מֹשֶׁה מִזְבֵּחַ, מִזְבַּח לְכַפְּרָא עָלַיְיהוּ. וַיִּקְרָא שְׁמוֹ. שְׁמוֹ דְּמַאן. אָמַר רִבִּי חִיָּיא שְׁמֵיהּ דְּמַדְבְּחָא הַהוּא. יְיָ' נִסִּי: כְּמָה דְאַתְּ אָמֵר, וְשָׁם נִסָּהוּ. וְכֹלָּא מִלָּה חַד, עַל דְּאִתְפְּרָעוּ יִשְׂרָאֵל, וְאִתְגַּלְיָיא הַהוּא אָת קַיָּימָא, רְשִׁימָא קַדִּישָׁא. מִכָּאן אוֹלִיפְנָא, דְּכֵיוָן דְּאִתְגְּזַר בְּרֵיהּ דְּבַר נָשׁ, וְאִתְגַּלְיָיא בֵּיהּ אָת רְשִׁימָא קַדִּישָׁא קַיָּימָא. הַהוּא אִקְרֵי מִזְבֵּחַ לְכַפְּרָא עָלֵיהּ. וּמַה שְׁמֵיהּ. יְיָ' נִסִּי.</p>\n<p>כְּגַוְונָא דָּא יַעֲקֹב, בְּנָהּ מַדְבְּחָא, דִּכְתִּיב, (בראשית ל״ג:כ׳) וַיַּצֶּב שָׁם מִזְבֵּחַ וַיִּקְרָא לוֹ אֵל אֱלהֵי יִשְׂרָאֵל. לְמַאן. לְהַהוּא אֲתָר דְּאִקְרֵי מִזְבֵּחַ. וּמַאן שְׁמֵיהּ. אֵל אֱלֹהֵי יִשְׂרָאֵל.</p>"],[9520011632,"<p>אָמַר רִבִּי יוֹסֵי, מַאי דִּכְתִּיב, (שמות כ״ד:י׳) וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל וְגוֹ'. וְכִי מַאן יָכִיל לְמֵחמֵי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְהָא כְּתִיב (שמות ל״ג:כ׳) כִּי לא יִרְאַנִי הָאָדָם וָחָי. וְהָכָא אָמַר וַיִּרְאוּ אֶלָּא דְּאִתְגַּלְיָא קֶשֶׁת עָלַיְיהוּ בִּגְוָונִין נְהִירִין, וְהָכִי תָּנֵינָן, כָּל מַאן דְּאִסְתַּכַּל בַּקֶּשֶׁת, כְּמַאן דְּמִסְתַּכַּל בַּשְּׁכִינָה, וּלְאִסְתַּכְּלָא בִּשְׁכִינְתָּא אָסִיר.</p>\n<p>וְעַל דָּא, אָסִיר לֵיהּ לְאִינִישׁ, לְאִסְתַּכְּלָא בְּאֶצְבְּעַיְיהוּ דְּכַהֲנֵי, בְּשַׁעֲתָא דְּפַרְסֵי יְדַיְיהוּ. אָסוּר לְאִסְתַּכְּלָא בַּקֶּשֶׁת. מַאן קֶשֶׁת. אָמַר רִבִּי אַבָּא, בַּקֶּשֶׁת סְתָם אָמַר לֵיהּ מַאי בַּקֶּשֶׁת סְתָם אֲמַר לֵיהּ בַּקֶּשֶׁת דִּלְעֵילָּא, וּבַקֶּשֶׁת דִּלְתַתָּא.</p>\n<p>בַּקֶּשֶׁת דִּלְעֵילָּא, בִּגְוָונוֹי. דְּכָל מַאן דְּיִסְתַּכַּל בִּגְוָונוֹי, כְּאִילּוּ אִסְתַּכַּל בְּאֲתָר דִּלְעֵילָּא, וְאָסִיר לְאִסְתַּכְּלָא בֵּיהּ, דְּלָא יַעֲבִיד קְלָנָא בִּשְׁכִינְתָּא. קֶשֶׁת דִּלְתַתָּא מַאי הִיא. הַהוּא אָת קַיָּימָא, דְּאִתְרְשִׁים בֵּיהּ בְּבַר נָשׁ, דְּכָל מַאן דְּיִסְתַּכַּל בֵּיהּ, עָבִיד קְלָנָא לְעֵילָּא.</p>\n<p>אָמַר רִבִּי יִצְחָק, אִי הָכִי וְהָכְתִיב (בראשית כ״ד:ב׳) שִׂים נָא יָדְךָ תַּחַת יְרֵכִי, דְּהֲוָה אוֹמֵי לֵיהּ בְּהַאי אָת. אֲמַר לֵיהּ, אֲנַח לְהוּ לַאֲבָהָן דְּעָלְמָא, דְּלֵית אִינּוּן כִּשְׁאַר בְּנֵי עָלְמָא. וְעוֹד, שִׂים נָא יָדְךָ תַּחַת יְרֵכִי כְּתִיב, וְלָא כְּתִיב רְאֵה תַּחַת יְרֵכִי, בְּגִין כָּךְ אָסִיר לְאִסְתַּכְּלָא בַּקֶּשֶׁת סְתָם, כְּמָה דְּתָנֵינָן.</p>\n<p>תָּאנָא, וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל, דְּאִתְגַּלְיָא קֶשֶׁת עָלַיְיהוּ, בִּגְוָונִין שַׁפִּירִין נְהִירִין, מְלַהֲטָן לְכָל עִיבָר, מַשְׁמַע דִּכְתִּיב, אֵת אֱלֹהֵי יִשְׂרָאֵל וְלָא כְּתִיב וַיִּרְאוּ אֱלהֵי יִשְׂרָאֵל. אָמַר רִבִּי יוֹסֵי, נְהוֹרָא דְּבוּצִינָא דִּשְׁכִינְתָּא. וּמַאי נִיהוּ. הַהוּא דְּאִקְרֵי נַעַר, דִּמְשַׁמֵּשׁ לִשְׁכִינְתָּא, בְּמַקְדְּשָׁא. וּבְגִין כַּךְ, אֵת דַּיְיקָא.</p>\n<p>וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר, דְּאִתְרְשִׁים בֵּיהּ תְּחוֹת דּוּכְתֵּיהּ, חַד לְבֵינָתָא מֵאִינּוּן לְבֵנִין דַּהֲווֹ בָּנִין בְּמִצְרַיִם, דְּתָנֵינָן, אִתְּתָא חֲדָא אוֹלִידַת בְּמִצְרַיִם, וַהֲוָה אָתִין סַרְכֵי פַּרְעֹה, וְעָאלַת לֵיהּ בְּחַד לְבֵינָתָא, וְאָתָא פַּס יְדָא וְאָחִיד לֵיהּ, וְאִתְרְשִׁים תְּחוֹת רַגְלוֹי דִּשְׁכִינְתָּא, וְקַיְּימָא קָמֵיהּ, עַד דְּאִתּוֹקַד בֵּי מַקְדְּשָׁא דִּלְתַתָּא, דִּכְתִּיב, (איכה ב׳:א׳) וְלא זָכַר הֲדוֹם רַגְלָיו.</p>\n<p>ר' חִיָּיא אָמַר, לִבְנַת הַסַּפִּיר: נְהִירוּתָא דְּסַפִּיר, קַלְדִיטֵי בְּקַנְדִיטֵי גְּלִיפִין עִלָּאִין דִּלְעֵילָּא, דְּמִתְלַהֲטָא לְשִׁבְעִין וּתְרֵין עִבְרִי, הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ד:י״א) וִיסַדְתִּיךְ בַּסַּפִּירִים. (שמות כ״ד:י׳) וּכְעֶצֶם הַשָּׁמַיִם. מַאי עֶצֶם הַשָּׁמַיִם. אָמַר רִבִּי אַבָּא, מָה עֶצֶם הַשָּׁמַיִם, גְּלִיפָא בְּשִׁבְעִין וּתְרֵין עֲנָפִין, פַּרְחִין מְלַהֲטָן בְּכָל עִיבָר. אוּף הָכָא, חֵיזוּ דְּהַהוּא עֶצֶם הַשָּׁמַיִם כְּחֵיזוּ שְׁמַיָּא מַמָּשׁ. רִבִּי יְהוּדָה אָמַר, כֹּלָּא אִתְרְשִׁים בְּהַהוּא נְהִירוּ, דְּחֵיזוּ דְּמִתְגַּלְפָא מִסִּטְרָא דִּשְׁכִינְתָּא.</p>\n<p>אָמַר רִבִּי חִזְקִיָּה, אִי הָכִי, וְהָא שִׁתִּין אִינּוּן, בְּסַחֲרָנִיהּ דִּשְׁכִינְתָּא, דִּכְתִּיב, (שיר השירים ג׳:ז׳) שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ. אֲמַר לֵיהּ הָכִי הוּא וַדַּאי. אֶלָּא אִינּוּן שִׁתִּין, אִתְנְהִירוּ בִּתְרֵיסַר תְּחוּמִין, וְלָא אַעְדִּיאוּ מִסָּחֲרָנוּתָהָּא לְעָלְמִין. דְּתָנֵינָן, תְּרֵיסַר תְּחוּמִין, גְּלִיפִין עִלָּאִין, בְּמַתְקְלָא סְלִיקוּ, בְּאִילָנָא קַדִּישָׁא רַבָּא וְתַקִּיף. וְכֻלְּהוּ נְהִירִין בְּמַטְרוֹנִיתָא, כַּד אִתְחַבְּרַת בְּמַלְכָּא. וְדָא הוּא עֶצֶם הַשָּׁמַיִם, עֶצֶם הַשָּׁמַיִם מַמָּשׁ. וְכָל אִינּוּן נְהִירִין שְׁבִילִין, מְנָהֲרִין בֵּיהּ, בִּנְהִירוּ דְּמַטְרוֹנִיתָא.</p>\n<p>וְתָאנָא, נְהִירוּ דְּאִלֵּין שִׁתִּין, דְּסָחֲרָנָהָא, רְשִׁימִין בֵּיהּ בְּהַהוּא נַעַ\"ר, וְקָרֵינָן לְהוּ שִׁתִּין פּוּלְסֵי דְּנוּרָא, דְּאִתְלָבַּשׁ בְּהוּ מִסְּטָר דִּשְׁכִינְתָּא, מִתְלַהֲטָן בְּדִינָא, הֲדָא הוּא דִכְתִיב <Nonei></i>שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ.</p>"],[9520011633,"<p>תָּאנָא, וַיִּבֶן מֹשֶׁה מִזְבֵּחַ כְּמָה דַּאֲמֵינָא. וַיִּקְרָא שְׁמוֹ ה' נִסִּי. ה' נִסִּי מַמָּשׁ. אֲמַאי. בְּגִין דַּעֲמָלֵק נָטַל כָּל אִינּוּן דַּהֲווֹ גְּזִירִין, וְלָא אִתְפְּרָעוּ, וְגָזַר לוֹן וְשָׁדֵי לְהוּ לְעֵילָּא, וְאָמַר טוֹל מַה דְּאִתְרְעִית בֵּיהּ. בֵּיהּ שַׁעֲתָא מַה כְּתִיב. וַיֹּאמֶר כִּי יַד עַל כֵּס יָהּ מִלְחָמָה לַה' בַּעֲמָלֵק מִדֹּר דֹּר. מִדֹּר דֹּר חֲסֵרִין, מִדִּיּוּרִין דִּלְעֵילָּא, וּמִדִּיּוּרִין דִּלְתַתָּא.</p>\n<p>אָמַר רִבִּי יְהוּדָה, בְּכָל דָּרָא וְדָרָא, בְּכָל דָּרִין דְּאַתְיָין לְעָלְמָא, לֵית לָךְ דָּר דְּלֵית בְּהוּ מֵהַהוּא זַרְעָא בִּישָׁא, וקוּדְשָׁא בְּרִיךְ הוּא אֲגַח בְּהוּ קְרָבָא. (ר' יצחק אמר מדירותא דלתתא לדיורא דלעילא) וְעָלַיְיהוּ כְּתִיב (תהילים ק״ד:ל״ה) יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ וְגוֹ'. מִן הָאָרֶץ: בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי. בֵּיהּ זִמְנָא כְּתִיב, בָּרְכִי נַפְשִׁי אֶת ה' הַלְלוּיָהּ.</p>"],[9520011634,"<p>(שמות י״ח:א׳) וַיִּשְׁמַע יִתְרוֹ כֹּהֵן מִדְיָן חֹתֵן מֹשֶׁה אֵת כָּל אֲשֶׁר עָשָׂה וְגוֹ'. רַבִּי חִזְקִיָּה (נ\"א ר' אלעזר) פָּתַח וְאָמַר, (ויקרא ט׳:כ״ב) וַיִשָּׂא אַהֲרֹן אֶת יָדָו. כְּתִיב יָדוֹ חַד, בְּגִין דְּבָעֵי לְאָרָמָא יְמִינָא עַל שְׂמָאלָא, והָא אוֹקִימְנָא רָזָא.</p>\n<p>אַשְׁכַּחְנָא בְּסִפְרָא דְּשְׁלֹמֹה מַלְכָּא, דְּכָל מַאן דְּאָרִים יְדוֹי לְעֵילָּא, וְלָאו אִינּוּן בִּצְלוֹתִין וּבָעוּתִין, הַאי אִיהוּ בַּר נָשׁ, דְּאִתְלַטְיָיא מֵעֲשָׂרָה שׁוּלְטָנִין מְמָנָן. וְאִינּוּן (קהלת ז׳:י״ט) עֲשָׂרָה שַׁלִּיטִין אֲשֶׁר הָיוּ בָּעִיר. אִלֵּין אִינּוּן עַשְׂרָה דִּי מְמָנָן עַל פְּרִישׂוּ דְּיָדִין לְעֵילָּא לְנַטְלָא הַהוּא צְלוֹתָא, אוֹ הַהִיא בִּרְכָתָא, וְיָהֲבֵי בֵּיהּ חֵילָא, לְאִתְיַקְּרָא שְׁמָא קַדִּישָׁא, וְאִתְבְּרַךְ מִתַּתָּא. כֵּיוָן דְּמִתַתָּא אִתְבְּרַךְ, מֵהַהוּא פְּרִישׂוּ דְּיָדִין לְעֵילָּא, כְּדֵין אִתְבָּרְכָא מֵעֵילָּא, וְאִתְיְקַר מִכָּל סִטְרִין.</p>\n<p>וְאִלֵּין עֲשָׂרָה מְמָנָן, זְמִינִין לְנַטְלָא מֵאִינּוּן בִּרְכָּאן דִּלְעֵילָּא, וּלְאַרָקָא לְתַתָּא, וּלְבָרְכָא לְהַהוּא דִּמְבָרֵךְ לֵיהּ, דִּכְתִּיב, (במדבר ו׳:כ״ז) וַאֲנִי אֲבָרַכֵם.</p>\n<p>בְּגִין כָּךְ, יִסְתַּמַּר בַּר נָשׁ, בְּשַׁעֲתָא דְּיָרִים יְדוֹי לְעֵילָּא, לְמֶהוֵי בִּצְלּוֹ, אוֹ בְּבִרְכָּאן אוֹ בְּבָעוּתָא, וְלָא יָרִים יְדוֹי לְמַגָּנָא, בְּגִין דְּאִלֵּין עֲשָׂרָה אִינּוּן זְמִינִין, וּמִתְעָרִין. לְגַבֵּי הַהוּא פְּרִישׂוּ דְּיָדִין, וְאִי הוּא לְמַגָּנָא, אִינּוּן עֲשָׂרָה לַטְיָין לֵיהּ, בְּמָאתָן וְאַרְבְּעִין וּתְמַנְיָא לְוָוטִין. וְהַאי אִיהוּ דִּכְתִּיב בֵּיהּ, (תהילים ק״ט:י״ז) וַיֶּאֱהַב קְלָלָה וַתְּבוֹאֵהוּ.</p>\n<p>וּכְדֵין, רוּחַ מִסְאֲבָא שַׁרְיָא עַל אִינּוּן יְדִין, דְּאִיהוּ אָרְחֵיהּ לְמִשְׁרֵי עַל אֲתָר רֵיקָנַיָּא, וּבִרְכָּתָא לָא שַׁרְיָא בַּאֲתָר רֵיקָנַיָּא. וְעַל דָּא (נ\"א דמברך ליה ואי אינון מתערין לגבי ההוא פרישו דידין ואיהו למגנא אינון לטיין ליה במאתן וארבעין ותמנייא לווטין וכדין רוח מסאבא שרייא על אינון ידין דאיהו ארחיה למשרזי על אתר ריקנייא בגין כך יסתמר בר נש בשעתא דארים ידוי לעילא למהוי בצלו או בברכאן ובצלותא ולא ירים ידוי למגנא ועל דא) כְּתִיב, (בראשית י״ד:כ״ב) הֲרִימוֹתִי יָדִי אֶל ה' אֵל עֶלְיוֹן, דְּמִתַּרְגְּמִינָן בְּצַלּוּ.</p>\n<p>וּבְהַאי פְּרִישׂוּ דְּיָדִין, אִית רָזִין עִלָּאִין, בְּשַׁעֲתָא דְּאִתְפְּרִישׁוּ, וְאִזְדְּקָפוּ לְעֵילָּא, אוֹקִיר בַּר נָשׁ לְקוּדְשָׁא בְּרִיךְ הוּא, בְּכַמָּה רָזִין עִלָּאִין. אַחְזֵי לְיַחֲדָא רָזָא דְּעֶשֶׂר אֲמִירָן, בְּגִין לְיַחֲדָא כֹּלָּא, וּלְאִתְבָּרְכָא שְׁמָא קַדִּישָׁא כַּדְקָא חֲזִי, (ר\"ח א' ב') וְאַחְזֵי לְיַחֲדָא רָזָא דִּרְתִּיכִין פְּנִימָאִין, וּרְתִיכִין דִּלְבַר, בְּגִין דְּיִתְבָּרֵךְ שְׁמָא קַדִּישָׁא בְּכָל סִטְרִין, וְיִתְיַחֵד כֹּלָּא כַּחֲדָא, עֵילָּא וְתַתָּא.</p>\n<p>פָּתַח וְאָמַר, (שמות כ״ג:ט״ו) וְלֹא יֵרָאוּ פָּנַי רֵיקָם, דָּא אִיהוּ רָזָא דְּזְקִיפוּ דְּאֶצְבְּעָן, כַּד זָקִיף לוֹן בַּר נָשׁ לְעֵילָּא, דְּבָעֵי דְּלָא לְאִזְדַּקְּפָא בְּרֵיקַנְיָּא, אֶלָּא בְּצַלּוּ וּבְבָעוּתִין וּבְבִרְכָּאן. (או בחד מנייהו) וְעַל דָּא וְלֹא יֵרָאוּ פָּנַי רֵיקָם. וְלֹא יֵרָאוּ לְפָנַי לָא כְּתִיב, אֶלָּא פָּנַי, רָזָא דְּזְקִיפוּ דְּאֶצְבְּעָן, דְּלָא אִצְטְרִיכוּ לְזַקְפָא לְמַגָּנָא, כְּמָה דְּאִתְּמַר.</p>\n<p>עֲשָׂרָה שַׁלִּיטִין דְּקַאמְרָן, אִינּוּן עֶשֶׂר אֲמִירָן לְתַתָּא, בְּרָזָא (נ\"א עשרה שלטנין ממנן דקאמרן, אינון ממנן לתתא ברזא) דְּאַתְוָון רְשִׁימִין כְּגַוְונָא דִּלְעֵילָּא, וְאִלֵּין קַיְּימִין בְּקַדְמִיתָא עַל הַהוּא זְקִיפָן דְּאֶצְבְּעָאן. <Nonei></i>וּבְהָא כָּל סִטְרָא דִּקְדוּשָּׁה אִתְאֲחָד לְעֵילָּא לְאָרָמָא, כְּדֵין כָּל סִטְרִין אַחֲרָנִין אִתְכַּפְיָין כֻּלְּהוּ, וְאוֹדָן לְמַלְכָּא קַדִּישָׁא.</p>\n<p>תָּא חֲזֵי, בְּרָזָא דִּקְדוּשָּׁה (נ\"א דשמא קדישא) אִיהוּ מֶלֶךְ, וְכֹהֵן וּמְשַׁמֵּשׁ תְּחוֹתֵיהּ, (ברזא דקדושה) בֵּין לְעֵילָּא בֵּין לְתַתָּא. אִית מֶלֶךְ לְעֵילָּא, דְּאִיהוּ רָזָא דְּקֹדֶשׁ הַקֳּדָשִׁים, וְאִיהוּ מֶלֶךְ עִלָּאָה, וּתְחוֹתֵיהּ אִית כֹּהֵן רָזָא דְּאוֹר קַדְמָאָה, דְּקָא מְשַׁמֵּשׁ קָמֵיהּ, וְדָא אִיהוּ כֹּהֵן דְּאִקְרֵי גָּדוֹל, סִטְרָא דִּימִינָא.</p>\n<p>אִית מֶלֶךְ לְתַתָּא, דְּאִיהוּ כְּגַוְונָא דְּהַהוּא מֶלֶךְ עִלָּאָה, וְאִיהוּ מֶלֶךְ עַל כֹּלָּא דִּלְתַתָּא. וּתְחוֹתֵיהּ אִית כֹּהֵן דִּמְשַׁמֵּשׁ לֵיהּ, רָזָא דְּמִיכָאֵל כַּהֲנָא רַבָּא, דְּאִיהוּ לִימִינָא. (ודאי בסטרא דקדשה אית מלך וכהן) וְדָא אִיהוּ רָזָא דִּמְהֵימָנוּתָא שְׁלֵימָתָא, סִטְרָא דִּקְדוּשָּׁה.</p>\n<p>בְּסִטְרָא אַחֲרָא, דְּלָאו אִיהוּ סִטְרָא דִּקְדוּשָׁה, אִית רָזָא דְּאִיהוּ מֶלֶךְ, וְהָא אוֹקִימְנָא דְּאִקְרֵי (קהלת ד׳:י״ג) מֶלֶךְ זָקֵן וּכְסִיל, וּתְחוֹתֵיהּ אִית כֹּהֵן אוֹן, וְדָא הוּא רָזָא דִּכְתִּיב, (הושע י״ב:ט׳) וַיֹּאמֶר אֶפְרַיִם אַךְ עָשַׁרְתִּי מָצָאתִי אוֹן לִי, בְּגִין דְּחֵילָא דָּא, שַׁלְטָא עַל הַהוּא עוֹבָדָא דַּעֲבַד יָרָבְעָם. וְאִלְמָלֵא דְּאַשְׁכַּח חֵילָא דָּא, לָא יָכִיל לְאַצְלָחָא בְּהַהוּא עוֹבָדָא.</p>\n<p>רָזָא דְּמִלָּה, בְּשַׁעֲתָא דְּהַאי מֶלֶךְ וְהַאי כֹּהֵן אִתְכַּפְיָין, וְאִתְּבָּרוּ, כְּדֵין כָּל סִטְרִין אַחֲרָנִין אִתְכַּפְיָין, וְאוֹדָן לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא שָׁלִיט בִּלְחוֹדוֹי עֵילָּא וְתַתָּא, כְּמָה דְאַתְּ אָמֵר, (ישעיהו ב׳:י״א) וְנִשְׂגַּב יְיָ' לְבַדּוֹ בַּיּוֹם הַהוּא.</p>\n<p>כְּגַוְונָא דָּא, וְרָזָא דָּא מַמָּשׁ, עָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא, דְּתָבַר מֶלֶךְ זָקֵן וּכְסִיל, וְדָא הוּא פַּרְעֹה, בְּשַׁעֲתָא דְּאָתָא מֹשֶׁה לְפַרְעֹה, וְאָמַר, (שמות ה׳:ג׳) אֱלהֵי הָעִבְרִים נִקְרָא עָלֵינוּ, פָּתַח וְאָמַר, לֹא יָדַעְתִּי אֶת יְיָ', וּבָעָא קוּדְשָׁא בְּרִיךְ הוּא דְּיִתְיָקַּר שְׁמֵיהּ בְּאַרְעָא, כְּמָה דְּאִיהוּ יַקִּירָא לְעֵילָּא. כֵּיוָן דְּאַלְקֵי לֵיהּ וּלְעַמֵּיהּ, אָתָא וְאוֹדֵי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וּלְבָתַר אִתְּבַר וְאִתְכַּפְיָיא הַהוּא כֹּהֵן אוֹן, יִתְרוֹ, דִּמְשַׁמֵּשׁ תְּחוֹתֵיהּ, עַד דְּאָתָא וְאוֹדֵי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְאָמַר בָּרוּךְ יְיָ' אֲשֶׁר הִצִּיל אֶתְכֶם וְגוֹ', עַתָּה יָדַעְתִּי כִּי גָּדוֹל יְיָ' וְגוֹ', וְדָא הוּא כֹּהֵן אוֹן, סִטְרָא אַחֲרָא, דְּאִיהוּ סְטָר שְׂמָאלָא. וְדָא אִיהוּ רָזָא דְּאָמְרָה רָחֵל, כַּד חָמָאתּ דְּמִיתַת, כְּמָה דִּכְתִּיב, (בראשית לה) בֶּן אוֹנִי. וּבְגִין דָּא אוֹחֵי (נ\"א אודי) יַעֲקֹב, וְאָמַר בֶּן יָמִין, וְלָא בֶּן אוֹנִי, סְטָר יְמִינָא, וְלָא שְׂמָאלָא.</p>\n<p>וְכֵיוָן דְּהַהוּא מֶלֶךְ וְכֹהֵן אוֹדוּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְאִתְּבָּרוּ קָמֵיהּ, כְּדֵין אִסְתְּלַק קוּדְשָׁא בְּרִיךְ הוּא בִּיקָרֵיהּ עַל כֹּלָּא, עֵילָּא וְתַתָּא, וְעַד דְּאִסְתַּלָּק קוּדְשָׁא בְּרִיךְ הוּא בִּיקָרֵיהּ, כַּד אוֹדָן אִלֵּין קָמֵיהּ, לָא אִתְיְיהִיבַת אוֹרַיְיתָא. עַד לְבָתַר דְּאָתָא יִתְרוֹ, וְאוֹדֵי וְאָמַר, עַתָּה יָדַעְתִּי כִּי גָּדוֹל יְיָ' מִכָּל הָאֱלֹהִים. בָּרוּךְ יְיָ' אֲשֶׁר הִצִּיל אֶתְכֶם וְגוֹ'. כְּדֵין אִסְתַּלָּק קוּדְשָׁא בְּרִיךְ הוּא בִּיקָרֵיהּ, עֵילָּא וְתַתָּא, וּלְבָתַר יָהַב אוֹרַיְיתָא בִּשְׁלִימוּ, דְּשֻׁלְטָנוּ עַל כֹּלָּא.</p>\n<p>רִבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהילים ס״ז:ד׳) יוֹדוּךָ עַמִּים אֱלֹהִים יוֹדוּךָ עַמִּים כֻּלָּם, תָּא חֲזֵי, דָּוִד מַלְכָּא קָם וְשַׁבַּח וְאוֹדֵי לְמַלְכָּא קַדִּישָׁא. וְהוּא אִשְׁתַּדַּל בְּאוֹרַיְיתָא, בְּהַהִיא שַׁעֲתָא כַּד רוּחַ צָפוֹן אִתְּעַר, וַהֲוָה בָּטַשׁ בְּאִינּוּן נִימִין דְּכִנּוֹרָא, וְכִנּוֹרָא הֲוָה מְנַגֵּן וְאָמַר שִׁירָה וְכוּ', וּמַה שִׁירָה הֲוָה קָאָמַר.</p>\n<p>תָּא חֲזִי, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְעַר לְגַבֵּי כָּל אִינּוּן רְתִיכִין, לְמֵיהָב לוֹן טַרְפָּא, כְּמָה דְּאוֹקִימְנָא דִּכְתִּיב, (משלי ל״א:ט״ו) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ. כְּדֵין, כֻּלְּהוּ בְּחֵדוּ, פַּתְחֵי וְאַמְרֵי, (תהילים ס״ז:ב׳) אֱלהִים יְחָנֵּנוּ וִיבָרְכֵנוּ יָאֵר פָּנָיו אִתָּנוּ סֶלָה. כַּד רוּחַ צָפוֹן אִתְּעַר וְנָחִית לְעָלְמָא, נָשִׁיב וְאָמַר, לָדַעַת בָּאָרֶץ דַּרְכֶּךָ בְּכָל גּוֹיִם יְשׁוּעָתֶךָ. כִּנּוֹר בְּשַׁעֲתָא דְּאִיהוּ מְנַגְּנָא בֵּיהּ בְּהַהוּא רוּחָא, פָּתַח וְאָמַר יוֹדוּךָ עַמִּים כֻּלָּם (חסר) דָּוִד כַּד הֲוָה קָם, וְאִתְּעַר עָלֵיהּ רוּחַ קֻדְשָׁא, פָּתַח וְאָמַר, אֶרֶץ נָתְנָה יְבוּלָהּ יְבָרְכֵנוּ אֱלהִים אֱלהֵינוּ יְבָרְכֵנוּ אֱלֹהִים וַיִּירְאוּ אוֹתוֹ כָּל אַפְסֵי אָרֶץ. בְּגִין לְאַמְשָׁכָא טִיבוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, מֵעֵילָּא לְתַתָּא. לְבָתַר אָתָא דָּוִד בְּרוּחַ קֻדְשָׁא, וְסִדֵּר לוֹן כַּחֲדָא, אִסְתָּכַּל בְּכֹלָּא הַאי קְרָא דְּכִנּוֹרָא, (בגין) דִּשְׁלִימוּ דִּיְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא עֵילָּא וְתַתָּא.</p>\n<p>בְּשַׁעֲתָא דִּשְׁאַר עַמִּין אִתְכַּפְיָין, אַתְיָין וְאוֹדָאן לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, כֵּיוָן דְּאִינּוּן אִתְכַּפְיָין, וְאוֹדָן לֵיהּ, כְּדֵין אִשְׁתְּלִים יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא עֵילָּא וְתַתָּא. בְּשַׁעֲתָא דְּאָתָא מֹשֶׁה <Nonei></i>לְפַרְעֹה וְאָמַר לֵיהּ יְיָ' אֱלהֵי הָעִבְרִים נִקְרָא עָלֵינוּ וְגוֹ', פָּתַח אִיהוּ וְאָמַר לא יָדַעְתִּי אֶת יְיָ'.</p>\n<p>וּבָעָא קוּדְשָׁא בְּרִיךְ הוּא, דְּיִתְיָיקַּר שְׁמֵיהּ בְּאַרְעָא, כְּמָה דְּאִיהוּ יַקִּירָא לְעֵילָּא, כֵּיוָן דְּאַלְקֵי לֵיהּ וּלְעַמֵּיהּ, אָתָא וְאוֹדֵי לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (שמות ט) יְיָ' הַצַּדִיק. אִיהוּ דְּהֲוָה מַלְכָּא קְרוֹפִינוֹס דְּכָל עָלְמָא, כֵּיוָן דְּאִיהוּ אוֹדֵי, כָּל שְׁאַר מַלְכִין אוֹדוּן, דִּכְתִּיב, (שמות ט״ו:ט״ו) אָז נִבְהֲלוּ אַלּוּפֵי אֱדוֹם.</p>\n<p>אָתָא יִתְרוֹ, כּוֹמָרָא עִלָּאָה וְרַבְרְבָא, רַב מְמָנָא (דכל ממנא) דְּכָל טַעֲוָון אַחֲרָנִין, וְאוֹדֵי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְאָמַר עַתָּה יָדַעְתִּי כִּי גָּדוֹל יְיָ' מִכָּל הָאֱלֹהִים, כְּדֵין אִסְתַּלָּק וְאִתְיְיקָר קוּדְשָׁא בְּרִיךְ הוּא בִּיקָרֵיהּ עֵילָּא וְתַתָּא, וּלְבָתַר יָהַב אוֹרַיְיתָא בִּשְׁלִימוּ, דְּשֻׁלְטָנוּ עַל כֹּלָּא.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן לְרַ' אֶלְעָזָר בְּרֵיהּ, עַל דָּא כְּתִיב, (תהילים ס״ז:ד׳) יוֹדוּךָ עַמִּים אֱלֹהִים יוֹדוּךָ עַמִּים כּוּלָּם. אָתָא ר' אֶלְעָזָר וְנָשִׁיק יְדוֹי. בָּכָה ר' אַבָּא וְאָמַר, (תהילים ק״ג:י״ג) כְּרַחֵם אָב עַל בָּנִים. מַאן יְרַחֵם עַל ר' אֶלְעָזָר, וּלְאַשְׁלְמָא מִלּוֹי, בַּר רְחִימוּ דְּמֹר, זַכָּאָה חוּלָקָנָא, דְּזָכֵינָא לְמִשְׁמַע מִלִּין אִלֵּין קָמֵיהּ, דְּלָא נִכְסוֹף בְּהוּ לְעָלְמָא דְּאָתֵי.</p>\n<p>אָמַר רַבִּי אַבָּא, הָא כֹּהֵן אוֹן לָא כְּתִיב בְּיִתְרוֹ, כֹּהֵן מִדְיָן כְּתִיב. אֲמַר לֵיהּ, כֹּלָּא אִיהוּ חַד. בְּקַדְמִיתָא חָמוּי דְּיוֹסֵף, כֹּהֵן אוֹן אִקְרֵי. וּלְבָתַר חָמוּי דְּמֹשֶׁה, כֹּהֵן מִדְיָן. וְכֹלָּא רָזָא חֲדָא, דְּהָא אִלֵּין תְּרֵין מֹשֶׁה וְיוֹסֵף. בְּדַרְגָּא דְרָזָא חֲדָא קַיְימִין, בְּרָזָא דְּאָת וָ\"ו, תְּרֵין וָוִין כַּחֲדָא. וּמַה דְּאִתְּמַר כֹּהֵן מִדְיָן, רָזָא דָּא אֵשֶׁת מִדְיָנִים. (משה ויוסף ברזא חדא קיימי, רזא דא ו\"ו תרין כחדא)</p>\n<p>אָרִים יְדוֹי עַל רֵישֵׁיהּ ר' אַבָּא וּבָכָה, אָמַר, נְהִירוּ דְּאוֹרַיְיתָא סַלְּקָא הַשְׁתָּא עַד רוּם רְקִיעָא דְּכֻרְסְיָיא עִלָּאָה, לְבָתַר דְּיִסְתַּלַּק מֹר מֵעָלְמָא, מַאן יַנְהִיר נְהִירוּ דְּאוֹרַיְיתָא. וַוי לְעָלְמָא דְּיִשְׁתְּאַר יָתוֹם מִינָךְ. אֲבָל מִלִּין דְּמֹר יִתְנְהִירוּ בְּעָלְמָא עַד דְּיֵיתֵי מַלְכָּא מְשִׁיחָא וּכְדֵין כְּתִיב, (ישעיהו י״א:ט׳) וּמָלְאָה הָאָרֶץ דֵּעָה אֶת יְיָ' וְגוֹ'.</p>\n<p>וַיִּשְׁמַע יִתְרוֹ כֹּהֵן וְגוֹ, רַבִּי חִיָּיא אָמַר, הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, בְּקַדְמִיתָא כְּתִיב, אֵת כָּל אֲשֶׁר עָשָׂה אֱלהִים לְמֹשֶׁה, וּלְבָתַר כְּתִיב כִּי הוֹצִיא יְיָ'. אֶלָּא רָזָא דָּא אֵת כָּל אֲשֶׁר עָשָׂה אֱלֹהִים, דָּא שְׁמָא דְּאָגִין עַל מֹשֶׁה וְעַל יִשְׂרָאֵל, וְלָא אִתְעָדֵי מִנַּיְיהוּ בְּגָלוּתָא. וּלְבָתַר, שְׁמָא עִלָּאָה אַפִּיק לוֹן מִמִּצְרַיִם. דְּהָא שְׁמָא קַדִּישָׁא דְּאַפִּיק לוֹן, בְּרָזָא דְּיוֹבְלָא הֲוָה.</p>\n<p>דָּבָר אַחֵר אֵת כָּל אֲשֶׁר עָשָׂה אֱלֹהִים לְמֹשֶׁה, כַּד אִתְרְמֵי לְנָהֲרָא, וְכַד שֵׁזִיב לֵיהּ מֵחַרְבָּא דְּפַרְעֹה, וּלְיִשְׂרָאֵל עַמּוֹ, דִּכְתִּיב, (שמות ב׳:כ״ד) וַיִּשְׁמַע אֱלֹהִים אֶת נַאֲקָתָם. וּכְתִיב (שמות א׳:י״ב) וְכַאֲשֶׁר יְעַנּוּ אוֹתוֹ כֵּן יִרְבֶּה וְכֵן יִפְרוֹץ.</p>\n<p>וַיִּשְׁמַע יִתְרוֹ כֹּהֵן מִדְיָן. רַבִּי יוֹסִי פָּתַח, (תהילים קי״א:ט׳) פְּדוּת שָׁלַח לְעַמּוֹ צִוָּה לְעוֹלָם בְּרִיתוֹ קָדוֹשׁ וְנוֹרָא שְׁמוֹ. מַאי שְׁנָא, בְּכָל שְׁאַר קְרָאֵי, דִּבְכֻלְּהוּ, תְּרֵין תֵּיבִין מֵאַלְפָא בֵּיתָא, וּבְהַאי קְרָא, וּבִקְרָא דַּאֲבַתְרֵיהּ, תְּלַת תְּלַת. אֶלָּא, בְּגִין לְאַשְׁלְמָא שִׁית סִטְרִין, בְּהַאי אַלְפָא בֵּיתָא, הַאי לָקֳבֵל תְּלַת פּוּרְקָנִין דְּיִשְׂרָאֵל, בַּר פּוּרְקָנָא קַדְמָאָה. קְרָא אַחֲרָא, לָקֳבֵל תּוֹרָה נְבִיאִים וּכְתוּבִים. וְכֹלָּא תַּלְיָא בְּהַאי חָכְמָה.</p>\n<p>פְּדוּת שָׁלַח לְעַמּוֹ, כַּד פָּרִיק קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, מִגָּלוּתָא דְּמִצְרַיִם, וְעָבִיד לוֹן נִסִּין וּגְבוּרָן. צִוָּה לְעוֹלָם בְּרִיתוֹ, כַּד אָתָא יִתְרוֹ, וְקָבִּיל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְקָרִיב לֵיהּ לְפוּלְחָנֵיהּ. וּמִתַּמָּן, אִתְקְרִיבוּ כָּל אִינּוּן גִּיּוֹרִין, תְּחוֹת גַּדְפּוֹי דִּשְׁכִינְתָּא, מִתַּמָּן וּלְהָלְאָה, קָדוֹשׁ וְנוֹרָא שְׁמוֹ. דְּהָא כְּדֵין אִתְקַדָּשׁ שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּהָא (מסטרא אחרא) יִתְקַדָּשׁ שְׁמָא קַדִּישָׁא, כַּד אִתְּבַר, וְאִתְכַּפְיָא סִטְרָא אַחֲרָא, כְּמָה דְּהֲוָה בְּיִתְרוֹ.</p>\n<p>וַיִּשְׁמַע יִתְרוֹ וְגוֹ', וְכִי יִתְרוֹ שָׁמַע, וְכָל עָלְמָא לא שַׁמְעוּ, וְהָא כְּתִיב, (שמות ט״ו:י״ד) שָׁמְעוּ עַמִּים יִרְגָּזוּן. אֶלָּא, כָּל עָלְמָא שָׁמְעוּ, וְלָא אִתְּבָּרוּ, וְאִיהוּ שָׁמַע וְאִתְּבַּר, <Nonei></i>וְאִתְכַּפְיָא מִקַּמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִתְקְרַב לְדַחַלְתֵּיהּ.</p>\n<p>רַבִּי אַבָּא אָמַר, בְּכַמָּה אֲתָר תָּנֵינָן, דְּקוּדְשָׁא בְּרִיךְ הוּא, כָּל מַה דְּעָבַד לְעֵילָּא וְתַתָּא כֹּלָּא אִיהוּ קְשׁוֹט, וְעוֹבָדָא דִּקְשׁוֹט. וְלֵית לָךְ מִלָּה בְּעָלְמָא דְּבָעֵי בַּר נָשׁ לְדַחְיָא לֵיהּ מִנֵּיהּ, וּלְאַנְהָגָא בֵּיהּ קְלָנָא, דְּהָא כֻּלְּהוּ עוֹבָדָא דִּקְשׁוֹט אִינּוּן, וְכֹלָּא אִצְטְרִיךְ בְּעָלְמָא.</p>\n<p>דְּהָא זִמְנָא חֲדָא, הֲוָה ר' אֶלְעָזָר אָזִיל בְּאָרְחָא, וַהֲוָה אָזִיל עִמֵּיהּ ר' חִזְקִיָּה, חָמוּ חַד חִוְיָא, קָם ר' חִזְקִיָּה לְמִקְטְלֵיהּ. אֲמַר לֵיהּ ר' אֶלְעָזָר, שָׁבִיק לֵיהּ לָא תְּקַטְלִינֵיהּ. אֲמַר לֵיהּ, וְהָא מִלָּה בִּישָׁא אִיהוּ, דְּקָטִיל בְּנִי נָשָׁא. אֲמַר לֵיהּ לְרַ' חִזְקִיָּה, וְהָא כְּתִיב (קהלת י׳:י״א) אִם יִשּׁוֹךְ הַנָּחָשׁ בְּלֹא לָחַשׁ. לָא נָשִׁיךְ חִוְיָא לְבַר נָשׁ, עַד דְּלָחֲשִׁין לֵיהּ מִלְּעֵילָּא, וְאַמְרֵי לֵיהּ זִיל קָטִיל לֵיהּ לִפְלָנַיָּא.</p>\n<p>וּלְזִמְנִין כְּמָה דְּעָבִיד הַאי, הָכִי נָמֵי שֵׁזִיב לְבַר נָשׁ, מִמִּלִּין אַחֲרָנִין, וְעַל יְדוֹי אַרְחִישׁ קוּדְשָׁא בְּרִיךְ הוּא נִיסָא לִבְנֵי נָשָׁא, וְכֹלָּא בִּידָא דְּקוּדְשָׁא בְּרִיךְ הוּא תַּלְיָא, וְכֹלָּא אִיהוּ עוֹבָדֵי יְדוֹי, וְאִצְטְרִיךְ עָלְמָא לְהוּ, וְאִי לָאו דְּאִיצְטְרִיךָ לוֹן עָלְמָא, לָא עָבֵד לוֹן קוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא לָא בָּעֵי בַּר נָשׁ לְאַנְהָגָא בְּהוּ קְלָנָא בְּמִלֵּי דְּעָלְמָא. בְּמִלּוֹי וּבְעוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>פָּתַח וְאָמַר, (בראשית א׳:ל״א) וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנִּה טוֹב מְאֹד. וַיַּרְא אֱלהִים: דָּא אֱלהִים חַיִּים. וַיַּרְא: דְּאִסְתָּכַּל לְאַנְהָרָא לוֹן, וּלְאַשְׁגָּחָא לוֹן. אֶת כָּל אֲשֶׁר עָשָׂה כֹּלָּא בִּכְלָלָא חֲדָא, עֵילָּא וְתַתָּא. וְהִנֵּה טוֹב: דָּא סִטְרָא דִּימִינָא. מְאֹד: דָּא סִטְרָא דִּשְׂמָאלָא, וְהָא אוּקְמוּהָ, טוֹב: דָּא מַלְאַךְ חַיִּים מְאֹד: דָּא מַלְאַךְ הַמָּוֶת. וְכֹלָּא רָזָא חֲדָא. רָזָא הוּא, לְאִינוּן דְּמִסְתַּכְלֵי בְּרָזָא דְּחָכְמְתָא.</p>\n<p>וַיַּרְא אֱלהִים אֶת כָּל אֲשֶׁר עָשָׂה. בְּכָל עוֹבָדָא דִּבְרֵאשִׁית, כְּתִיב, וַיַּרְא אֱלהִים כִּי טוֹב, וְהָכָא וַיַּרְא אֱלהִים אֶת כָּל אֲשֶׁר עָשָׂה. אֱלֹהִים לְתַתָּא, שָׁלִיט עַל תַּתָּאֵי. אֱלהִים לְעֵילָּא, שָׁלִיט עַל עִלָּאֵי. דָּא אִיהוּ רָזָא דֶּאֱלהִים חַיִּים, (נ\"א דבר אחר כלא איהו אלהים חיים) דְּאַנְהִיר וְאַדְלִיק כָּל אִינּוּן בּוּצִינִין עִלָּאִין וְתַתָּאִין, וּמִתַּמָּן נָפְקִין כָּל אִינּוּן נְהוֹרִין לְאַנְהָרָא.</p>\n<p><Noneb>תוספתא</b> בִּטְמִירוּ דִּטְמִירִין, אִתְרְשִׁים רְשִׁימוּ חַד, דְּלָא אִתְחָזֵי וְלָא אִתְגַּלְיָא. הַהוּא רְשִׁימוּ, רָשִׁים וְלָא רָשִׁים. מָארֵי דְּסָכְלְתָנוּ, וּפִקְחִין דְּעַיְינִין, לָא יַכְלִין לְמֵיקָם בֵּיהּ. אִיהוּ קִיּוּמָא דְּכֹלָּא. הַהוּא רְשִׁימוּ אִיהוּ זְעֵיר, דְּלָא אִתְחַזְיָא וְלָא אִתְגַּלְיָא. קַיְּימָא בִּרְעוּתָא, לְקַיְּימָא כֹּלָּא. לְנַטְלָא מַה דְּנַטְלָא, מִמַּה דְּלֵית בֵּיהּ רְשִׁימוּ, וְלָא רְעוּתָא, דְּלָא אִתְחָזֵי.</p>\n<p>הַהוּא רְשִׁימוּ בָּעָא לְאַחֲפָיָא גַּרְמֵיהּ, וְעָבִיד לֵיהּ לְגַרְמֵיהּ, לְאִתְטַמְּרָא בֵּיהּ, חַד הֵיכָלָא. הַהוּא הֵיכָלָא אַפִּיק לֵיהּ מִגַרְמֵיהּ, וּמָתַח לֵיהּ בִּמְתִּיחוּ רַב וְסַגִּיא לְכָל סִטְרִין, אוֹקִיר לֵיהּ בִּלְבוּשֵׁי יְקָר, פָּתַח לֵיהּ חַמְשִׁין תַּרְעִין.</p>\n<p>לְגוֹ בְּגוֹ, אִתְטָמַּר וְאִתְגְּנִיז הַהוּא רְשִׁימוּ. כֵּיוָן דְּאִתְגְּנִיז בֵּיהּ, וְעָאל בְּגַוֵּיהּ, אִתְמַלְיָא נְהוֹרָא. מֵהַהוּא נְהִירוּ, נַבְעִין נְהוֹרִין, וְנִצוֹצִין נָפְקִין מֵאִינּוּן תַּרְעִין, וְנָהֲרִין כֹּלָּא.</p>\n<p>הַהוּא הֵיכָלָא אִתְחַפְיָיא בְּשִׁית יְרִיעָן. אִינּוּן שִׁית יְרִיעָן, אִינּוּן חֲמֵשׁ. לְגוֹ בְּגוֹ אִינּוּן יְרִיעָן, קַיְּימָא חַד יְרִיעָא מְרֻקָּמָא, בְּהַהוּא יְרִיעָה אִתְחַפְיָיא הַהוּא הֵיכָלָא, מִנֵּיהּ אַשְׁגַּח וְחָמָא לְכֹלָּא.</p>\n<p>הַאי הֵיכָלָא אִיהוּ פְּקִיחָא דְּעַיְינִין, דְּלָא נָיִים. אִיהוּ אַשְׁגַּח תָּדִיר לְאַנְהָרָא לְתַתָּא, מִגּוֹ נְהִירוּ דְּהַהוּא רְשִׁימוּ. הַהוּא סָכְלְתָנוּ, חָכְמְתָא טְמִירְתָּא, רְעוּ דִּרְעוּתִין (ס\"א בעו דבעותין) הֲוֵי גָּנִיז וְטָמִיר, וְלָא אִתְגַּלְיָא, קַיְּימָא וְלָא קַיְּימָא. בְּרִיךְ הוּא מִטְּמִיר דִּטְמִירוּ, בְּרִיךְ הוּא לְעָלַם וּלְעָלְמֵי עַד אָמֵן. (ע\"כ תוספתא)</p>\n<p>תָּא חֲזִי, יִתְרוֹ הוּא דְּיָהַב עֵיטָא לְמֹשֶׁה, עַל תִּקּוּנָא דְּדִינִין, הָכִי אִצְטְרִיךְ. וְרָזָא דָּא דְּאוֹדֵי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְסִדֵּר קָמֵיהּ תִּקּוּנָא דְּדִינוֹי, לְאַחֲזָאָה מַה דִּכְתִּיב, (דברים א׳:י״ז) כִּי הַמִּשְׁפָּט לֵאלהִים הוּא, וְלָא לְסִטְרָא אַחֲרָא. וְדִינִין לְיִשְׂרָאֵל אִתְיְיהִיבוּ, וְלָא לְאַחֲרָא, דִּכְתִּיב, (תהילים קמ״ז:י״ט) חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל. וְתָּא חֲזֵי, לָא יַנְהִיג בַּר נָשׁ קְלָנָא בְּאַחֲרָא, וּמִלָּה דְּהֶדְיוֹטָא, מִלָּה <Nonei></i>אִיהוּ. דְּהָא בְּמֹשֶׁה כְּתִיב, וַיִּשְׁמַע מֹשֶׁה לְקוֹל חוֹתְנוֹ וְגוֹ'.</p>\n<p>וַיִּשְׁמַע יִתְרוֹ וְגוֹ'. פָּתַח וְאָמַר (תהילים י״ח:נ׳) עַל כֵּן אוֹדְךָ בַּגּוֹיִם יְיָ' וּלְשִׁמְךָ אֲזַמֵּרָה. דָּוִד מַלְכָּא אָמַר דָּא בְּרוּחַ קֻדְשָׁא, בְּשַׁעֲתָא דְּחָמָא, דְּהָא יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא, לָא אִסְתְּלִיק בִּסְלִיקוּ וְלָא אִתְיָיקְרָא בְּעָלְמָא, אֶלָּא מִסִּטְרָא דִּשְׁאַר עַמִין. וְאִי תֵּימָא, הָא קוּדְשָׁא בְּרִיךְ הוּא לָא אִתְיָיקַר בְּעָלְמָא, אֶלָּא בְּגִינֵיהוֹן דְּיִשְׂרָאֵל. הָכִי הוּא וַדַּאי, דְּהָא יִשְׂרָאֵל אִינּוּן הֲוֵי יְסוֹדָא דִּשְׁרָגָּא לְאַנְהָרָא, אֲבָל כַּד שְׁאַר עַמִּין אָתָאן וְאוֹדָן לֵיהּ, בְּשִׁעְבּוּדָא דִּיְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא, כְּדֵין אִתּוֹסָף יְסוֹדָא דִּשְׁרָגָּא, וְאִתְתָּקַּף עַל כָּל עוֹבָדוֹי. בְּחִבּוּרָא חֲדָא, וְשָׁלִיט קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי עֵילָּא וְתַתָּא.</p>\n<p>כְּגַוְונָא דָּא, כָּל עָלְמָא, דְּחִילוּ וְאֵימָתָא נָפַל עָלַיְיהוּ מִקָּמֵי קוּדְשָׁא בְּרִיךְ הוּא. וְכֵיוָן דְּאָתָא יִתְרוֹ, דְּאִיהוּ כּוֹמָרָא עִלָּאָה, דְּכָל טַעֲוָון אַחֲרָנִין, כְּדֵין אִתְתָּקַּף וְשָׁלִיט יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא עַל כֹּלָּא.</p>\n<p>בְּגִין, דְּכָל עָלְמָא, כַּד שָׁמְעוּ שֵׁמַע גְּבוּרְתֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, זָעוּ. וְכֻלְּהוּ הֲווֹ מִסְתַּכְּלָן בְּיִתְרוֹ, דְּאִיהוּ חַכִּים וְרַב מְמָנָא דְּכָל טַעֲוָון דְּעָלְמָא, כֵּיוָן דְּחָמוּ, דְּאִיהוּ אָתָא וּפָלַח לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְאָמַר עַתָּה יָדַעְתִּי כִּי גָּדוֹל יְיָ' מִכָּל הָאֱלֹהִים, כְּדֵין כֻּלְּהוּ אִתְרַחֲקוּ מִפּוּלְחָנֵיהוֹן, וְיָדְעוּ דְּלֵית בְּהוּ מַמָּשׁוּ. כְּדֵין אִתְיָיקַר יְקָרָא דִּשְׁמָא קַדִּישָׁא דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּכָל סִטְרִין. וְעַל דָּא אִתְרְשִׁים פַּרְשְׁתָּא דָּא בְּאוֹרַיְיתָא, וְשֵׁירוּתָא דְּפַרְשְׁתָּא הֲוָה בֵּיהּ בְּיִתְרוֹ.</p>\n<p>יִתְרוֹ חַד מֵחַכִּימִין דְּפַרְעֹה הֲוָה. תְּלַת חַכִּימִין הֲווֹ לֵיהּ לְפַרְעֹה, חַד יִתְרוֹ, וְחַד אִיּוֹב, וְחַד בִּלְעָם. חַד יִתְרוֹ: דְּלָא הֲוָה פּוּלְחָנָא וּמְמַנָּא וְשַׁמָּשָׁא וְכֹכָבָא דְּשָׁלִיט עַל שׁוּלְטָנֵיהּ, דְּלָא הֲוָה יָדַע פּוּלְחָנָא דְּאִתְחָזֵי לֵיהּ, וְהַהוּא שִׁמּוּשָׁא דִּילֵיהּ. בִּלְעָם, הֲוָה חַרְשָׁא בְּכָל מִינִי חֲרָשִׁין בֵּין בְּעוֹבָדָא בֵּין בְּמִלָּה.</p>\n<p>אִיּוֹב הֲוָה דָּחִיל בִּדְחִילוּ, וּבְהַהוּא דְּחִילוּ הֲוָה עִקָרָא דִּילֵיהּ, בְּגִין דְּמִלָּה דִּלְעֵילָּא, בֵּין דִּקְדוּשָׁה, בֵּין דְּסִטְרָא אַחֲרָא, לָא יָכִיל בַּר נָשׁ לְאַמְשָׁכָא רוּחָא דִּלְעֵילָּא לְתַתָּא וּלְמִקְרַב גַּבֵּיהּ, אֶלָּא בִּדְחִילוּ. וִיכַוֵּין לִבֵּיהּ וּרְעוּתֵיהּ בִּדְחִילוּ וּתְבִירוּ דְּלִבָּא, וּכְדֵין יַמְשִׁיךְ לְתַתָּא רוּחָא דִּלְעֵילָּא וּרְעוּתָא דְּאִצְטְרִיךְ.</p>\n<p>וְאִי לָא יְשַׁוֵּי לִבֵּיהּ וּרְעוּתֵיהּ בִּדְחִילוּ לְהַהוּא סִטְרָא, לָא יָכִיל לְאִתְדַּבְּקָא בֵּיהּ רְעוּתֵיהּ, בַּר לְהָנֵי טוֹפְסֵי דְּקִיקִין, וְלָא בְּכֻלְּהוּ, בְּגִין דְּאִית בְּהוּ שָׁלְטָנִין, דְּאִצְטְרִיךְ לְגַבַּיְיהוּ, רְעוּתָא דְּלִבָּא וּדְחִילוּ. כָּל שֶׁכֵּן אִינּוּן מִלִּין עִלָּאִין, דְּאִצְטְרִיךְ דְּחִילוּ וְאֵימָתָא וּרְעוּתָא יַתִּיר.</p>\n<p>יִתְרוֹ אִצְטְרִיךְ פּוּלְחָנֵיהּ דְּהַהוּא סִטְרָא תָּדִיר, בֵּין בְּזִמְנָא דְּאִצְטְרִיךְ לֵיהּ לְבַר נָשׁ, בֵּין בְּזִמְנָא דְּלָא אִצְטְרִיךְ לֵיהּ, בְּגִין דְּהַהוּא סִטְרָא יְהֵא דָּבִיק לְגַבֵּיהּ, בְּשַׁעֲתָא דְּאִצְטְרִיךְ לֵיהּ. בִּלְעָם אִתְדָּבַּק בְּאִינּוּן חֲרָשִׁין, כְּמָה דְּאִתְּמַר.</p>\n<p>אִיּוֹב בִּסְגִיאוּ דְּהַהוּא דְּחִילוּ דִּילֵיהּ אַהְדָּר בְּמִצְרַיִם לְמִדְחַל מִקָּמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, כַּד חָמָא אִינּוּן גְּבוּרָן וְנִסִּין, דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם. יִתְרוֹ, לָא אַהְדָּר בְּכָל דָּא, עַד דְּנָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, וְכָל אִינּוּן קִשְׁרִין וְטִפְסִין דְּקָשִׁירוּ מִצְרָאֵי, לָא הֲווֹ כְּלוּם, וְנַפְקוּ. וּלְבָתַר דְּטָבַע לוֹן בְּיַמָּא, כְּדֵין תָּב, וְאַהְדָּר לְפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>בִּלְעָם לָא תָּב, וְלָא אַהְדָּר, דְּטִנּוּפָא (נ\"א דטפסא) דְּסִטְרָא אַחֲרָא הֲוָה מִתְדָּבַק בֵּיהּ, וְעִם כָּל דָּא אִסְתַּכְּלוּתָא דְּמֵרָחִיק הֲוָה מִסְתַּכֵּל, בְּגוֹ הַהוּא טִנּוּפָא (ס\"א טפסא) וְאִתְדַּבְּקוּתָא דְּסִטְרָא אַחֲרָא. דְּהָא בְּסִטְרָא אַחֲרָא אִית נְהִירוּ דָּקִיק חַד, דְּנָהִיר סַחֲרָנֵיהּ, כְּמָה דְאַתְּ אָמֵר (יחזקאל א׳:ד׳) וְנֹגַהּ לוֹ סָבִיב. וְדָא אִסְתַּכְּלוּתָא זְעֵיר (ועל דא) הֲוָה מִסְתַּכֵּל מֵרָחִיק, וְלָא בְּכֻלְּהוּ מִלִּין.</p>\n<p>וְכַד הֲוָה מִסְתַּכֵּל מִלָּה זְעֵיר מֵהַהוּא נְהִירוּ, כְּבָתַר כּוֹתָלָא הֲוָה, אָמַר וְלָא יָדַע מַאי קָאָמַר. וַהֲוָה מִסְתַּכֵּל בְּהַהוּא נְהִירוּ בִּסְתִימוּ דְּעֵינָא, וְאִתְגַּלְגַּל עֵינָא, וְחָזֵי בַּר נָשׁ נְהוֹרָא סְתִימָא, וְלָא חֲזִי. וְרָזָא דָּא (במדבר כ״ד:ג׳) שְׁתוּם הָעָיִן, וְאוּקְמוּהָ שְׁתוּם: סְתוּם, וְכֹלָּא חַד.</p>\n<p>דְּהָא לֵית סִטְרָא אַחֲרָא, דְּלֵית בֵּיהּ <Nonei></i>נְהִירוּ דָּקִיק זְעֵיר מִסִּטְרָא דִּקְדוּשָּׁה, כְּגַוְונָא דְּרוֹב חֶלְמִין, דְּבִסְגִיאוּת תַּבְנָא, אִית חַד גַּרְעִינָא דְּחִטִּין. בַּר אִלֵּין טַפְסֵי דְּקִיקִין חֲצִיפִין, דְּכֻלְּהוּ מְסָאֲבֵי יַתִּיר. וּבְהוּ הֲוָה בִּלְעָם יוֹדֵעַ.</p>\n<p>זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה, דְּאִיהוּ לְעֵילָּא בְּכָל קְדוּשִׁין עִלָּאִין, וְאִסְתַּכַּל, בְּמָה דְּלָא אִתְיְיהִב רְשׁוּ לְבַר נָשׁ אַחֲרָא בְּעָלְמָא לְאִסְתַּכְּלָא. וּכְמָה דְּבִלְעָם הֲוָה חָמֵי נְהִירוּ זְעֵיר דָּקִיק כְּמִבָּתַר כּוֹתָלָא, מִגּוֹ הַהוּא סִטְרָא אַחֲרָא. אוּף הָכִי מֹשֶׁה, מִגּוֹ נְהִירוּ עִילָּאָה רַב וְסַגִּי, הֲוָה חָמֵי לְתַתָּא כְּמִבָּתַר כּוֹתָלָא, חַד חֲשׁוֹכָא דָּקִיק, דְּאִתְחֲזֵי לֵיהּ. וְלָאו בְּכָל זִמְנָא, כְּמָה דְּבִלְעָם לָא הֲוָה מִסְתַּכֵּל הַהוּא נְהִירוּ בְּכָל זִמְנָא.</p>\n<p>זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה נְבִיאָה מְהֵימָנָא, מַה כְּתִיב בֵּיהּ, (שמות ג׳:ב׳) וַיֵּרָא מַלְאַךְ יְיָ' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה. הַסְּנְה וַדַּאי הֲוָה בְּגוֹ הַהוּא קְדוּשָׁה וְאִתְדָבַּק בֵּיהּ. דְּכֹלָּא אִתְדָּבַּק דָּא בְּדָא, טָהוֹר וְטָמֵא, לֵית טָהוֹר אֶלָּא מִגּוֹ טָמֵא.</p>\n<p>וְרָזָא דָּא, (איוב י״ד:ד׳) מִי יִתֵּן טָהוֹר מִטָּמֵא. קְלִיפָה וּמוֹחָא דָּא בְּדָא סַלְּקָא. וְדָא קְלִיפָה לָא יִתְעֲדֵי וְלָא יִתְּבַּר, עַד זִמְנָא דִּיקוּמוּן מֵתִין מֵעַפְרָא, כְּדֵין יִתְּבַּר קְלִיפָה, וּנְהִירוּ יַנְהִיר בְּעָלְמָא בְּלֹא סְתִימוּ מִגּוֹ מוֹחָא. זַכָּאִין אִינּוּן צַדִּיקַיָּא בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.</p>"],[9520011635,"<p>וְאֵת שְׁנֵי בָּנֶיהָ, אָמַר רַבִּי חִיָּיא, וְכִי בָּנְיהָ וְלֹא בָּנָיו שֶׁל מֹשֶׁה. אֶלָּא, בְּגִין דְּאִיהִי אִשְׁתַּדְּלַת אֲבַתְרַיְיהוּ, בְּלָא בַּעְלָהּ, קָרָא לוֹן אוֹרַיְיתָא בָּנֶיהָ, וְלֹא בָּנָיו. אָמַר רִבִּי יוֹסִי, אַף עַל גַּב דִּבְנוֹי דְּמֹשֶׁה הֲווֹ. מִלָּה דִּקְשׁוֹט בָּנֶיהָ וַדַּאי. ר' אֶלְעָזָר אָמַר, הָא מֹשֶׁה הֲוָה מִזְדַּוֵּוג בַּאֲתָר אַחֲרָא קַדִּישָׁא עִלָּאָה, וְלָאו יְקָרָא דִּילֵיהּ לְמִקְרֵי לוֹן בָּנָיו. הַשְׁתָּא אַף עַל גַּב דִּבְנוֹי הֲווֹ, בְּגִין יְקָרָא דְּהַהוּא אֲתָר דְּאִזְדָּוַּוג בֵּיהּ, קָרָא לוֹן בָּנֶיהָ הָכָא, לְבָתַר קָרָא לוֹן בָּנָיו מַאי טַעְמָא, בְּגִין דְּהַהוּא שַׁעֲתָא דְּמָטוּ, הֲוָה מֹשֶׁה מְמַלֵּל בִּשְׁכִינְתָּא. לְבָתַר דְּאִתְפְּרַשׁ וְנָפַק לְגַבֵּי חָמוּי, כְּדֵין כְּתִיב (שמות י״ח:ה׳) וַיָּבֹא יִתְרוֹ חֹתֵן מֹשֶׁה וּבָנָיו וְאִשְׁתּוֹ וְגוֹ'.</p>\n<p>אָמַר ר' שִׁמְעוֹן, אֶלְעָזָר אֶלְעָזָר, אָנָא חֲמֵינָא בְּפַרְשְׁתָּא דָּא, דְּאַתְּ שָׁארֵי מִלָּה כְּדְקָא יֵאוֹת, וְסִיּוּמָא לָאו הָכִי. וַדַּאי בְּגִין יְקָרָא דִּשְׁכִינְתָּא, אִזְדַּוְּוגוּתָא עִלָּאָה דְּאִזְדָּוַּוג בֵּיהּ בְּמֹשֶׁה, כְּתִיב בָּנְיהָ. וְאִי תֵּימָא, וְהָא כְּתִיב וַיָּבֹא יִתְרוֹ חֹתֵן מֹשֶׁה וּבָנָיו וְאִשְׁתּוֹ אֶל מֹשֶׁה. כֹּלָּא אִיהוּ כְּלָלָא חֲדָא. וּבָנָיו, בָּנָיו דְּיִתְרוֹ, דְּהָא לְבָתַר דְּאָתָא מֹשֶׁה לְגַבֵּיהּ, הֲווֹ לֵיהּ בְּנִין.</p>\n<p>וְהָכִי הֲוָה בְּיַעֲקֹב, דְּכֵיוָן דְּאָתָא לְגַבֵּיהּ דְּלָבָן, וְשַׁוֵּי דִּיוֹרֵיהּ בֵּיהּ, הֲווֹ לֵיהּ בְּנִין. אוּף הָכָא מֹשֶׁה, כֵּיוָן דְּשַׁוֵּי דִּיוֹרֵיהּ בְּיִתְרוֹ, הֲווֹ לֵיהּ לְיִתְרוֹ בְּנִין וְכָל בֵּיתֵיהּ אַיְיתֵי עִמֵּיהּ, לְמֵיעַל לוֹן תְּחוֹת גַּדְפֵּי דִּשְׁכִינְתָּא, וְיִתְרוֹ אָמַר לְמֹשֶׁה, אֲנִי חוֹתֶנְךָ יִתְרוֹ בָּא אֵלֶיךָ וְאִשְׁתְּךָ וּשְׁנִי בָּנֶיהָ עִמָּהּ, וּשְׁנֵי בָּנֶיהָ כְּתִיב, וְלָא כְּתִיב וּשְׁנֵי בָּנֶיךָ. (ס\"א ויבא יתרו חתן משה ובניו) בְּנִין הֲווֹ לֵיהּ לְיִתְרוֹ, דִּכְתִּיב, (שופטים א׳:ט״ז) וּבְנִי קֵנִי חֹתֵן מֹשֶׁה עָלוּ מֵעִיר הַתְּמָרִים וּבְנוֹי שָׁבַק עִם מֹשֶׁה.</p>"],[9520011636,"<p>וַיָּבֹא יִתְרוֹ חֹתֵן מֹשֶׁה. פָּתַח וְאָמַר, (ישעיהו ב׳:ג׳) וְהָלְכוּ עַמִּים רָבִּים וְאָמְרוּ לְכוּ וְנַעֲלֶה אֶל הַר יְיָ' וְגוֹ'. הַאי קְרָא אוּקְמוּהָ בְּכַמָּה אֲתָר. אֲבָל זְמִינִין שְׁאַר עַמִּין לְמֵהַךְ וּלְכַתְּתָא רַגְלַיְיהוּ, לְמֵיעַל תְּחוֹת גַּדְפֵּי דִּשְׁכִינְתָּא. לְכוּ וְנַעֲלֶה, כָּל טַעֲוָון דְּעָלְמָא אִית לוֹן יְרִידָה, וְקוּדְשָׁא בְּרִיךְ הוּא מַאן דְּאִתְדַּבָּק בֵּיהּ, אִית בֵּיהּ עֲלִיָּה.</p>\n<p>אֶל הַר יְיָ', דָּא אַבְרָהָם, דִּכְתִּיב, (בראשית כ״ב:י״ד) אֲשֶׁר יֵאָמֵר הַיּוֹם בְּהַר יְיָ' יֵרָאֶה, דְּהָא אַבְרָהָם קָרֵי לֵיהּ הַר. מַה הַר הֶפְקֵירָא לְכָל מַאן דְּבָעֵי בְּעָלְמָא, אוּף אֲתָר דָּא קַדִּישָׁא, הֶפְקֵירָא לְקַבְּלָא לְכָל מַאן דְּבָעֵי בְּעָלְמָא. אֶל בֵּית, דָּא יַעֲקֹב, דְּקָרָא לְהַאי אֲתָר בַּיִת, דִּכְתִּיב, (בראשית כח) אֵין זֶה כִּי אִם בֵּית אֱלהִים.</p>\n<p>דָּבָר אַחֵר, הַר וּבַיִת, אַף עַל גַּב דְּכֹלָּא חַד דַּרְגָּא, <Nonei></i>סְלִיקוּ לְדָא מִן דָּא, הַר, לִשְׁאַר עַמִּין, כַּד אָתָאן לְאָעָלָא תְּחוֹת גַּדְפּוֹי. בַּיִת, לְיִשְׂרָאֵל, לְמֶהֱוֵי עִמְּהוֹן כְּאִתְּתָא בְּבַעְלָהּ. בְּדִיּוּרָא חַד בְּחֶדְוָוה, וּרְבִיעָא עָלַיְיהוּ כְּאִימָּא עַל בְּנִין.</p>\n<p>תָּא חֲזֵי מָה כְּתִיב הָכָא בְּיִתְרוֹ וַיָּבֹא יִתְרוֹ חֹתֵן מֹשֶׁה וּבַנָיו וְאִשְׁתּוֹ אֶל מֹשֶׁה וְגו' כֵּיוָן דִכְתִיב אֶל מֹשֶׁה אַמָּאי כְּתִיב אֶל הַמִּדְבָּר. אֶלָּא עִיקָרָא דְכֹלָא לְמָה דַהֲוָה אָתֵי אֶל הַמִּדְבָּר. וּמָאן אִיהוּ הַר הָאֱלהִים דְדָּא אִיהוּ אֲתַר לְגַיוּרֵי לְאִתְגַיְירָא וְעַל דָא כְּתִיב אֶל מֹשֶׁה אֶל הַמִּדְבָּר לְמֹשֶׁה לְגַיְירָא לוֹן וּלְאַעָלָא לוֹן תֵחוֹת גַּדְפֵי שְׁכִינְתָּא אֶל הַמִּדְבָּר הֲווּ אַתְיָין דְּאִיהוּ הַר הָאֱלֹהִים לְמֶעְבָּד נַפְשָׁיְיהוּ</p>\n<p>וּבְגִין כַּךְ קַיְּימָא הַהוּא אֲתָר, בְּרָזָא דְּהַר דְּכָל מַאן דְּאָתֵי זָכֵי בֵּיהּ. וְאִקְרֵי (ויקרא קס\"ח ע\"א) גֵּר צֶדֶק. וְהָא אוֹקִימְנָא, גֵּר, אַף עַל גַּב דְּאִתְדַּבָּק בַּאֲתָר דָּא עִלָּאָה קַדִּישָׁא, כֵּיוָן דְּשָׁבַק עִמֵּיהּ וַאֲבַהְתוֹי (ואתדבק בבריתו), גֵּר (צדק) אִקְרֵי, כְּמַאן דְּשַׁוֵּי מָדוֹרֵיהּ בַּאֲתָר דְּלָא יָדַע מִקַּדְמַת דְּנָא.</p>"],[9520011637,"<p>רַבִּי יִצְחָק וְרַבִּי יוֹסִי, הֲווֹ יַתְבֵי יוֹמָא חַד וְלָעָאן בְּאוֹרַיְיתָא בִּטְבֶרְיָא. אַעְבָּר רַבִּי שִׁמְעוֹן, אָמַר לוֹן בְּמַאי עַסְקִיתּוּ, אָמְרוּ לֵיהּ, בְּהַאי קְרָא דְּאוֹלִיפְנָא מִנֵּיהּ דְּמֹר, אָמַר לוֹן מַאי אִיהוּ. אָמְרוּ לֵיהּ, הַאי דִּכְתִּיב, (בראשית ה׳:א׳) זֶה סֵפֶר תוֹלְדוֹת אָדָם בְּיוֹם בְּרוֹא אֱלהִים אָדָם בִּדְמוּת אֱלהִים עָשָׂה אוֹתוֹ. וְהָא אִתְּמַר, דְּאַחְמֵי קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם הָרִאשׁוֹן, כָּל אִינּוּן דָּרִין דַּהֲווֹ זְמִינִין לְמֵיתֵי לְעָלְמָא, וְכָל אִינּוּן פַּרְנָסִין, וְכָל אִינּוּן חַכִּימִין, דַּהֲווֹ זְמִינִין בְּכָל דָּרָא וְדָרָא.</p>\n<p>וְרָזָא אוֹלִיפְנָא, זֶה סֵפֶר. אִית סֵפֶר וְאִית סֵפֶר. סֵפֶר לְעֵילָּא, סֵפֶר לְתַתָּא. סֵפֶר לְתַתָּא אִקְרֵי סֵפֶר הַזִּכָּרוֹן, סֵפֶר דְּהַהוּא זִכָּרוֹן, וְדָא חַד צַדִּיק, וְאִקְרֵי זֶה. וּבְגִין דְּלָא לְאַפְרְשָׁא לוֹן, דְּאִינּוּן תָּדִיר כַּחֲדָא בְּיִחוּדָא חֲדָא, כְּתִיב, זֶה סֵפֶר תְּרֵין דַּרְגִּין דְּאִינּוּן חַד, כְּלָלָא דְּכַר וְנוּקְבָּא.</p>\n<p>וְדָא אִיהוּ כְּלָלָא חֲדָא, דְּכָל אִינּוּן נִשְׁמָתִין וְרוּחִין דְּפַרְחִין בִּבְנֵי נָשָׁא, כְּלָלָא דְּכָל תוֹלְדוֹת, אִינּוּן בְּרָזָא תוֹלְדוֹת אָדָם וַדַּאי. דְּהָא מֵהַהוּא צַדִּיק דְּקָאָמַר, פַּרְחִין אִינּוּן נִשְׁמָתִין בְּתִיאוּבְתָּא חֲדָא, וְדָא אִיהוּ שַׁקְיוּ דְּגִנְתָּא דְּאַשְׁקֵי הַהוּא נָהָר דְּנָפִיק מֵעֵדֶן, דִּכְתִּיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וְדָא אִיהוּ רָזָא דְּאָדָם, דִּכְתִּיב תוֹלְדוֹת אָדָם.</p>\n<p>לְבָתַר בְּיוֹם בְּרוֹא אֱלהִים אָדָם, דָּא אָדָם דִּלְתַתָּא, דְּהָא תְּרֵין אָדָם כְּתִיבֵי בְּהַאי <Nonei></i>קְרָא, חַד רָזָא דִּלְעֵילָּא, וְחַד רָזָא דִּלְתַתָּא, אָדָם דְּאִיהוּ רָזָא דִּלְעֵילָּא, אִיהוּ בִּגְנִיזוּ, דְּגָנִיז קְרָא, בִּדְכַר וְנוּקְבָּא בְּרָזָא חֲדָא, דִּכְתִּיב זֶה סֵפֶר, דָּא כְּלָלָא דְּכַר וְנוּקְבָּא כַּחֲדָא. כֵּיוָן דְּעָבְדוּ תוֹלְדוֹת כַּחֲדָא, קָרָא לוֹן אָדָם, דִּכְתִּיב תוֹלְדוֹת אָדָם.</p>\n<p>לְבָתַר דְּאִתְגַּלְיָיא מִלְּתָא, מִגּוֹ סְתִימוּ עִלָּאָה קַדְמָאָה דִּקְרָא, בָּרָא אָדָם לְתַתָּא, דִּכְתִּיב בְּיוֹם בְּרוֹא אֱלהִים אָדָם בִּדְמוּת אֱלהִים עָשָׂה אוֹתוֹ. בִּדְמוּת (ס\"א דא איהו) דְּאָדָם אִיהוּ כְּהַאי חֵיזוּ דְּאִתְחָזֵי דִּיּוּקְנִין בֵּיהּ, וְאִינּוּן דִּיּוּקְנִין לָא קַיְימִין בְּהַהוּא חֵיזוּ בְּדִיּוּקְנָא בְּקִיּוּמָא, אֶלָּא מִתְעַבְּרָן מִינֵּיהּ, אוּף הָכִי בִּדְמוּת אֱלהִים.</p>\n<p>דָּבָר אַחֵר, בִּדְמוּת אֱלהִים, דִּיּוּקְנָא דְּשַׁיְיפִין דְּכָר וְנוּקְבָּא, בְּרָזָא (תהלים קלט) דְּאָחוֹר וָקֶדֶם. אָחוֹר: בְּרָזָא דְּשָׁמוֹר. וָקֶדֶם: בְּרָזָא דְּזָכוֹר. וּבְאִלֵּין תַּלְיָין כָּל פִּקּוּדֵי אוֹרַיְיתָא, שִׁית מְאָה וּתְלֵיסָר פִּקּוּדֵי אוֹרַיְיתָא, כְּלָלָא דְּכֹלָּא. וְתָנֵינָן, אָחוֹר לְעוֹבָדָא דִּבְרִאשִׁית, וָקֶדֶם לְעוֹבָדָא דְּמֶרְכָּבָה. וְכֹלָּא דָּא בְּדָא תַּלְיָא. בִּדְמוּת אֱלהִים, בְּהַהוּא דִּיּוּקְנָא מַמָּשׁ, וְהָא אוֹקִים לֵיהּ מֹר.</p>\n<p>תּוּ, זֶה סֵפֶר תוֹלְדוֹת אָדָם: לְדִּיּוּקְנִין, בְּרָזֵי דְּדִיּוּקְנִין דְּבַּר נָשׁ, לְאִשְׁתְּמוֹדְעָא בְּאִינּוּן תוֹלְדוֹת דְּבַּר נָשׁ, דִּיּוּקְנָא דְּרָזִין דְּבַּר נָשׁ, בְּשַׂעְרָא, בְּמִצְחָא, בְּעַיְינִין, בְּאַנְפִּין. בְּשִׁפְוָון, וּבְשִׂרְטוּטֵי יְדִין, וּבְאוּדְנִין. בְּאִלֵּין שֶׁבַע בְּנֵי נָשָׁא אִשְׁתְּמוֹדְעָן.</p>"],[9520011638,"<p>בְּשַׂעְרָא. הַאי מַאן דְּשַׂעֲרֵיהּ קָמִיט, וְסָלִיק לְעֵילָּא עַל רֵישֵׁיהּ, מָארֵיהּ דִּרְגִּיזוּ. לִבֵּיהּ קָמִיט כְּטוּפְסָא, לָאו כַּשְׁרָאן עוֹבָדוֹי. בְּשׁוּתָפוּ אִתְרְחַק מִנֵּיהּ.</p>\n<p>שַׂעֲרָא שְׁעִיעַ יַתִּיר, וְתָלֵי לְתַתָּא, טָב אִיהוּ לְשׁוּתָפוּ. וּרְוָוחָא אִשְׁתְּכַח בֵּיהּ. וְאִיהוּ בִּלְחוֹדוֹי לָאו הָכִי. מָארֵי דְּרָזִין אִיהוּ בְּאִינּוּן רָזִין עִלָּאִין. בְּרָזִין זְעִירִין לָא <Nonei></i>קַיְּימָא בְּהוּ. עוֹבָדוֹי כַּשְׁרָאן וְלָא כַּשְׁרָאָן.</p>\n<p>וְאִי תָּלֵי לְתַתָּא, וְלָא שְׁעִיעַ, לִבֵּיהּ לָא דָּחִיל, מָארֵיהּ דִּזְדוֹנָא אִיהוּ. כָּסִיף בְּעוֹבָדִין דְּכַשְׁרָן, וְיָאָן קָמֵיהּ, וְלָא עָבִיד. וְכַד אִיהוּ סִיב, אַהְדָּר לְמֶהֱוִי דָּחִיל וְיָאָן עוֹבָדוֹי. וְהָנֵי מִילֵּי, בְּמִילֵּי דְּעָלְמָא. אֲבָל בְּמִילֵּי דִּשְׁמַיָּא, יִצְלַח מַאן דְּיִקְרַב בֵּיהּ. לָא יִתְגַּלּוּן לֵיהּ רָזִין עִלָּאִין, אֲבָל רָזִין זְעִירִין טָב אִיהוּ לְנַטְרָא לוֹן, מִמִּלָּה זְעֵירָא עָבִיד רַב, וּמִלּוֹי אִשְׁתְּמָעוּ. וְרָזָא דָּא זַיִ\"ן, בְּאִינּוּן אַתְוָון דְּשִׁיעוּרָא דְּמֹר.</p>\n<p>שַׂעֲרָא אוּכָמָא יַתִּיר צָהִיב, אַצְלַח בְּכָל עוֹבָדוֹי בְּמִלֵּי דְּעָלְמָא, וּבַסְּחוֹרָא, וּבְדְדָמֵי לוֹן. וַתְרָן אִיהוּ דָּא אַצְלַח לְחוֹדוֹי. מַאן דְּמִתְחַבֵּר בַּהֲדֵיהּ, לָא אַצְלַח לְיוֹמִין סַגִּיאִין, אֶלָּא אַצְלַח מִיַּד, וְהַהִיא אַצְלָחוּתָא פַּרְחָא מִנֵּיהּ. וְרָזָא דָּא דְּאִיהוּ בִּכְלָלָא דְּאָת ז'.</p>\n<p>שַׂעֲרָא אוּכָמָא דְּלָא צָהִיב, לְזִמְנִין אַצְלַח, לְזִמְנִין לָא אַצְלַח. דָּא אִיהוּ לְשׁוּתָפוּ וּלְאִשְׁתַּדְּלָא בַּהֲדֵיהּ, טָב לִזְמַן קָרִיב, וְלָא לִזְמַן רָחִיק, דְּהָא לִזְמַן רָחִיק יַחֲשׁוֹב מַחֲשָׁבִין. וּבְגִין דְּלָא יִתְפָּרְשׁוּן מִנֵּיהּ, הֲוֵי טָב לִזְמַן קָרִיב. דָּא יִצְלַח בְּאוֹרַיְיתָא. אִי יִשְׁתָּדַּל אֲבַתְרָהָא. וְיִצְלְחוּן בֵּיהּ אַחֲרָנִין. לֵית לֵיהּ רָזָא, לִזְמַן רָחִיק. דָּחִיק לִבָּא אִיהוּ. יֶחֱמֵי בְּשַׂנְאוֹי. לָא יַכְלִין לֵיהּ שַׂנְאוֹי, וְאִיהוּ דָּחִיק לִבָּא, וְאִיהוּ בְּרָזָא דְּאָת י', דְּלָא קַיְּימָא בִּכְלָלָא דְּאָת ז', אֶלָּא י' בִּלְחוֹדוֹי, בְּרָזָא דְּאַתְוָון דְּקִיקִין.</p>\n<p>שַׂעֲרָא דְּמָרִיט, יִצְלַח בְּעוֹבָדוֹי, וְרַמָּאָה אִיהוּ כַּפִין בְּבֵיתֵיהּ. אִתְחָזֵי דָּחִיל חַטָּאָה לְבַר, לָאו הָכִי לְגוֹ. דָּא עַד לָא סִיב. אִי שַׂעֲרֵיהּ מָרִיט, לְבָתַר דְּסִיב, אִתְהַפַּךְ מִכַּמָּה דְּהֲוָה בְּקַדְמִיתָא, הֵן לְטָב הֵן לְבִישׁ.</p>\n<p>וְהָנֵי מִילֵּי שַׂעֲרָא דְּמָרִיט בֵּין עֵינוֹי, עַל גַּבֵּי מוֹחָא, בַּאֲתָר דְּאָנַח תְּפִלִין. וְאִי בַּאֲתָר אַחֲרָא דְּרִישָׁא, לָאו הָכִי. וְלָאו אִיהוּ <Nonei></i>רַמָּאָה, אֶלָּא מָארֵיהּ דְּלִישָׁנָא בִּישָׁא. בִּלְחִישׁוּ, בְּלָא אֲרָמוּת קָלָא. לְזִמְנִין דָּחִיל חַטָּאָה אִיהוּ, לְזִמְנִין לָא. וְדָא אִיהוּ בְּרָזָא דְּאָת ז', כַּד כָּלִיל אָת י'.</p>\n<p>עַד הָכָא, רָזִין דְּשַׂעֲרָא לְמָרֵי מִדִּין, דְּיַדְעֵי אָרְחֵי וְרָזֵי דְּאוֹרַיְיתָא, לְאִשְׁתְּמוֹדְעָא טְמִירוּ דִּבְנֵי נָשָׁא, דְּאִינּוּן בְּצֶלֶם אֱלהִים סָתוּם שְׁמָא, דְּאִתְפְּרַשׁ לְכַמָּה אָרְחִין.</p>"],[9520011639,"<p>בְּרָזָא דְּמִצְחָא, בְּאָת נ', דְּאִיהוּ שְׁלִימוּ דְּאָת זַיִ\"ן, לְזִמְנִין אִתְכְּלִילַת בְּרָזָא דְּאָת ז', וּלְזִמְנִין אִיהוּ בִּלְחוֹדָהָא. מִצְחָא דְּאִיהוּ דָּקִיק וְחַד, בְּלָא עִגּוּלָא דָּא הוּא בַּר נָשׁ דְּלָא מִתְיַישְׁבָא בְּדַעְתֵּיהּ, חָשִׁיב דְּאִיהוּ חַכִּים, וְלא יָדַע. אִתְבְּהִיל בְּרוּחֵיהּ. חֲיִּיךְ (ס\"א נשיך) בְּלִישָׁנֵיהּ כְּחִוְיָא.</p>\n<p>קְמִיטִין דְּמִצְחֵיהּ רַבְרְבָן, וְלָאו אִינּוּן בְּזִוּוּגָא. בְּשַׁעֲתָא דְּמַלִּיל אִתְעָבִידוּ אִינּוּן קְמִיטִין בְּמִצְחֵיהּ, וְלָאו בְּזִוּוּגָא. רְשִׁימִין אַחֲרָנִין דִּי בְּמִצְחֵיהּ כֻּלְּהוּ בְּזִוּוּגָא. דָּא, בָּעֵי דְּלָא לְאִזְדַּוְּוגָא לֵיהּ, אֶלָּא זִמְנָא זְעֵירָא, וְלָא זִמְנָא סַגִּי. כָּל מַה דְּעָבַד וְחָשַׁב, אִיהוּ לְתוֹעַלְתֵּיה, וְלָא חָיִישׁ לְתוֹעַלְתָּא דְּאַחֲרָנִין. לָאו אִיהוּ מָארֵי דְּרָזִין כְּלָל. דָּא אִיהוּ, (משלי י״א:י״ג) הוֹלֵךְ רָכִיל מְגַלֶּה סּוֹד, וְלָא חָשִׁיב מִלּוֹי כְּלָל. דָּא אִיהוּ בְּרָזָא דְּאָת נ' דִּכְלִילָא בְּאָת ז', וְלָא אִקְרֵי נֶאֱמָן רוּחַ בְּקִיּוּמָא.</p>\n<p>מִצְחָא דָּקִיק בְּעִגּוּלָא, דָּא אִיהוּ בַּר נָשׁ חַכִּימָא, בְּמָה דְּאִסְתָּכַּל. לְזִמְנִין אִתְבְּהִיל בְּרוּחֵיהּ. רְחִימוּ דִּילֵיהּ בְּחֶדְוָה. רַחֲמָן אִיהוּ עַל כֹּלָּא, אִסְתָּכַּל בְּמִלִּין סַגִּיאִין. אִי יִשְׁתָּדַּל בְּאוֹרַיְיתָא לֶהֱוֵי חַכִּים יַתִּיר.</p>\n<p>תְּלַת קְמִיטִין עִלָּאִין רַבְרְבִין בְּמִצְחֵיהּ בְּשַׁעֲתָא דְּאִיהוּ מַלִּיל. תְּלַת קְמִיטִין קָרִיב לְעֵינָא חַד. וּתְלַת קְמִיטִין עַל עֵינָא אַחֲרָא. בָּכֵי בְּשַׁעֲתָא דְּאַרְגִּיז. דָּא אִיהוּ טָב יַתִּיר מִכַּמָּה דְּאִתְחָזֵי. אַרְמִי בָּתַר כִּתְפוֹי כָּל מִלִּין דְּעָלְמָא, בֵּין בְּעוֹבָדוֹי, בֵּין בְּמִלִּין אַחֲרָנִין, וְלָא חָיִישׁ. אַצְלַח בְּאוֹרַיְיתָא. כָּל בַּר נָשׁ <Nonei></i>דְּיִשְׁתְּדַל בַּהֲדֵיהּ יַתִּיר מִמִּלִּין אַחֲרָנִין דְּעָלְמָא, לְזִמְנִין אִתְדְּבָק רְעִוּתֵיהּ בְּקֻדְשָׁא בְּרִיךְ הוּא, וּלְזִמְנִין לָא. בְּדִינָא לָא אַצְלַח. אִתְרְחַק אִיהוּ מִן דִּינָא. וְרָזָא דָּא אָת נ' בִּלְחוֹדוֹי, דְּלָא אִתְכְּלִילַת בְּאָת ז'. וּבְגִין דְּלָא אִתְכְּלִילַת בְּאָת ז', אִתְרְחַק מִן דִּינָא, וְלָא קָאִים בֵּיהּ, וּרְחִימוּתָא אִיהוּ סִטְרָא דִּילֵיהּ.</p>\n<p>מִצְחָא דְּאִיהוּ בְּלָא עִגּוּלָא, וְאִיהוּ רַבְרְבָא. הַאי אִיהוּ בַּר נָשׁ דְּכָל זִמְנִין כַּד קָאִים, וְכַד אָזִיל, כָּפִיף רֵישֵׁיהּ. הַאי אִתְפְּלִיג לִתְרֵין לְסִטְרִין, וְאִינּוּן סִטְרֵי שִׁגְעוֹנָא. סִטְרָא חֲדָא אִיהוּ שִׁגְעוֹנָא דְּאִתְחָזֵי, וּבְנֵי נָשָׁא אַחֲרָנִין יַדְעִין שִׁגְעוֹנָא, דְּאִשְׁתְּמוֹדְעָא קַמֵי כֹּלָּא. וְאִיהוּ טִפְּשָׁא.</p>\n<p>בְּמִצְחֵיהּ אִית ד' קְמִיטִין רַבְרְבִין, לְזִמְנִין בְּשַׁעֲתָא דְּמַלִּיל קָמִיט לוֹן בְּמִצְחֵיהּ, וּלְזִמְנִין דְּאִתְפְּשַׁט מִצְחֵיהּ בְּמַשְׁכֵיהּ, וְלָא אִתְחָזוּן. אִינּוּן קְמִיטִין אִתְחָזוּן, קְמִיטִין אַחֲרָנִין רַבְרְבִין בְּסִטְרָא דְּעֵינוֹי, חַיִיךְ לְמַגָּנָא. פּוּמֵיהּ רַבְרְבָא. לָאו אִיהוּ בַר נָשׁ לְתוֹעַלְתָּא. סִטְרָא אַחֲרָא אִיהוּ. שִׁגְעוֹנָא דְּאִתְכַּסֵּי בֵּיהּ, וּבְנֵי נָשָׁא לָא מִסְתַּכְּלָן בֵּיהּ. וְאִיהוּ אִתְחַכָּם בְּמָה דְּאִשְׁתַּדַּל, וַאֲפִילּוּ בְּאוֹרַיְיתָא, אֲבָל לָא לִשְׁמָהּ, אֶלָּא בְּגִין לְאִתְגָּאָה בִּפְנֵי עַמָּא. וְכֹלָּא בִּלְחִישׁוּ וּבְגַאֲוַת לִבָּא, לְאַחֲזָאָה דְּאִיהוּ זַכָּאָה וְלָאו הָכִי. כָּל מִלּוֹי לָאו אִינּוּן לִשְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא בְּגִין בְּנֵי נָשָׁא. וְחָשִׁיב מַחֲשָׁבִין, וְאַנְהִיג גַּרְמֵיהּ. כְּמִנְהָגָא דִּלְבַר, דְּיִסְתַּכְּלוּן בֵּיהּ. הַאי אִיהוּ בְּרָזָא דְּאָת נ', דִּי בִּכְלָלָא דְּאָת ז'.</p>\n<p>מִצְחָא דְּאִיהוּ בְּעִגּוּלָא רַבְרְבָא, פְּקִיחָא אִיהוּ, דָבְּרָנוּ (ס\"א דכרנו) דְּכֹלָּא בֵּיהּ. יָדַע בְּכָל מַה דְּאִשְׁתַּדַּל, אֲפִילּוּ בְּלָא אוּמָנָא דְּיוֹלִיף לֵיהּ. אַצְלַח בְּכָל מַה דְּאִשְׁתַּדַּל. וּבְמָמוֹנָא, לְזִמְנִין אַצְלַח, לְזִמְנִין לָא. מִמִּלָּה זְעֵירָא אִסְתָּכַל בְּמִלִּין סַגִּיאִין. נָבוֹן אִקְרֵי. לָא חָיִישׁ לְמִלִּין דְּעָלְמָא, וַאֲפִילּוּ דְּיִנְדַּע דְּיִתְכְּסִיף <Nonei></i>בְּהוּ לָא חָיִישׁ לוֹן, וְלָא שָׁוִי עַל לִבֵּיהּ. רָכִיךְ לִבָּא אִיהוּ.</p>\n<p>תְּרֵין קְמִיטִין עִלָּאִין רַבְרְבִין בְּמִצְחֵיהּ. חַד קְמִיטָא עַל עֵינָא חַד, וְחַד קְמִיטָא עַל עֵינָא אַחֲרָא. וְאִשְׁתְּכָחוּ תְּלַת קְמִיטִין רַבְרְבִין בְּמִצְחֵיהּ, בְּאִלֵּין דְּעַיְינִין, בַּר קְמִיטָא תַּתָּאָה, דְּאִיהוּ אִתְפְּלַג עַל עַיְינִין. דָּא חָשִׁיב מַחֲשָׁבִין לְגוֹ וְלָא לְבַר. בְּגִין דְּלָא חָשִׁיב לִבְנֵי נָשָׁא בְּעוֹבָדוֹי, וְדָחִיל אִיהוּ לְפוּם שַׁעֲתָא, וְלָא יַתִּיר. לְפַיּוּסָא, אִתְפַּיְּיסָא בְּעוֹבָדוֹי דִּלְבַר מִקָּמֵי בַּר נָשׁ, לָאו אִינּוּן, אֶלָּא לְזִמְנִין כְּרַבְיָא, וּלְזִמְנִין בְּחָכְמָה. דָּא אִיהוּ בְּרָזָא דְּאָת נ', דְּאִיהוּ בִּלְחוֹדוֹי, דְּלָא אִתְכְּלִיל בְּאָת ז'. וְחַלְשָׁא אִיהוּ, דְּלָא אִתְכְּלִיל בְּאִלֵּין אַתְוָון קַדְמָאֵי, אֶלָּא אִסְתְּמִיךְ לְאָת ס' לְאִתְכְּלָלָא בֵּיהּ. וְלָא בְּאַתְוָון קַדְמָאֵי. עַד הָכָא רָזִין דְּחָכְמְתָא דְּמִצְחָא.</p>"],[9520011640,"<p>בְּרָזָא דְּעַיְינִין, בְּרָזָא דְּאָת ס', בְּהַהוּא גַּוְונָא דְּסַחֲרָא לְבַר, וּכְמָה דְּיָתְבָא עֵינָא, דְּיָתְבָא עַל שְׁלִימוּ, דְּלָא שְׁקִיעַ, הַאי לָאו רַמָּאָה הִיא, וְרָחִיק מֵרַמָּאוּתָא, דְּלָא אִית בֵּיהּ כְּלָל.</p>\n<p>גַּוְונֵי דְּעַיְינִין אִינּוּן ד'. חִוָּורוּ לְבַר, דְּסַחֲרָא עֵינָא, כְּגַוְונָא דְּכָל בַּר נָשׁ. לְגוֹ מִנֵּיהּ אוּכָמָא דְּסַחֲרָא, וְאִתְכְּלִיל חִוָּורוּ וְאוּכָמוּ כַּחֲדָא. לְגוֹ מִנֵּיהּ יְרוֹקָא. וְאִתְכְּלִיל בְּאוּכָמָא. לְגוֹ מִנֵּיהּ הַהוּא בַּת עֵינָא, נְקוּדָא אוּכָמָא. דָּא אִיהוּ בַּר נָשׁ דְּחַיִיךְ תָּדִיר, וְחַדֵּי בְּחֵדוּ. וְחָשִׁיב מַחֲשָׁבִין לְטָב, וְלָא אִשְׁתְּלִימוּ אִינּוּן מַחֲשָׁבִין, בְּגִין דְּסָלִיק לוֹן מִיַּד מֵרְעוּתֵיהּ. אִשְׁתַּדַּל בְּמִילֵּי דְּעָלְמָא. וְכַד אִשְׁתַּדַּל בְּמִילֵּי דִּשְׁמַיָּא, אַצְלַח. הַאי אִצְטְרִיךְ לְאִתַּתְקְפָא בֵּיהּ לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, דְּהָא יִצְלַח בָּהּ.</p>\n<p>גְּבִינִי עֵינוֹי רַבְרְבִין, וְכַסְיָין לְתַתָּא. בְּאִינּוּן גַּוְונִין דְּעֵינָא אִית רְשִׁימִין סוּמָקִין דְּקִיקִין בְּאַרְכָּא. אִינּוּן רְשִׁימִין אִקְרוּן אַתְוָון זְעִירִין דְּעֵינָא. בְּגִין דְּאִינּוּן גַּוְונִין דְּעֵינָא. אִי <Nonei></i>נְהִרִין בִּנְהִירוּ, הַהוּא נְהִירוּ סָלִיק אַתְוָון לְאִתְחֲזָאָה, לְאִינוּן מָארִי דְּמִדִּין. בְּאִינּוּן רְשִׁימִין אַחֲרָנִין דְּקִיקִין, וְהַאי אִיהוּ בְּאָת ס', וּכְלִילָא בְּאָת ה'.</p>\n<p>עַיְינִין יְרוֹקִין דְּסַחֲרִין (נ\"א דמסחרא) בְּחִוָּורוּ, וּמִתְעָרְבִין אִינּוּן יְרוֹקִין, בְּהַהוּא חִוָּורוּ. רַחֲמָנָא אִיהוּ, וְאִיהוּ חָשִׁיב תָּדִיר לְתוֹעַלְתֵּיה, וְלָא חָשִׁיב לְנִזְקָא דְּאַחֲרָנִין כְּלוּם.</p>\n<p>גַּוְונָא אוּכָמָא לָא אִתְחָזֵי בֵּיהּ. חָמִיד אִיהוּ וְלָא מִסִּטְרָא בִּישָׁא. וְאִי סַלְּקָא בִּידֵיהּ מִסִּטְרָא בִּישָׁא, לָא יֵתוּב מִנֵּיהּ. מְהֵימָנָא אִיהוּ בְּמָה דְּאִשְׁתְּמוֹדְעא. וּבַמֶּה דְּלָא אִשְׁתְּמוֹדְעָא לָאו מְהֵימָנָא אִיהוּ. מָארֵיהּ דְּרָזִין אִיהוּ, בְּמִלָּה דְּאִיהוּ רָזָא, עַד דְּיִשְׁמַע לְהַהוּא רָזָא בְּאֲתָר אַחֲרָא. כֵּיוָן דִּשְׁמַע לֵיהּ גַּלֵּי כֹּלָּא. וְלָאו עִמֵּיהּ רָזָא כְּלָל, דְּכָל מִלּוֹי לָאו אִינּוּן בִּשְׁלִימוּ. גַּוְונֵי עֵינוֹי סָחֲרָן בְּחִוָּורוּ וּבִירוֹקָא. דָּא אִיהוּ בְּרָזָא דְּאָת ה', וְאִתְכְּלִיל בְּאָת ז', וּבְאָת ס'.</p>\n<p>עַיְינִין צְהִיבִין יְרוֹקִין, שִׁגְעוֹנָא אִית בֵּיהּ. וּבְגִין שִׁגְעוֹנֵיהּ אִיהוּ פּוּם מְמַלֵּל רַבְרְבָן, וְעָבִיד גַּרְמֵיהּ כְּבַר נָשׁ רַב, בְּרַבְרְבָנוּ. וּמַאן דְּאִתְתָּקַּף בֵּיהּ, נֶצַח לֵיהּ. לָא אִתְחָזֵי לְרָזִין דְּאוֹרַיְיתָא, דְּהָא לָא שָׁכִיךְ בְּלִבֵּיהּ, בְּאִינּוּן רָזִין. דְּעָבִיד גַּרְמֵיהּ רַב בְּהוּ. דָּא אִיהוּ בְּרָזָא דְּאָת ה', וְאִתְכְּלִיל בְּאָת ז' בִּלְחוֹדוֹי, וְאִתְרְחַק מֵאָת ס'. וּבְגִין דְּאִיהוּ עָבֵד גַּרְמֵיהּ בְּרַבְרְבָנוּ, אִתְרְחַק מִנֵּיהּ מֵאָת ס', וְלָא אִתְקְרִיב בַּהֲדֵיהּ. דָּא כַּד אִיהוּ מַלִּיל, עָבִיד קְמִיטִין סַגִּיאִין בְּמִצְחֵיהּ.</p>\n<p>עַיְינִין חִוָּורִן, דְּסַחֲרָן זְעֵיר בִּירוֹקָא, מָארֵיהּ דְּרוּגְזָא, וְרַחֲמָנָא אִיהוּ לְרוֹב זִמְנִין. וְכַד אִתְמְלֵי רוּגְזָא, לֵית בֵּיהּ רְחִימוּ כְּלָל, וְאִתְהַפָּךְ לְאַכְזָרִיּוּת. לָאו אִיהוּ מָארֵיהּ דְּרָזִין, דָּא אִיהוּ בְּרָזָא דְּאָת ה', דְּאִתְכְּלִיל בְּאָת ס'.</p>\n<p>עַיְינִין יְרוֹקִין וְחִוָּורִן כַּחֲדָא, וּזְעֵיר מִגָּוֶון אוּכָם בְּהוּ, דָּא אִיהִי מָארֵיהּ דְּרָזִין, וְאַצְלַח בְּהוּ. וְאִי שָׁאַרִי <Nonei></i>בְּאַצְלָחוּתָא אַצְלַח וְסָלִיק. שַׂנְאוֹי לָא יַכְלִין לֵיהּ, וְאִיהוּ שַׁלִּיט עָלַיְיהוּ בְּשׁוּלְטָנוּ, וְאִתְכַּפְיָין קָמֵיהּ. דָּא אִיהוּ בְּרָזָא דְּאָת כ', דְּאִתְכְּלִיל בְּרָזָא דְּאָת ס'. וְעַל דָּא אִיהוּ שַׁלִּיט, אִי שָׁאֲרִי בֵּיהּ. עַד הָכָא רָזִין דְּעַיְינִין לְאִינוּן מָארֵי דְּחָכְמְתָא.</p>"],[9520011641,"<p>רָזָא דְּאַנְפִּין, לְאִינוּן מָארֵי דְּחָכְמְתָא פְּנִימָאָה. דִּיוּקְנִין דְּאַנְפִּין, לָאו אִינּוּן בִּרְשִׁימִין דִּלְבַר, אֶלָּא בְּגוֹ רְשִׁימָא דְּרָזִין פְּנִימָאִין. דְּדִיּוּקְנִין דְּאַנְפִּין, מִתְהַפְּכָן מִגּוֹ דִּיוּקְנִין דִּרְשִׁימוּ דְּאַנְפִּין, סְתִימִין בְּרוּחָא דְּשַׁרְיָא לְגוֹ. וּמִגּוֹ הַהוּא רוּחָא, אִתְחָזֵי לְבַר דִּיוּקְנִין דְּאַנְפִּין, דְּאִשְׁתְּמוֹדְעָן לְגַבֵּי אִינּוּן חַכִּימִין.</p>\n<p>דִּיוּקְנִין דְּאַנְפִּין אִשְׁתְּמוֹדְעָן מִגּוֹ רוּחָא. רוּחָא אִית בְּבַר נָשׁ, דְּרָזִין דְּאַתְוָון חֲקִיקִין בֵּיהּ. וְכֻלְּהוּ אַתְוָון סְתִימִין גּוֹ הַהוּא רוּחָא, וּלְפוּם שַׁעֲתָא סַלְּקִין רְשִׁימִין דְּאִינּוּן אַתְוָון לְגוֹ אַנְפִּין. וּכְמָה דְּאִינּוּן אַתְוָון סַלְּקִין, הָכִי אִתְחָזוּן אַנְפִּין, בְּדִיּוּקְנִין רְשִׁימִין לְפוּם שַׁעֲתָא, בְּחֵיזוּ דְּלָא קַיְּימָא. בַּר אִינּוּן מָארֵי דְּחָכְמְתָא דְּאִתְקַיְּימָן בְּהוּ, וְלָא אִתְנְּשֵׁי מִנַּיְיהוּ.</p>\n<p>הַהוּא אֲתָר דְּאִקְרֵי עָלְמָא דְּאָתֵי, (איהו רזא דאורייתא) וּמִתַּמָּן נַפְקָא רָזָא דְּאוֹרַיְיתָא, בְּכֻלְּהוּ אַתְוָון דְּאִינּוּן כ\"ב אַתְוָון, כְּלָלָא דְּכֹלָּא. וְהַהוּא נַהֲרָא דְּנָפִיק מֵעֵדֶן, נָטִיל כֹּלָּא. וְכַד פַּרְחָן מִנֵּיהּ אִינּוּן רוּחִין וְנִשְׁמָתִין, כֻּלְּהוּ מִצְטַיְּירָן בְּצִיּוּרָא דְּאִינּוּן אַתְוָון, וְהָכִי נַפְקֵי כֻּלְּהוּ. וּבְּגִין כָּךְ, רוּחָא דְּבַר נָשׁ דְּמִצְטַיְּירָא בְּצִיּוּרָא דְּאַתְוָון, עָבִיד צִיּוּרָא בְּאַנְפִּין.</p>\n<p>אֲמַר לֵיהּ רַבִּי שִׁמְעוֹן, אִי הָכִי צִיּוּרָא דְּאִימָא, לָא מִצְטַיְּירָא גּוֹ הַהוּא רוּחָא, אָמְרוּ, הָכִי שְׁמַעְנָא מִנֵּיהּ דְּמֹר, דְּצִיּוּרָא דְּאַתְוָון מִסִּטְרָא דִּלְעֵילָּא, וְצִיּוּרָא דְּאֵימָא מִצְטַיְּירָא בְּהַהוּא רוּחָא לְתַתָּא. צִיּוּרָא דְּאַתְוָון אִתְגְּנִיזוּ לְגוֹ, וְצִיּוּרָא דְּאֵימָא בָּלִיט לְבַר.</p>\n<p>צִיּוּרָא דְּאִימָא, פְּנֵי אָדָ\"ם, פְּנֵי אַרְיֵ\"ה, פְּנֵי שׂוֹ\"ר, פְּנֵי נֶשֶׁ\"ר. וְרוּחָא עָבִיד צִיּוּרָא דְּכֻלְּהוּ לְבַר לְפוּם שַׁעֲתָא, בְּגִין דְּכָל מַה דְּאִיהוּ מִסִּטְרָא <Nonei></i>דְּרוּחָא בָּלְטָא לְבַר, וְאִתְחַזֵּי וְאִתְגְּנִיז. וְכָל הָנֵי דִּיוּקְנִין, אִתְחַזְיָין, מִתְצַיְּירָן בְּצִיּוּרָא דְּאַתְוָון אַף עַל גַּב דְּאִינּוּן גְּנִיזִין. אִלֵּין אַרְבַּע דִּיוּקְנִין אִתְחַזְיָין לְפוּם שַׁעֲתָא, לְאִינוּן מָארֵי דְּעַיְינִין, דְּיַדְעִין בְּרָזָא דְּחָכְמְתָא לְאִסְתַּכְּלָא בְּהוּ.</p>\n<p>צִיוּרָ\"א קַדְמָאָ\"ה, כַּד אָזִיל בַּר נָשׁ בְּאֹרַח קְשׁוֹט, אִינּוּן דְּיַדְעִין בְּרָזִין דְמָרֵיהוֹן מִסְתַּכְּלָן בֵּיהּ, בְּגִין דְּהַהוּא רוּחָא דִּלְגוֹ, מְתַּתְקְנָא בֵּיהּ, וּבָלִיט לְבַר, צִיּוּרָא דְּכֹלָּא. וְהַהוּא צִיּוּרָא אִיהוּ צִיּוּרָא דְּאָדָם, וְדָא אִיהוּ צִיּוּרָא שְׁלִים יַתִּיר מִכָּל צִיּוּרִין. וְדָא אִיהוּ צִיּוּרָא, דְּאַעְבַּר לְפוּם שַׁעֲתָא, קָמֵי עֵינַיְיהוּ דְּחַכִּימֵי לִבָּא. הַאי כַּד מִסְתַּכְּלָן בְּאַנְפּוֹי לְבַר, אִינּוּן אַנְפִּין דְּקַיְימִן קָמֵיהּ, עַיְינִין דְּלִבָּא רָחִים לוֹן.</p>\n<p>אַרְבַּע סִימָנִין דְּאַתְוָון אִית בְּהוּ, שׁוּרְיְיקָא חַד בָּלִיט בִּשְׁכִיבוּ, בְּסִטְרָא דִּיִמִינָא, וְשׁוּרְיְיקָא חַד דְּכָלִיל תְּרֵין אַחֲרָנִין דַּאֲחִידָן בֵּיהּ, בְּסִטְרָא דִּשְׂמָאלָא. וְאִלֵּין ד' סִימָנִים, אִינּוּן ד' אַתְוָון, דְּאִקְרוּן עֵדוּת וְסִימָנָא דָּא ע'. הַהוּא שׁוּרְיְיקָא דִּסְטַר יְמִינָא, דְּבָלִיט בִּשְׁכִיבוּ. ד' וְאִינּוּן תְּרִין אַתְוָון דְּמִתְחַבְּרָן בֵּיהּ (ס\"א ו\"ת אינון עדות') ו\"ת אִינּוּן הַהִיא שׁוּרְיְיקָא דְּכָלִיל תְּרֵין אַחֲרָנִין, וְדָא אִיהוּ רָזָא דִּכְתִּיב, (תהילים פ״א:ו׳) עֵדוּת בִּיהוֹסֵף שְׁמוֹ דְּכָל מַאן דְּחָמָא לֵיהּ הֲוָה רָחִים לֵיהּ בְּלִבּוֹי, וּבִרְחִימוּ אִשְׁתְּלִים.</p>\n<p>זַרְעָא דְּדָוִד מִתְהַפְּכָן בֵּיהּ חֵיזוּ דִּגְוָונִין, וּבְּגִין כָּךְ טָעָה שְׁמוּאֵל, דִּכְתִּיב, (שמואל א ט״ז:ז׳) אַל תַּבֵּט אֶל מַרְאֵהוּ, בְּגִין דְּסִטְרָא אַחֲרָא הֲוָה בֵּיהּ בֶּאֱלִיאָב, דְּלָא הֲוָה הָכִי בְּדָוִד, דְּיּוּקְנִין דְּדָוִד טְמִירִין אִינּוּן, דְּהָא דְּיּוּקְנִין דְּסִטְרָא אַחֲרָא, אִתְכְּלִיל גּוֹ דִּיּוּקְנִין, וְהַהוּא דִּיּוּקְנָא דִּסְטָר אַחֲרָא אִתְחָזֵי בֵּיהּ בְּקַדְמִיתָא, דְּאַעְבַּר עַל עַיְינִין לְפוּם שַׁעֲתָא, וּבָהִיל לִבָּא וְדָחִיל, וּלְבָתַר (שמואל א ט״ז:י״ב) וְטוֹב רוֹאִי וַיְיָ' עִמּוֹ. וְדָא אִיהוּ עֵדוּת לְגַבֵּיהּ.</p>\n<p>דִּיּוּקְנָא דָּא דְּאָדָם, כָּלִיל כָּל דִּיוּקְנִין, וְכֻלְּהוּ כְּלִילָן בֵּיהּ, הַאי לָא בָּהִיל בְּרוּחֵיהּ. בְּשַׁעֲתָא דְּרוּגְזֵיהּ אִיהוּ בְּנַיְיחָא, וּמִלּוֹי בְּנַיְיחָא, וּמִיָּד אִתְפָּיָּיס.</p>\n<p><Nonei></i>זַרְעָא דְּדָוִד דְּאִתְחָזֵי בֵּיהּ הַהוּא דִּיּוּקְנָא בְּקַדְמִיתָא, דְּאַעְבַּר לְפוּם שַׁעֲתָא עַל עַיְינִין, בְּרוּגְזֵיהּ בְּנַיְיחָא, מִיָּד אִתְפָּיַּיס. אֲבָל נָטִיר דְּבָבוּ כְּנָחָשׁ לְסוֹפָא. בְּגִין דְּהַהוּא סִטְרָא גַּרְמָא לֵיהּ, דְּסַחֲרָא בְּכָל סִטְרִין. אֲבָל מוֹחָא דִּבְגוֹ קְלִיפָה וְלִבָּא מִתְיַשְּׁרָא, וְיַצִּיבָא דָּא לְאִינוּן זַכָּאִין. אֲבָל חַיָּיבִין לָא מִתְעַבְּרָן מֵהַהוּא דִּיּוּקְנָא קַדְמָאָה בִּישָׁא, וְאִתְחַבְּרָן (ואסתאבן) בֵּיהּ בְּכֹלָּא.</p>\n<p>צִיוּרָ\"א תִּנְיָינָ\"א, אִי הַהוּא בַּר נָשׁ לָא אָזִיל כָּל כַּךְ בְּאָרְחָא בִּישָׁא, וְאַסְטֵי מֵהַהוּא אָרְחָא, וְתָב לְמָארִיהּ, לָא דְּהוּא רְגִילָא בְּאָרְחוֹי דִּמְתַקְּנָן, אֶלָּא אִיהוּ דְּהֲוָה בְּאִינּוּן אוֹרְחֵי מִתְעֲדֵי, וְסָטֵי מִנַּיְיהוּ וְתָב לְמָארֵיהּ. הַאי אִיהוּ רוּחָא טָבָא שָׁארֵי לְמִשְׁרִי עֲלוֹי, וּלְאִתַּתְקְפָא עַל זוּהֲמָא קַדְמָאָה דְּהֲוָה בֵּיהּ, וּבָלִיט לְבַר, בְּאִסְתַּכְּלוּתָא, דְּעַיְינִין לְפוּם שַׁעֲתָא, כְּחַד דִּיּוּקְנָא דְּאַרְיֵה דְּאִתְגַּבָּר הַאי בְּשַׁעֲתָא דְּחָמֵי לֵיהּ, הַהוּא חֵיזוּ גָּרִים לֵיהּ לְאַעְבָּר בְּלִבֵּיהּ אַרְיֵה דְּמִתְגַּבְּרָא לְפוּם שַׁעֲתָא.</p>\n<p>הַאי מִסְתַּכְּלָן בְּאַנְפּוֹי לְבָתַר, אִינּוּן אַנְפִּין דְּלִבָּא לָא רָחִים לוֹן לְפוּם שַׁעֲתָא, וּמִיָּד תָּב לִבֵּיהּ וְרָחִים לֵיהּ. כַּד מִסְתַּכְּלָן בֵּיהּ אַכְסִיף, וְחָשִׁיב דְּכֹלָּא יַדְעִין בֵּיה. אַנְפּוֹי חַפְיָין דָּמָא לְפוּם שַׁעֲתָא, מִתְהַפְּכָן לְחִוְּורָא אוֹ לִירוֹקָא.</p>\n<p>תְּלַת שׁוּרְיְיקָן אִית בְּאַנְפּוֹי. חַד לִימִינָא, דְּדָא אִתְפָּשַׁט בְּאַנְפּוֹי וְאִתְאֲחִיד בֵּיהּ. חַד דְּסַלְּקָא לְחוֹטָמֵיהּ לְעֵילָּא, וּתְרֵין לִשְׂמָאלָא. וְחַד דְּאִתְפָּשַּׁט לְתַתָּא מֵאִינּוּן תְּרִין, וְאָחִיד בְּהַאי וּבְהַאי. וְאִלֵּין אִינּוּן אַתְוָון דְּמִתְחַקְּקָן בְּאַנְפּוֹי, וְאִינּוּן בַּלְטִין דְּלָא שְׁכִיבִין. וְכַד מִתְיַישְׁבָא וְאַרְגִּיל בְּאֹרַח קְשׁוֹט, שְׁכִבִין.</p>\n<p>וְרָזָא דְּאִינּוּן אַתְוָון אִיהוּ קָרִיב. דָּא הֲוָה רָחִיק, וְהַשְׁתָּא אִינּוּן אַתְוָון בַּלְטִין בְּאַנְפּוֹי, וְסָהֲדִין בֵּיהּ בִּבְהִילוּ. וְסִימָנָא דָּא ק' (ד\"א ה') מִסְּטָר יְמִינָא אַתְוָון אַחֲרָנִין מִסְּטָר <Nonei></i>שְׂמָאלָא, וְאַף עַל גַּב דְּשׁוּרְיָיקֵי אַחֲרָנִין אִתְחָזוּן בְּאַנְפּוֹי, לָא בַּלְטִין לְבַר כְּהָנֵי. בַּר בְּזִמְנָא דְּהֲוָה אָזִיל בְּעַקִּימוּ.</p>\n<p>הַאיִ אִיהוּ זַרְעָא דְּדָוִד, אִתְהַפַּךְ מֵחֵיזוּ דָּא. בְּקַדְמִיתָא אִתְחָזֵי בְּדִיּוּקְנָא דְּאָדָם, וּלְבָתַר קַיְימָא בְּדִיּוּקְנָא דְּאַרְיֵה, וְאִתְפְּרַשׁ בְּדִיּוּקְנָא דְּסִטְרָא אַחֲרָא, וּבְכֹלָּא, מִתְהַפְּכָא מִשְּׁאָר בְּנֵי נָשָׁא.</p>\n<p>צִיוּרָ\"א תְּלִי\"תָאָה, אִי הַהוּא בַּר נָשׁ אָזִיל בְּאָרְחָא דְּלָא מְתַּתְקְנָא, וְסָטֵי אוֹרְחוֹי מֵאָרְחֵי דְּאוֹרַיְיתָא, הַהוּא רוּחָא קַדִּישָׁא אִסְתַּלָּק מִנֵּיהּ, וְרוּחָא אַחֲרָא אִתְחָזֵי בֵּיהּ, וּדְיוּקְנָא אַחֲרָא, וּבָלִיט לְבַר, בְּאִסְתַּכְּלוּתָא דְּעַיְינִין דְּחַכִּימֵי לִבָּא, לְפוּם שַׁעֲתָא דִּיּוּקְנָא דְּשׁוֹר. בְּשַׁעֲתָא דְּחָמָאן לֵיהּ, מַעְבְּרָן בְּלִבַּיְיהוּ הַהוּא דִּיּוּקְנָא, וְאִסְתַּכְּלָן בֵּיהּ.</p>\n<p>ג' קוּרְטָמֵי סוּמָקֵי בְּאַנְפּוֹי, בְּסִטְרָא דִּימִינָא, וְאִינּוּן שׁוּרְיָיקֵי סוּמָקִין דְּקִיקִין. וּתְלַת בִּשְׂמָאלָא, וְאִלֵּין אִינּוּן אַתְוָון דְּבַלְטִין בֵּיהּ. חַד אִיהוּ שׁוּרְיְיקָא דָּקִיק בְּעִגּוּלָא, וּתְרֵין דְּקִיקִין אַחֲרָנִין עָלֵיהּ, וְכֻלְּהוּ בְּעִגּוּלָא. וּכְדֵין שְׁקִיעִין עֵינוֹי.</p>\n<p>וְרָזָא דְּאִינּוּן אַתְוָון. חַד אִיהוּ כ', תְּרֵין אַחֲרָנִין ר\"ת אִינּוּן. וְכֵן לִסְטַר שְׂמָאלָא, וְסִימָנָא דָּא הַהוּא דִּכְתִּיב, (ישעיהו ג׳:ט׳) הַכָּרַת פְּנֵיהֶם עָנְתָה בָּם וְאִלֵּין אַתְוָון בַּלְטִין בְּאַנְפִּין, עַל כָּל שְׁאַר שׁוּרְיָיקִין. וְאִי תָּב מִשְּׂמָאלָא לִימִינָא, אִתְכַּפְיָא הַהוּא רוּחָא וְאִתְתָּקַּף רוּחָא דְּקֻדְשָׁא, וְאִלֵּין שׁוּרְיָיקִין שְׁכִיבוּ, וְאַחֲרָנִין בַּלְטִין לְבַר, כְּמָה דְּאִתְּמַר.</p>\n<p>זַרְעָא דְּדָוִד אִיהוּ בְּהִפּוּכָא, אִתְחַזְיָא בְּדִיּוּקְנָא דְּאַרְיֵה בְּקַדְמִיתָא, וּלְבָתַר אִתְהַדַּר בְּדִיּוּקְנָא דְּשׁוֹר. תְּרִין שׁוּרְיָיקִין אוּכָּמִין בְּאַנְפּוֹי, חַד מִימִינָא, וְחַד מִשְּׂמָאלָא, וְאִלֵּין אִינּוּן אַתְוָון, חַד אִקְרֵי ד', וְחַד אִקְרֵי ע', וְכֹלָּא מִתְהַפְּכָא מִשְּׁאָר בְּנֵי נָשָׁא.</p>\n<p>צִיוּרָ\"א רְבִיעָ\"אָה, דָּא אִיהוּ צִיּוּרָא דְּבַר נָשׁ, דְּקַיְּימָא תָּדִיר לְאִתְתַּקְנָא עַל רָזָא דְּמִלְקַדְּמִין, הַאי אִיהוּ חֵיזוּ לְחַכִּימֵי לִבָּא בְּדִיּוּקְנָא דְּנֶשֶׁר. הַהוּא רוּחָא דִּילֵיהּ אִיהוּ רוּחָא חַלְשָׁא. הַאי לָא אַחְזֵי בְּאַנְפִּין אַתְוָון דְּבַלְטִין לְבַר, דְּהָא אִתְאֲבִידוּ מִנֵּיהּ, וְאִשְׁתְּקָעוּ בְּזִמְנָא אַחֲרָא דְּמִלְקַדְּמִין, דְּאִסְתָּלָּקוּ מִנֵּיהּ, וְעַל דָּא לָא בַּלְטִין בֵּיִהּ.</p>\n<p>וְרָזָא דִּילֵיהּ, עֵינוֹי לָא נְהִרִין בִּנְצִיצוּ, כַּד אִיהוּ בְּחֶדְוָה. וּבְזִמְנָא דְּסָפַר שְׂעַר רֵישֵׁיהּ וְדִיקְנִיהּ. בְּגִין דְּרוּחֵיהּ לָא נָהִיר לֵיהּ בְּאַתְוָון, וְאִשְׁתְּקַע נְצִיצוּ דִּילֵיהּ דְּהֲוָה בְּקַדְמִיתָא. לָא קַיְּימָא בְּאִסְתַּכְּלוּתָא דְּאַנְפִּין לְאִסְתַּכְּלָא. וְרָזָא דְּהַאי (קהלת ד׳:ב׳) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ מִן הַחַיִּים אֲשֶׁר הֵמָּה חַיִּים עֲדֶנָּה. זַרְעָא דְּדָוִד, (תהילים כ״ה:י״ד) סּוֹד יְיָ' לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם.</p>\n<p>בְּרוּחָא דְּבַר נָשׁ, אִצְטְיָּירוּ אַתְוָון, כְּמָה דְּאִתְּמַר, וְאִיִהוּ בָּלִיט לוֹן לְבַר, וְאִתְמְסַר חָכְמְתָא דָּא לְחַכִּימֵי לִבָּא לְמִנְדַּע וּלְאִשְׁתְּמוֹדְעָא, רוּחָא קַיְימָא בְּרָזָא (בראשית ה) דְּזֶה סֵפֶר, וְכֹלָּא בְּרָזָא דָּא קַיְּימָא, בַּר חֵיזוּ דְּאַנְפִּין דְּאִתְּדָּן בְּגַוְונָא אַחֲרָא, כְּפוּם שׁוּלְטָנוּ <Nonei></i>דְּרוּחָא, אוֹ מָארִיהּ דְּרוּחָא. זַכָּאִין אִינּוּן חַכִּימִין דְּכֹלָּא אִתְמְסַר לוֹן לְמִנְדַּע. עַד הָכָא רָזָא דְּאַנְפִּין.</p>"],[9520011642,"<p>מִכָּאן וּלְהָלְאָה בְּרָזָא דְּשִׂפְוָון, בְּאָת פ' דְּכָלִיל בְּרָזָא דְּאָת ס'. שִׂפְוָון רַבְרְבָן, דָּא אִיהוּ בַּר נָשׁ מַלִּיל בְּלִישָׁנָא בִּישָׁא, וְלָא אַכְסִיף, וְלָא דָּחִיל, מָארֵי דְּמַחְלוֹקֶת, רְכִילָא אִיהוּ בֵּין הַאי לְהַאי. (משלי ו׳:י״ט) וּמְשַׁלֵּחַ מְדָנִים בֵּין אַחִים. לָאו אִיהוּ מָארִיהּ דְּרָזִין, וְכַד אִשְׁתַּדַּל בְּאוֹרַיְיתָא מְכַסֶּה רָזִין, אֲבָל מָארִיהּ דְּלִישָׁנָא בִּישָׁא, וְלָא שָׁוִי דְּחִילוּ בְּלִבֵּיהּ.</p>\n<p>וְסִימָנָא דָּא, אָת פ' דְּכָלִיל בְּאָת ר' וְלָא אִתְכְּלִיל בְּאָת ס'. הַאי אִיהוּ דְּאִתְחָזֵי דְּאִיהוּ זַכָּאָה, וְלָא דָּחִיל חַטָּאָה אִיהוּ, וְלָא בָּעֵי לְאִשְׁתַּדְּלָא אֲבַתְרֵיהּ, בְּגִין דְּכָל מִלּוֹי אִינּוּן בְּפוּמָא וְלָא בְּגוּפָא.</p>\n<p>שִׂפְוָון עַתִּיקִין בְּעַתִּיקוּ, וְלָאו דְּקִיקִין. הַאי אִיהוּ בַּר נָשׁ מָארֵיהּ דְּרוּגְזָא יַתִּיר. מָארִיהּ דִּזְדוֹנָא. לָא יָכִיל לְמִסְבַּל מִלָּה. מָארֵי דְּלִישָׁנָא בִּישָׁא בְּפַרְהֶסְיָא, בְּלָא כִּסּוּפָא כְּלַל. לְזִמְנִין אִשְׁתָּדַּל בְּלֵיצָנוּתָא. הַאי אִיהוּ בַּר נָשׁ דְּבָעֵי לְאִתְרַחֲקא מִנֵּיהּ.</p>\n<p>אִתְמְלֵי דִּיקְנֵיהּ בְּשַׂעְרָא, הַהוּא, לִישָׁנָא בִּישָׁא, אוִֹרִי עָלֵיהּ בְּפַרְהֶסְיָא, לֵית לֵיהּ כִּסּוּפָא. אִשְׁתָּדַּל בְּמַחְלוֹקֶת. אַצְלַח בְּמִלֵּי דְּעָלְמָא. חָמֵי בְּשַׂנְאוֹי. דָּא אִיהוּ (משלי ו׳:י״ג) קוֹרֵץ בְּעֵינָיו, עַל דָּא אִתְּמַר (משלי כ״א:כ״ט) הֵעֵז אִישׁ רָשָׁע בְּפָנָיו. דָּא אִיהוּ בְּרָזָא דְּאָת פ' בִּלְחוֹדוֹי. דְּלָא אִתְכְּלִיל בְּאָת ס' כְּלָל. וּלְזִמְנִין אִתְחַבָּר בְּאָת ר' בְּהַאי אָת ר' אִתְכְּלִיל.</p>"],[9520011643,"<p>בְּרָזָא דְּאוּדְנִין, מַאן דְּאוּדְנוֹי רַבְרְבִין, טִפְּשָׁא בְּלִיבֵּיהּ וְשִׁגְעוֹנָא בְּרוּחֵיהּ. מַאן דְּאוּדְנוֹי זְעִירִין, וְקַיְימִין עַל קִיּוּמָא. פְּקִיחָא דְּלִבָּא בְּאִתְעָרוּתָא אִיהוּ. צָבֵי לְאִשְׁתַּדְּלָא בְּכֹלָּא. וְרָזָא דָּא אָת י' דְּאִתְכְּלִיל בְּכָל שְׁאַר אַתְוָון.</p>\n<p>עַד הָכָא, רָזִין דְּדִיּוּקְנִין דְּבַר נָשׁ. מִכָּאן וּלְהָלְאָה, רָזִין אַחֲרָנִין בְּאַתְוָון דְּמֹר, דְּלָא קַיְימִין גּוֹ פַּרְצוּפָא, אֶלָּא לְמִנְדַּע רָזִין דְּהַאי פְּסוּקָא, גּוֹ דַּרְגִּין עִלָּאִין, בִּזְמַנִין וּתְקִיפִין דְּהַאי עָלְמָא, וְלָא זָכֵינָן בְּהוּ.</p>\n<p>אָמַר ר' שִׁמְעוֹן, בָּנַי, זַכָּאִין אַתּוּן בְּעָלְמָא, דֵּין, וּבְעָלְמָא דְּאָתֵי, וְזַכָּאִין עֵינַי, דְּיִזְכּוּן לְמֶיחֱמֵי דָּא, כַּד אֵיעוּל לְהַהוּא עָלְמָא דְּאָתֵי. בְּגִין נִשְׁמָתִי קָרֵי לְעַתִּיק יוֹמִין, הַאי קְרָא, (תהילים כ״ג:ה׳) תַּעֲרוֹךְ לְפָנַי שֻלְחָן נֶגֶד צוֹרְרָי דִּשַּׁנְתָּ בַשֶּׁמֶן רֹאשִׁי כּוֹסִי רְוָיָה. וְקוּדְשָׁא בְּרִיךְ הוּא קָרֵי עֲלָן, (ישעיהו כ״ו:ב׳) פִּתְחוּ שְׁעָרִים וְיָבֹא גּוֹי צַדִּיק שׁוֹמֵר אֱמוּנִים. \"</p>"],[9520011644,"<p>אוּף אִינּוּן פָּתְחוּ וְאָמְרוּ, כְּתִיב (יחזקאל א׳:ח׳) וִידֵי אָדָם מִתַּחַת כַּנְפֵיהֶם, הַאי קְרָא אוּקְמוּהָ חַבְרַיָּיא, דְּאִינּוּן יְדִין לְקַבְּלָא מָארִיהוֹן דִתִיוּבְתָּא דְּתָבָאָן לְגַבֵּי (נ\"א לקבל) קוּדְשָׁא בְּרִיךְ הוּא. אֲבָל יְדֵי אָדָם, אִלֵּין אִינּוּן דְּיּוּקְנִין וְרָזִין עִלָּאִין, דְּשַׁוִּי קוּדְשָׁא בְּרִיךְ הוּא בְּבַר נָשׁ, וְסִדֵּר לוֹן בְּאֶצְבְּעָן לְבַר וּלְגוֹ. וּבְהַהוּא כַּ\"ף.</p>\n<p>וְקוּדְשָׁא בְּרִיךְ הוּא כַּד בָּרָא לֵיהּ לְבַר נָשׁ, סִדֵר בֵּיהּ, כָּל דִּיּוּקְנִין דְּרָזִין עִלָּאִין, דְּעָלְמָא דִּלְעֵילָּא, וְכָל דִּיּוּקְנִין דְּרָזִין תַּתָּאִין, דְּעָלְמָא דִּלְתַתָּא, וְכֹלָּא מִתְחַקְּקָא בְּבַּר נָשׁ, דְּאִיהוּ קָאִים בְּצֶלֶם אֱלהִים, בְּגִין דְּאִקְרֵי יְצִיר כַּ\"ף.</p>\n<p>וְרָזָא דְּכַ\"ף, דְּאָת דָּא דְּאִקְרֵי כַּ\"ף, דִּכְתִּיב, (בראשית א׳:כ״ז) וַיִּבְרָא אֱלהִים אֶת הָאָדָם בְּצַלְמוֹ, דָּא אִיהוּ רָזָא דְּאָת כַּ\"ף. אָת דָּא, אִית בֵּיהּ רָזִין עִלָּאִין, וְדִיּוּקְנִין עִלָּאִין. בְּהַאי כַּ\"ף תַּלְיָין עֶשֶׂר אֲמִירָן מִימִינָא וּמִשְּׂמָאלָא, חָמֵשׁ מִימִינָא, וְחָמֵשׁ מִשְּׂמָאלָא, וְאִינּוּן חַד בְּרָזָא חֲדָא.</p>\n<p>(תנינן כתיב (יחזקאל כ״א:כ״ב) וגם אני אכה כפי אל כפי, דלהוו דא עם דא בפלוגתא ויסתלקו ברכאן מעלמא, הואיל וגאותא דישראל אתיהיבת לעמין. כד מתחברן כחדא, כתיב, (במדבר ז׳:י״ד) כף אחת עשרה זהב מלאה קטרת רמז לחבורא חדא.) וְכַד הֲווֹ בְּחִבּוּרָא חֲדָא, כְּתִיב, וַיִּבְרָא אֱלהִים אֶת הָאָדָם בְּצַלְמוֹ וְגוֹ'. וַיִּבְרָא אֱלֹהִים (את האדם) דָּא סְלִיקוּ דְּמַחֲשָׁבָה בְּרָזָא פְּנִימָאָה. אֶת הָאָדָם: רָזָא דְּכַר וְנוּקְבָּא כַּחֲדָא, בְּצֶלֶם אֱלהִים רָזָא דְּכַף (אחרא).</p>\n<p>כַּד אִתְבְּרֵי אָדָם, מַה כְּתִיב, בֵּיהּ, (איוב י׳:י״א) עוֹר (בראשית כ' ע\"ב) וּבָשָׂר תַּלְבִּישֵׁנִי <Nonei></i>וְגוֹ'. אִי הָכִי הָאָדָם מַהוּ. אִי תֵּימָא, דְּאֵינוֹ אֶלָּא עוֹר וּבָשָׂר וְעַצָמוֹת וְגִידִים, לָאו הָכִי, דְּהָא וַדַּאי הָאָדָם לָאו אִיהוּ אֶלָּא נִשְׁמְתָא. וְאִלֵּין דְּקָאָמַר עוֹר וּבָשָׂר עַצָמוֹת וְגִידִים, כֻּלְּהוּ לָא הֲווֹ אֶלָּא מַלְבּוּשָׁא בִּלְחוֹדוֹי, מָאנִין אִינּוּן דְּבַר נָשׁ, וְלָאו אִינּוּן אָדָם. וְכַד הַאי אָדָם אִסְתַּלָּק, אִתְפָּשַׁט מֵאִנּוּן מָאנִין דְּקָא לְבִישׁ.</p>\n<p>עוֹר דְּאִתְלְבַּשׁ בֵּיהּ בַּר נָשׁ. וְכָל אִינּוּן עַצְמוֹת וְגִידִים, כֻּלְּהוּ בְּרָזָא דְּחָכְמְתָא עִלָּאָה כְּגַוְונָא דִּלְעֵילָּא. עוֹר כְּגַוְונָא דִּלְעֵילָּא, כְּמָה דְּאוֹלִיף מֹר, בְּאִינּוּן יְרִיעוֹת, דִּכְתִּיב, (תהילים ק״ד:ב׳) נוֹטֶה שָׁמַיִם כַּיְרִיעָה. (שמות כ״ה:ה׳) עוֹרוֹת אֵלִים מְאָדָּמִים וְעוֹרוֹת תְּחָשִׁים. אִינּוּן מַלְבּוּשִׁין דִּלְעֵילָּא, דִּמְסַכְּכֵי לְמַלְבּוּשָׁא, אִתְפַּשָּׁטוּתָא דְּשָׁמַיִם, דְּאִיהוּ מַלְבּוּשָׁא דִּלְבַר. יְרִיעוֹת אִינּוּן מַלְבּוּשָׁא דִּלְגוֹ, וְאִיהוּ קְרוּמָא דְּסָכִיךְ עַל בִּשְׂרָא.</p>\n<p>עַצְמוֹת וְגִידִים, אִינּוּן רְתִיכִין, וְכָל אִינּוּן חַיָּילִין, דְּקַיְימִין לְגוֹ. וְכֻלְּהוּ מַלְבּוּשִׁין לִפְנִימָאָה, רָזָא דְּאָדָם עִילָּאָה, דְּאִיהוּ פְּנִימָאָה.</p>\n<p>אוּף הָכִי רָזָא לְתַתָּא, אָדָם אִיהוּ פְּנִימָאָה לְגוֹ. מַלְבּוּשִׁין דִּילֵיהּ כְּגַוְונָא דִּלְעֵילָּא. עַצְמוֹת וְגִידִין, כְּגַוְונָא דְּקָאמְרָן בְּאִינּוּן רְתִיכִין וּמַשִׁירְיָין. בָּשָׂר אִיהוּ סָכִיךְ עַל אִינּוּן מַשִׁירְיָין וּרְתִיכִין, וְקַיְּימָא לְבַר, וְדָא (ויקרא ק\"ע ע\"א) רָזָא דְּאִתְמַשְּׁכָא לְסִטְרָא אַחֲרָא. עוֹר דְּסָכִיךְ עַל כֹּלָּא, דָּא אִיהוּ כְּגַוְונָא דְּאִינּוּן רְקִיעִין, דְּסָכִיכוּ עַל כֹּלָּא. וְכֻלְּהוּ מַלְבּוּשִׁין לְאִתְלַבְּשָׁא בְּהוּ. פְּנִימָאָה דִּלְגוֹ רָזָא דְּאָדָם. וְכֹלָּא רָזָא, לְתַתָּא כְּגַוְונָא דִּלְעֵילָּא. וְעַל דָּא וַיִּבְרָא אֱלקִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹקִים, (תרי אלהים הכא חד כלפי דכר וחד כלפי נוקבא) וְרָזָא דְּאָדָם לְתַתָּא כֹּלָּא אִיהוּ בְּרָזָא דִּלְעֵילָּא.</p>\n<p>בְּהַאי רְקִיעָא דִּלְעֵילָּא, דִּמְסַכֵּךְ עַל כֹּלָּא, אִתְרְשִׁימוּ בֵּיהּ רְשִׁימִין, לְאִתְחֲזָאָה וּלְמִנְדַּע בְּאִינּוּן רְשִׁימִין, דְּאִתְקְבִיעוּ בֵּיהּ מִלִּין וְרָזִין סְתִימִין. וְאִינּוּן רְשִׁימִין דְּכֹּכָבַיָּא וּמַזָּלֵי, דְּאִתְרְשִׁימוּ וְאִתְקְבִיעוּ בְּהַאי רְקִיעָא, דְּסָכִיךְ לְבַר. אוּף הָכִי עוֹר, דְּאִיהוּ סִכּוּכָא לְבַר בְּבַר נָשׁ, דְּאִיהוּ רְקִיעָא דְּסָכִיךְ עַל כֹּלָּא, אִית בֵּיהּ רְשִׁימִין וְשִׂרְטוּטִין, וְאִינּוּן כֹּכָבַיָּא וּמַזָּלֵי דְּהַאי עוֹר. לְאִתְחֲזָאָה בְּהוּ, וּלְמִנְדַּע בְּהוּ, מִלִּין וְרָזִין סְתִימִין, בְּכֹכָבַיָּא וּמַזְלַיא, לְעַיְּינָא בְּהוּ חַכִּימֵי לִבָּא, וּלְאִסְתַּכְּלָא בְּהוּ לְמִנְדַּע אִסְתַּכְּלוּתָא בְּאַנְפִּין, בְּרָזִין דְּקָאָמַרָן, וְרָזָא דָּא, (ישעיהו מ״ז:י״ג) הוֹבְרֵי שָׁמַיִם הַחוֹזִים בַּכֹּכָבִים.</p>\n<p>וְדָא אִיהוּ, כַּד אִינּוּן נְהִירִין וְקַיְימִין, בְּלא רוּגְזָא. בְּזִמְנָא דְּרוּגְזָא שַׁלְטָא עָלֵיהּ דְּבַר נָשׁ, דִּינָא אַחֲרָא אִתְמְסַר לְמִנְדַּע בֵּיהּ. בְּמָה דְּלָא אִתְיְיהִיב לְשַׁלְּטָאָה, לְמִנְדַּע בְּזִמְנָא דְעֵינָא (נ\"א דדינא) שַׁלְטָא בִּרְקִיעָא.</p>\n<p>אֲבָל אִסְתַּכְּלוּתָא דְּאַנְפִּין עַל אָרַח קְשׁוֹט, בְּשַׁעֲתָא דְּאַנְפִּין נְהִירִין, וְקַיְּימָא בַּר נָשׁ עַל קִיּוּמָא, וְאִינּוּן רְשִׁימִין אִתְחָזוּן בְּאֹרַח קְשׁוֹט, דִּכְדֵין בְּהַהוּא אִסְתַּכְּלוּתָא יָכִיל לְאִתְּדָּנָא עַל בּוּרְיֵיהּ יַתִּיר, וְאַף עַל גַּב דִּבְכֹלָּא כָּל אִינּוּן חַכִּימִין יַכְלִין לְאִסְתַּכְּלָא.</p>\n<p>שִׂרְטוּטֵי יְדִין וְשִׂרְטוּטֵי אֶצְבְּעָן, לְגוֹ, כֻּלְּהוּ קַיְימִין בְּרָזִין אַחֲרָנִין, לְמִנְדַּע בְּמִלִּין סְתִימִין. וְאִלֵּין אִינּוּן כֹּכָבַיָּא, דִּנְהִירִין לְאִסְתַּכְּלָא גּוֹ מַזָּלֵי, בִּטְסִירִין עִלָּאִין.</p>\n<p>אֶצְבְּעָן קַיְימֵי בְּרָזִין עִלָּאִין. טוּפְרֵי אֶצְבְּעָאן, דְּקַיְימִין דְּחַפְיָן, לְבַר, הוּא אוּקְמוּהָ בְּאִינּוּן רָזִין, דַּהֲווֹ (בראשית כ\"א ע\"א) פָּנִים דִּלְבַר, וּבְהוּ אִית רָזִין, לְאִינוּן חֲרָשִׁין, דְּמִסְתַּכְלֵי בְּטוּפְרֵי, בִּנְהִירוּ דְּמִלָּה אַחֲרָא, דְּשַׁלְטָא בְּהוּ, וְאִינּוּן חֲרָשִׁין קָא מְסָאֲבֵי לְהַהוּא אֲתָר.</p>\n<p>בְּטוּפְרִין אִית זִמְנִין, דְּנַהֲרִין בְּהוּ כֹּכָבִין חִוָּורִין דְּקִיקִין, וְאִלֵּין אִינּוּן כְּתוֹלְדָה דִּטְלוּפְחִין, וְאִינּוּן שְׁקִיעִין כְּהַאי מַסְמְרָא עַל לוּחָא. וְלָאו אִינּוּן כְּאִינּוּן חִוָּורִן אַחֲרָנִין דְּלָא שְׁקִיעִין, אֶלָּא דְּקַיְימִין לְעֵילָּא. בְּהָנִי דְּלָא שְׁקִיעִין, לֵית בְּהוּ מַמָּשָׁא. אֲבָל הָנִי דִּשְׁקִיעִין חִוָּורִין כְּתוֹלְדָה דִּטְלוּפְחִין אִית בְּהוּ מַמָּשָׁא, וְאִית סִימָנָא טָבָא לֵיהּ לְבַר נָשׁ בְּחֵדוּ (נ\"א בהו') וְיַצְלַח בְּהַהוּא זִמְנָא. אוֹ גְּזֵרָה אִתְגְּזַר עָלֵּיהּ וְאִשְׁתֵּזִיב מִינָהּ.</p>\n<p>שִׂרְטוּטֵי יְדִין בְּרָזִין עִלָּאִין, <Nonei></i>(שרטוטין) בְּאֶצְבְּעָן לְגוֹ. בְּיָדִין שִׂרְטוּטִין רַבְרְבִין, שִׂרְטוּטִין זְעִירִין דְּקִיקִין עִלָּאִין בִּימִינָא. בְּאִינּוּן אֶצְבְּעָן דִּבְהוּ שִׂרְטוּטִין זְעִירִין. בְּאֶצְבְּעָא זְעֵירָא דִּימִינָא, אִית רְשִׁימִין דְּקִיקִין. אֶצְבְּעָא דָּא, קַיְּימָא תָּדִיר עַל עוֹבָדִין דְּבִסְטַר אַחֲרָא.</p>\n<p>בְּהַאי אֶצְבְּעָא קַיְימִין שִׂרְטוּטִין, אִינּוּן דְּאֶצְבְּעָא אִתְכְּפִיל בְּהוּ. הָנֵי לָאו אִינּוּן לְאִסְתַּכְּלָא, אֶלָּא אִי אִתּוֹסְפָן בֵּיהּ. אִי אִתּוֹסְפָן תְּרֵין אוֹחֳרָנִין, עַל הַהוּא שִׂרְטוּטָא דְּאִתְכְּפַל בְּהוּ. אָרְחָא לָא אִזְדָּמַן לֵיהּ. וְאִי יַעֲבֹד לָא יִצְלַח.</p>\n<p>בַּר אִי קַיְימָן בְּאַרְכָּא, בֵּין רְשִׁימָא לִרְשִׁימָא, בְּזִמְנָא דְּיִתְמְשַׁךְ מַשְׁכָא לַאֲחוֹרָא, וְאִשְׁתָּאָרוּ אִינּוּן רְשִׁימִין דְּאִשְׁתְּמוֹדְעָן. הַאי יִצְלַח בְּאָרְחָא. וְסִימָן דָּא, תְּלַת תְּלַת בְּפוּתְיָא. וְאַרְבַּע בְּאַרְכָּא. וְרָזָא דָּא ז' מֵאַתְוָון זְעִירִין.</p>\n<p>רְשִׁימָא חַד בְּאַרְכָּא, וּתְרֵין תְּרֵין בְּפוּתְיָא. מֵאָרְחָא, יִשְׁמַע מִלִּין בִּזְמַן קָרִיב, וְלֵית לֵיהּ בְּהוּ תּוֹעַלְתָּא. אַרְבַּע רְשִׁימִין בְּאַרְכָּא, וְד' רְשִׁימִין בְּפוּתְיָא, אָרְחָא אִזְדָּמַן לֵיהּ בְּטֹרַח סַגִּי, וּלְסוֹפָא לְתוֹעַלְתָּיה. וְרָזָא דָּא ז' מֵאַתְוָון אֶמְצָעִיִּין, דְּבֵין זְעִירִין וְרַבְרְבִין.</p>\n<p>חָמֵשׁ זְעִירִין רְשִׁימִין בְּפוּתְיָא לְתַתָּא, וְאַרְבַּע בְּפוּתְיָא לְעֵילָּא, וְאַרְבַּע בְּאַרְכָּא. נַיְיחָא לֵיהּ בְּבֵיתֵיהּ, וְעַצְלָא אִיהוּ. וְאָרְחָא הֲוַת מְתַּתְקְנָא קָמֵיהּ, וְלָא בָּעֵי לְמֶעְבַּד. וְאִי יַעֲבֹד, יִצְלַח בְּהַהוּא אָרְחָא, אֲבָל לָא עָבִיד לֵיהּ, וְעַצְלָא הֲוֵי וְרָזָא דָּא ז' דְּאִיהִי פְּשׁוּטָה.</p>\n<p>בְּאֶצְבְּעָא דְּאֶמְצָעִיתָא, הַאי אֶצְבְּעָא קַיְּימָא, לְמֶעְבַּד עוֹבָדָא הַהוּא דְּחָשִׁיב. אִי שִׂרְטוּטָא חֲדָא קַיְּימָא בְּאַרְכָּא, בֵּין שִׂרְטוּטֵי דְּפוּתְיָא, הַאי חָשַׁב מַחֲשָׁבִין, וְאִסְתַּלְּקָן מִנֵּיהּ, וְדָחִיל וְלָא עָבִיד, וְהַהִיא מַחֲשָׁבָה לָא אִתְעָבִיד כְּלָל.</p>\n<p>אִי תְּרֵין שִׂרְטוּטִין בְּאַרְכָּא, דְּקַיְימִין כַּד אִתְפָּשַׁט מַשְׁכָא לַאֲחוֹרָא. הַאי לָאו בֵּיהּ מַחֲשָׁבִין, וְחָשִׁיב מַחֲשָׁבִין לְפוּם שַׁעֲתָא, וְאִתְעָבִיד, וְלָא מַחֲשָׁבָה דְּהִרְהֵר בֵּיהּ כְּלָל, אֶלָּא מַחֲשָׁבָה דְּאִיהוּ בִּבְהִילוּ וּזְעִירָא, אֲבָל הִרְהוּרָא וּמַחֲשָׁבָה לָא.</p>\n<p>וְאִי תְּלַת רְשִׁימִין בְּאַרְכָּא. וּבְפוּתְיָא תְּרֵין אוֹ תְּלַת, כַּד אִתְפָּשַׁט מַשְׁכָא לַאֲחוֹרָא. הַאי אִיהוּ בַּר נָשׁ דְּאִיהוּ פְּקִיחָא, וְחָשִׁיב מַחֲשָׁבִין, וְכָל אִינּוּן מַחֲשָׁבִין דְּאִינּוּן לִסְטַר קוּדְשָׁא בְּרִיךְ הוּא אִתְקַיְּימָן בִּידֵיהּ, וּמַחֲשָׁבִין אַחֲרָנִין לָאו הָכִי.</p>\n<p>אִי אַרְבַּע אוֹ חֲמִשָּׁה בְּאַרְכָּא, בְּאִתְפְּשָׁטוּ דְּמַשְׁכָא כִּדְקָאמְרַן, (דא איהו) כַּד שָׁרָאן עַל פּוּתְיָא, בִּתְלַת, אוֹ בְּאַרְבַּע, אוֹ מִתְּרֵין וּלְהָלְאָה. דָּא בַּר נָשׁ דְּמַחֲשָׁבוֹי לְאַבְאָשָׁא, וְאִשְׁתָּבַח בְּהוּ. וְדִיקְנִה וּגְבִינֵי עֵינוֹי סוּמָקִין, מְחַשֵּׁב לְבִישׁ וְאִשְׁתָּבַּח בְּהוּ. קִצְרָא דְּיוֹמִין אִיהוּ. פְּקִיחָא אִיהוּ. וְאַכְנַע תָּדִיר לִמְכִילָן דְּבִישׁ. אַצְלַח. וּלְסוֹפָא דְּיוֹמִין זְעִירִין אִסְתַּלָּק מֵעָלְמָא.</p>\n<p>אַסְוָותָא לְהַאי תִּיּוּבְתָּא. כְּדֵין אִשְׁתְּכָחוּ תְּלַת רְשִׁימִין, אוֹ אַרְבַּע, וְשַׁרְיָין עַל תְּרֵין. תְּלַת רְשִׁימִין אוֹ ד' בְּאַרְכָּא וְשַׁרְיָין עַל תְּרֵין בְּפוּתְיָא. דְּהָא כְּפוּם מִנְהֲגָא דְּבַר נָשׁ, הָכִי מִתְחַלְּפֵי שִׂרְטוּטִין, מִזְּמַן לִזְמַן. וְרָזָא דָּא (ישעיהו מ׳:כ״ו) הַמּוֹצִיא בְּמִסְפַּר צְבָאָם וְגוֹ', מֵרֹב אוֹנִים וְאַמִּיץ כֹּחַ וְגוֹ'.</p>\n<p>כְּמָה דְּקוּדְשָׁא בְּרִיךְ הוּא אַחְלָף חַיָּילִין וּזְמָנִין בְּכֹכְבֵי שְׁמַיָא, יוֹמָא דָּא כָּךְ, וּלְיוֹמָא אַחֲרָא כַּךְ. (ודא איהו דאמרינן בצלותא דערבית ומחליף את הזמנים ומסדר את הכוכבים כפום דחלופא דזמנים כך איהו מסדר כוכבים.) כְּפוּם דְּאָדָם דִּלְגוֹ כָּל עוֹבָדוֹי. הָכִי אִתְחָזוּן בְּהַאי רְקִיעָא. וְהָכִי אִתְחָזֵי בְּהַאי מַשְׁכָא דְּהַאי אָדָם תַּתָּאָה. דְּאִיהוּ רְקִיעָא, עוֹר דְּחַפְיָא עַל כֹּלָּא.</p>\n<p>וְכֹלָּא כְּפוּם גַּוְונָא דְּאָדָם דִּלְגוֹ, דְּהַאי לְזִמְנִין קָאִים בְּדִינָא, לְזִמְנִין בְּרַחֲמֵי, כְּהַהוּא גַּוְונָא מַמָּשׁ אַחְזֵי לְבַר. לְזִמְנִין כְּהַאי גַּוְונָא, וּלְזִמְנִין כְּהַאי גַּוְונָא כְּגַוְונָא דָּא לְתַתָּא בְּהַאי אָדָם, כְּמָה דְּאַמָרָן, לְזִמְנִין כְּהַאי גַּוְונָא, וּלְזִמְנִין כְּהַאי גַּוְונָא, וְרָזָא דָּא אָת ז' אִתְכְּלִיל בֵּיהּ אָת י'.</p>\n<p>וְרָזִין אִלֵּין בְּאֶצְבְּעָן <Nonei></i>דִּימִינָא, בִּזְעֵירָא וּבְרַבְרְבָא. וְסִימָן (דברים א׳:י״ז) כַּקָּטֹן כַּגָּדוֹל תִּשְׁמָעוּן. אֵלּוּ תְּרֵין אֶצְבְּעָן בְּרָזִין אִלֵּין, וְהָכִי אִינּוּן בְּרָזִין דְּאוֹלִיפְנָא מִנֵּיהּ דְּמֹר, (ולא אינון) בְּרָזֵי דְּרַב יֵיסָא סָבָא. מִכָּאן וּלְהָלְאָה שִׂרְטוּטִין אַחֲרָנִין, דְּאִקְרוּן כֻּלְּהוּ תוֹלְדוֹת, וְאִינּוּן תוֹלְדוֹת אָדָם, כְּמָה דִּכְתִּיב, (בראשית ב׳:ד׳) תוֹלְדוֹת הַשָּׁמַיִם, וְהָא אִתְּמַר, דְּכֹלָּא רָזָא דָּא. כְּגַוְונָא דָּא תוֹלְדוֹת אָדָם, בְּכָל אִינּוּן דִּיּוּקְנִין דְּאַנְפִּין, וּבְכָל אִינּוּן דְּקָאָמַרָן. וּבְאִלֵּין תוֹלְדוֹת דְּשִׂרְטוּטֵי יְדִין, דְּאִתְחַזְיָין בְּרָזִין פְּנִימָאִין, כְּמָה דְּאִתְחָזֵי.</p>\n<p>זֶה סֵפֶר תוֹלְדוֹת אָדָם, לְשִׂרְטוּטִין, סִימָן זר\"ה פס\"ץ. רָזִין לְחַכִּימֵי לִבָּא, רזהס\"ף, חָמֵשׁ אַתְוָון, בְּחָמֵשׁ תַּרְעִין, לְמִנְדַּע חָכְמָה בְּסוּכְלְתָנוּ.</p>\n<p>תַּרְעָא קַדְמָאָה, ר'. בִּידָא אִית שִׂרְטוּטִין דְּקִיקִין, וְשִׂרְטוּטִין רַבְרְבִין. וְכֻלְּהוּ מִתְעָרְבֵי דָּא עִם דָּא. שִׂרְטוּטִין רַבְרְבִין דְּאִית בִּידָא, כַּד אִינּוּן תְּרֵין בְּאַרְכָּא, וּתְרֵין בְּפוּתְיָא, וְאָחִידוּ דָּא בְּדָא, דָּא אִיהוּ בְּרָזָא דְּאָת ה', וּבְרָזָא דְּאָת ר' וְדָחֵי לְאָת ז', וְנָטִיל אִלֵּין תְּרֵין אַתְוָון. בְּפוּתְיָא נָטִיל ה', בְּאַרְכָּא נָטִיל ר', וְסִימָן דִּילֵיהּ ה\"ר.</p>\n<p>דָּא אִית לֵיהּ בִּידָא שְׂמָאלָא כְּהַאי גַּוְונָא בְּאִלֵּין שִׂרְטוּטִין רַבְרְבִין. אֲבָל אִינּוּן שִׂרְטוּטִין זְעִירִין דְּנָטְלָא יְמִינָא, לָא נָטְלָא שְׂמָאלָא. דִּימִינָא נָטְלָא, חַד שִׂרְטוּטָא דָּקִיק לְעֵילָּא בְּאַרְכָּא, וְחַד שִׂרְטוּטָא דָּקִיק לְתַתָּא, דְּאָחִיד בֵּין אִינּוּן תְּרֵין שִׂרְטוּטִין רַבְרְבָן. בְּפוּתְיָא אִית חַד שִׂרְטוּטָא דָּקִיק, דְּאָחִיד לְתַתָּא בְּאִינּוּן תְּרֵין דְּשַׁרְיָא עָלֵיהּ. וּבִשְׂמָאלָא לָאו הָכִי, וְרָזָא דִּילֵיהּ אִיהוּ בִּימִינָא, וְלָאו בִּשְׂמָאלָא.</p>\n<p>הַאי אִיהוּ בַּר נָשׁ, דִּלְזִמְנִין תָּאִיב בְּבֵיתָא, וּלְזִמְנִין בְּאָרְחָא, דָּא לָא שָׁכִיךְ לִבֵּיהּ בְּהַאי וּבְהַאי. כַּד אִיהוּ בְּבֵיתָא תָּאִיב בְּאָרְחָא, וְכַד אִיהוּ בְּאָרְחָא, תָּאִיב בְּבֵיתָא. אַצְלַח תָּדִיר בְּאָרְחָא, וּלְזִמְנִין בְּבֵיתָא. דָּא אַצְלַח בְּאוֹרַיְיתָא, וּבְרָזֵי דְּאוֹרַיְיתָא אִי אִשְׁתְּדַל בְּהוּ. הַאי חָמֵי בְּשַׂנְאוֹי, תּוֹעַלְתָּא לְסַגִּיאִין בֵּיהּ. עַצְלָא אִיהוּ בְּמִלֵּי דְּעָלְמָא. אִי אִתְּעַר, אִתְּעָרוּן לְאוֹטָבָא לֵיהּ מִלְּעֵילָּא. זָכֵי בְּמִלּוֹי. דָּא אִיהוּ חֲמִידָא וּמְפַזֵּר מָמוֹנָא. טָב עֵינָא אִיהוּ. צְלוֹתֵיהּ אִשְׁתְּמַע. נָחִית וְסָלִיק בְּמָמוֹנָא.</p>\n<p>דָּא אִיהוּ דִּלְזִמְנִין מִתְּבַּר לִבֵּיהּ לְגַבֵּיהּ מָארֵיהּ. וּכְדֵין אִשְׁתְּכָחוּ תְּלַת שִׂרְטוּטִין זְעִירִין, דִּמְעַבְּרָן בְּהַהוּא שִׂרְטוּטָא דָּקִיק, דְּאִתּוֹסָף עַל אִינּוּן תְּרֵין דְּפוּתְיָא, וְרָזָא דָּא ה' דְּמִתְחַבְּרָא עם ר'. דָּא אָרְחָא, דָּא בֵּיתָא. דָּא חֶדְוָה, דָּא עֲצִיבוּ, דָּא תּוֹעַלְתָּא, דָּא עַצְלָא, דָּא טָב עֵינָא, דָּא חֲמִידָא, וּמְפַזֵּר מָמוֹנָא. דָּא מִתְּבַּר לִבֵּיהּ, וְתָב לְמָארֵיהּ.</p>\n<p>תַּרְעָא תִּנְיָינָא, ז'. בִּימִינָא, בְּקַסְטִירוּ דְּקוֹלְטָא, רְשִׁימִין שְׁכִיחֵי, כַּד אִשְׁתְּכָחוּ תְּלַת שִׂרְטוּטִין רַבְרְבִין בְּפוּתְיָא, וּתְרֵין רַבְרְבִין בְּאַרְכָּא, וְחַד מֵאִינּוּן דְּאָרְכָּא, אָחִיד בְּאִינּוּן תְּרֵין דְּפוּתְיָא, וְחַד אַחֲרָא לָא אָחִיד בְּהוּ. הַאי אִית פַּסְלוּ בְּזַרְעֵיהּ, מִסִּטְרָא דַּאֲבוֹי, אוֹ מִסִּטְרָא דְּאִמֵּיהּ.</p>\n<p>וּכְדֵין מִשְׁתַּכְּחֵי לְתַתָּא מֵאִינּוּן תְּלַת שִׂרְטוּטִין דְּפוּתְיָא, תְּרֵין שִׂרְטוּטִין דְּקִיקִין, דַּאֲחִידָן בְּהוּ לְתַתָּא. הַאי אִיהוּ בַּר נָשׁ, מְתַקֵּן עוֹבָדוֹי, קָמֵי בְּנֵי נָשָׁא, וְלִבֵּיהּ לָא קְשׁוֹט. וּלְזִמְנָא דְּסִיב, אַהְדָּר לְאִתְתַּקְנָא. כְּדֵין אִשְׁתְּכָחוּ אִינּוּן תְּרֵין שִׂרְטוּטִין בְּאָרְכָא, אֲחִידָן בְּאִינוּן דְּפוּתְיָא, דָא עִם דָא. וּתְרֵין אַחֲרָנִין עִמְהוֹן בְּאֶמְצָעִיתָא, דְּקִיקִין, וְדָא בְּאַרְכָּא. וּתְלַת דְּקִיקִין בְּפוּתְיָא, וְרָזָא דָּא ז' דְּמִתְחַבְּרָא בְּאָת ר'.</p>\n<p>וְכַד אִיהוּ סִיב וְתָב כִּדְקָאמְרַן, אִתְתָּקַּן אִיהוּ בְּרָזָא דְּאָת ר', וְאִתְחֲבָּר בְּאָת ז'. לְבָתַר כַּד הַאי אִתְתָּקַּן, אִיהוּ תָּדִיר בִּלְחִישׁוּ, וְכָל עוֹבָדוֹי בִּלְחִישׁוּ. אֲבָל לָאו אִיהוּ בְּקִיּוּמָא כַּדְקָא חֲזִי בְּגִין דְּהַהוּא פַּסְלוּ, עַד לָא אִתְיָיאָשָׁא בֵּיהּ. (מכאן אוליפנא מאן דפסיל זרעיה עד תלת דרין לא אתייאשא ההוא פסילו (דף ע\"ז ע\"ב) מלכשכשא. בגין כך תנינן ווי ליה לההוא בר נש דפסל זרעיה ולא חייש ליקרא דמאריה. פסיל זרעיה ודאי.)</p>\n<p><Nonei></i>וּלְבָתַר דְּאִתְיָיאָשָׁא. הַהוּא פְּסִילוּ, כְּדֵין אִשְׁתְּכָחוּ שִׂרְטוּטִין בִּידָא יְמִינָא, אַרְבַּע וְחָמֵשׁ. אַרְבַּע בְּאַרְכָּא, חָמֵשׁ בְּפוּתְיָא. וְרָזָא דָּא ז', וְאִתְחֲבָּר בְּאָת ה'. הַאי לְזִמְנִין אַצְלַח, לְזִמְנִין לָא אַצְלַח. אַצְלַח בְּאוֹרַיְיתָא, וּלְסוֹף יוֹמוֹי, אַצְלַח אֲפִילּוּ בְּמָמוֹנָא.</p>\n<p>תַּרְעָא תְּלִיתָאָה, ה'. בִּימִינָא, כַּד אִשְׁתְּכָחוּ חָמֵשׁ שִׂרְטוּטִין בְּפוּתְיָא, וּתְלַת בְּאַרְכָּא, וְאִשְׁתְּכַח הַהוּא שִׂרְטוּטָא דְּאֶמְצָעִיתָא מֵאִינּוּן תְּלַת, דָּא אִיהוּ בְּרָזָא דְּאָת ה', וְאִסְתְּמִיךְ בְּאוֹת ס'.</p>\n<p>בְּזִמְנָא דְּאִשְׁתְּכַח הַהוּא שִׂרְטוּטָא דְּאֶמְצָעִיתָא, דְּעָאל וְאָחִיד גּוֹ אִינּוּן חָמֵשׁ שִׂרְטוּטִין דְּפוּתְיָא, דָּא אִיהוּ בַּר נָשׁ עָצִיב וְרָגִיז גּוֹ בֵּיתֵיהּ, וּבְגוֹ בְּנֵי נָשָׁא לָאו הָכִי. קַמְצָן אִיהוּ בְּבֵיתֵיהּ, וְרָגִיז וְכָפִין, וּלְזִמְנִין לָא. לְבַר מִבֵּיתֵיהּ לָאו הָכִי. אַצְלַח בְּעוֹבְדֵי עָלְמָא. כַּד אִשְׁתָּדַּל בְּאוֹרַיְיתָא אִסְתַּכִּיל זְעֵיר וְאִתְהַדָּר בָּהּ. מְהֵימָנָא אִיהוּ, אֲבָל לָאו כָּל זִמְנָא. וְהַהוּא זִמְנָא דְּלָאו מְהֵימָנָא, אַחְזֵי גּוָֹון קְשׁוֹט, וְלָא קְשׁוֹט בִּשְׁלִימוּ. בְּדִינָא יִצְלַח. מְהֵימָנָא אִיהוּ בְּרָזִין דְּאוֹרַיְיתָא, דָּא אִיהוּ בְּרָזָא דְּאָת ה', וְאִתְחֲבָּר בְּאָת ס'.</p>\n<p>וְאִי אַרְבַּע שִׂרְטוּטִין בְּפוּתְיָא, וְחָמֵשׁ בְּאַרְכָּא, תְּרֵין מֵאִינּוּן דְּאָרְכָּא, עָאלִין גּוֹ אִינּוּן אַרְבַּע, דָּא אִיהוּ בַּר נָשׁ חַדֵּי בְּבֵיתֵיהּ, וְאִתְחַזֵּי עָצִיב לִבָּא לְבַר, וְלָאו הָכִי דְּכֵיוָן דְּמַלִּיל עִם בְּנֵי נָשָׁא, אַחְזֵי חֵדוּ וְאִתְכְּוָון בְּמִלּוֹי.</p>\n<p>תְּלַת שִׂרְטוּטִין זְעִירִין עָאלִין גּוֹ אִינּוּן דְּאָרְכָּא, דָּא אִית לֵיהּ חַד רְשִׁימוּ אוּכָם בְּגוּפֵיהּ, וּתְלַת שַׂעֲרִין תַּלְיָין בְּהַהוּא רְשִׁימוּ, וְהַהוּא רְשִׁימוּ אִיהוּ כְּעִגּוּלָא, וְחַד תְּבִירָא (חבורא) בְּרֵישֵׁיהּ. וּלְהַאי רְשִׁימָא, קָרָאן לֵיהּ חַכִּימֵי לִבָּא, דְּיַדְעִין רָזִין אִלֵּין, רֵישׁ נִשְׁרָא. רְשִׁימוּ דָּא, אִתְחָזֵי לְזִמְנִין, בֵּין כִּתְפוֹי. וּלְזִמְנִין, בִּדְרוֹעָא יְמִינָא. וּלְזִמְנִין, עַל יְדָא יְמִינָא בְּאֶצְבְּעוֹי.</p>\n<p>אִי רְשִׁימָא דָּא רֵישׁ נִשְׁרָא, אִיהוּ בְּאֹרַח מֵישָׁר בְּתִיקוּנוֹי, יִסְתַּלַּק לְעוּתְרָא וְלִיקָרָא. וְאִי הַהוּא רֵישׁ נִשְׁרָא אִתְהַפַּךְ לַאֲחוֹרָא, יִזְכֶּה לְבֵנִין לְזִמְנִין. אֲבָל כַּד אִיהוּ סִיב, יִזְכֶּה לְעוּתְרָא יַתִּיר, וְלִיקָר סַגְיָא, יַתִּיר מֵעוּלְמוֹי, וְיַצְלַח בְּאוֹרַיְיתָא, אִי אִשְׁתַּדַּל בָּהּ.</p>\n<p>רֵישׁ נִשְׁרָא דָּא, אִתְחָזֵי לְזִמְנִין אוּכָמָא, וּלְזִמְנִין גּוָֹון דְּלָא סוּמָק זְעֵיר, דְּלָא אִצְטְבַּע כָּל כַּךְ. לְזִמְנִין בְּשַׂעֲרִין לְזִמְנִין שְׁעִיעַ, וְכֹלָּא חַד סִימָנָא אִיהוּ, וּבְחַד דִּינָא אִתְדָּן.</p>\n<p>וְאִי הַהוּא גּוָֹון סוּמָק אִצְטְבַּע יַתִּיר, וְקָאִים בִּגְוָונֵיהּ, זְמַן זְעֵיר הוּא דְּאִצְטְבַע, בְּגִין דְּאִלֵּין גַּוְונִין, לְזִמְנִין קַיְימִין נְהִירִין, וּלְזִמְנִין חֲשׁוּכִין. וְאִי אִצְטְבַּע הַהוּא סוּמָק וְנָהִיר, כְּדֵין אִית בִּידָא שְׂמָאלָא, תְּלַת שִׂרְטוּטִין בְּאַרְכָּא, וּתְלַת בְּפוּתְיָא, וְחַד דָּקִיק עַל אִינּוּן דְּפוּתְיָא, וְחַד דָּקִיק עַל אִינּוּן דְּאָרְכָּא. וּבִידָא יְמִינָא אִתּוֹסָף חַד בְּפוּתְיָא בִּלְחוֹדוֹי. הַאי בַּר נָשׁ שָׁכִיב בְּנִּדָּה, וְלָא תָּב מִינֵּהּ לְמָארֵיהּ.</p>\n<p>וְכַד תָּב בִּתְיוּבְתָּא, אִשְׁתָּאָרוּ אִינּוּן שִׂרְטוּטִין בִּידָא שְׂמָאלָא, וְהַהוּא דְּאִתּוֹסָף בִּימִינָא, אִתְעָדֵי מִנֵּיהּ, וְאִתְעָדֵי הַהוּא סוּמָקָא, דְּלָא אִתְחָזֵי נָהִיר כָּל כַּךְ מִנֵּיהּ. וּלְזִמְנִין דְּאַף עַל גַּב דְּתָב, לָא אַעְדִּיוּ מִנִּיהּ הַהוּא סוּמָקָא, עַד זְמַן. הַאי אִיהוּ בְּרָזָא דְּאָת ה', וְאִתְעָדֵי אָת ס', וְעָאל תְּחוֹתוֹי אָת ץ', וְאִתְחֲבָּר אָת ה' בְּאָת ץ'. הַאי בָּעֵי תִּקּוּנָא לְנַפְשֵׁיהּ בִּבְהִילוּ. חַכִּימָא דְּלִבָּא דְּחָמֵי לֵיהּ, חוֹבָתָא אִית עָלֵיהּ, לוֹמַר לֵיהּ זִיל אַסֵּי לְנַפְשָׁךְ.</p>\n<p>וְאִי תְּלַת שִׂרְטוּטִין בְּאַרְכָּא, וְחַד בְּפוּתְיָא, דָּא אִיהוּ בְּרָזָא דְּאָת ה' בִּלְחוֹדֵיהּ. וּלְזִמְנִין אִתְחַבַּר בְּרָזָא דְּאָת ז'. הַאי אִיהוּ בַּר נָשׁ תָּאִיב בָּתַר בִּצְעִין דְּעָלְמָא. וְאִי לָאו, רָדִיף בָּתַר נָשִׁין, וְתֵיאוּבְתֵיהּ נִאוּפִים. וְאַף עַל גַּב דְּתָאִיב לְבִצְעִין דְּעָלְמָא, הַאי לָא אַעְדִּיו מִנֵּיהּ, וְלָא אַכְסִיף. עֵינוֹי שְׁקִיעִין וּמַלִּיל בְּהוּ.</p>\n<p>אִי תָּב לְמָארֵיהּ מִתְחַלְּפֵי שִׂרְטוּטִין. תְּלָת בְּפוּתְיָא וְחַד לְאָרְכָּא, וְאִינּוּן תְּרֵין דְּקִיקִין <Nonei></i>קַיְימִין בְּקִיּוּמָא, כְּדֵין רְעוּ דִּילֵיהּ יַתִּיר בְּאִתְּתֵיהּ, וְאִתְדְּבַק בָּהּ. חַד דָּקִיק יַתִּיר, עָאל בֵּין אִינּוּן תְּרֵין דְּקִיקִין. כְּדֵין אִתְחַבַּר אָת ה' בְּאָת ז'.</p>\n<p>וְאִי שִׂרְטוּטָא חַד בְּאַרְכָּא וְאַרְבַּע בְּפוּתְיָא, וּתְלַת דְּקִיקִין קַיְימִין עַל הַהוּא חַד, וְחַד עַל אִינּוּן אַרְבַּע. עַל דְּרוֹעָא שְׂמָאלָא, אִית לֵיהּ תְּלַת קִסְטְרִין דְּקִיקִין, דְּאִתְיְלִידוּ בֵּיהּ מִיּוֹמִין זְעִירִין, וְחַד שַׂעֲרָא תַּלְיָא, בְּהַהוּא חַד דְּרֵישָׁא. הַאי אִיהוּ רָדִיף בָּתַר נְאוּפָא דְּאֵשֶׁת חַבְרֵיהּ. מָארֵיהּ דִּזְדוֹנָא אִיהוּ. אַגְזִים בְּעֵינָא שְׂמָאלָא, בְּלָא מִלּוּלָא כָּלַל, וְאַשְׁלִים. וּבְגִין דְּאִיהוּ מָארִיהּ זְדוֹנָא, לָא חָיִישׁ לִיקָרָא דְּמָארֵיהּ, לְאָתָבָא קָמֵיהּ. לְבָתַר קָטִיל חִוְיָא לֵיהּ, אוֹ בַּר נָשׁ סוּמָקָא.</p>\n<p>וְאִי אַרְבַּע בְּאַרְכָּא, וּתְלַת בְּפוּתְיָא, וְאִינּוּן דְּסַלְּקִין לְעֵילָּא אַעְדִּיוּ מִנֵּיהּ. הַאי, תָּבַר לִבֵּיהּ לְגַבֵּי מָארֵיהּ, וְתָב בְּתִיוּבְתָא. כְּדֵין אִיהוּ בְּרָזָא דְּאָת פ', וְאִתְחֲבָּר בְּאָת ה'. עַל אִלֵּין, וְעַל אִינּוּן דִּכְוָותֵיהּ, כְּתִיב, (ישעיהו נ״ז:י״ט) שָׁלוֹם שָׁלוֹם לָרָחוֹק וְלַקָּרוֹב.</p>\n<p>עַד הָכָא, כָּל אִינּוּן רָזִין דְּתוֹלְדוֹת אָדָם, דְּאִינּוּן תוֹלְדוֹת, דְּאִתְיְלִידוּ בֵּיהּ מִזְּמַן לִזְמַן, כְּפוּם אָרְחוֹי דְּבַר נָשׁ. זַכָּאָה חוּלָקֵיהוֹן דְּאִינּוּן דְּיַתְבִין קָמֵיהּ דְּמֹר, וְזָכוּ לְמִשְׁמַע מִפּוּמֵיהּ רָזִין דְּאוֹרַיְיתָא. זַכָּאָה אִינּוּן בְּהַאי עָלְמָא, וְזַכָּאִין אִינּוּן לְעָלְמָא דְּאָתֵי. אָמַר ר' שִׁמְעוֹן, זַכָּאִין אַתּוּן חַבְרַיָּא, דְּכָל רָזִין לָא אָנִיס לְכוּ, כַּמָּה דּוּכְתִּין עִלָּאִין אִזְדַּמְּנָן לְכוּ לְעָלְמָא דְּאָתֵי.</p>\n<p>פָּתַח וְאָמַר (שמות י״ח:כ״א) וְאַתָּה תֶחזֶה מִכָּל הָעָם אַנְשֵׁי חַיִל יִרְאֵי אֱלֹהִים אַנְשֵׁי אֱמֶת שׂוֹנְאֵי בָצַע, הַאי קְרָא אוּקְמוּהָ. אֲבָל וְאַתָּה תֶחזֶה, תִּבְחַר לָא כְּתִיב. אֶלָּא תֶחזֶה: לְפוּם חֵיזוּ דְּעַיְינִין. בְּמַאי. בְּדִיּוּקְנָא דְּבַר נָשׁ בְּאִלֵּין שִׁית סִטְרִין דְּקָאָמַרְתּוּן וְכֹלָּא בְּהַאי קְרָא. וְאַתָּה תֶחזֶה, חַד, בְּשַׂעְרָא. מִכָּל הָעָם, תְּרֵין, בְּמִצְחָא. אַנְשֵׁי חַיִל, תְּלַת, בְּאַנְפִּין. יִרְאֵי אֱלֹהִים, אַרְבַּע, בְּעַיְינִין. אַנְשֵׁי אֱמֶת, חָמֵשׁ, בְּשִׁפְוָון. שׂוֹנְאֵי בָצַע, שִׁית, בְּיָדִין. בְּשִׂרְטוּטֵיהוֹן.</p>\n<p>דְּאִלֵּין אִינּוּן סִימָנִין, לְאִשְׁתְּמוֹדְעָא בְּהוּ בְּנִי נָשָׁא, לְאִינוּן דְּרוּחַ חָכְמְתָא שַׁרְיָא עָלַיְיהוּ. וְעִם כָּל דָּא, מֹשֶׁה לָא אִצְטְרִיךְ דָּא, אֶלָּא מַה כְּתִיב, וַיִּבְחַר מֹשֶׁה אַנְשֵׁי חַיִל מִכָּל יִשְׂרָאֵל. בְּגִין דְּרוּחָא קוּדְשָׁא הֲוָה אָתֵי לְגַבֵּיהּ, וְאוֹדַע לֵיהּ, וּבֵיהּ הֲוָה חָמֵי כֹּלָּא.</p>\n<p>מְנָא לָן, דִּכְתִּיב כִּי יִהְיֶה לָהֶם דָּבָר בָּא אֵלַי. בָּאִים אֵלַי לָא כְּתִיב, אֶלָּא בָּא אֵלַי, דָּא רוּחַ קוּדְשָׁא, דְּהֲוָה אָתֵי לְגַבֵּיהּ, וּבֵיהּ הֲוָה יָדַע, וְלָא אִצְטְרִיךְ לְכָל דָּא לְאִסְתַּכְּלָא וּלְעַיְינָא, אֶלָּא לְפוּם שַׁעֲתָא הֲוָה יָדַע מֹשֶׁה.</p>\n<p>כְּהַאי גַּוְונָא, יָדַע שְׁלֹמֹה מַלְכָּא, יָדַע בְּכוּרְסְיֵיהּ, דְּרוּחַ קוּדְשָׁא שַׁרְיָא עָלֵיהּ, דְּכָל מַאן דְּקָרִיב לְכוּרְסְיֵיהּ, דְּחִילוּ וְאֵימָתָא נָפִיל עָלֵיהּ, וּבֵיהּ הֲוָה דָּאִין דִּינָא בְּלָא סָהֲדִין. בְּגִין דְּדִיּוּקְנִין הֲווֹ בְּכוּרְסְיֵיהּ, וְכָל מַאן דְּמִקְרַב בְּשִׁקְרָא, מְכַשְׁכְּשָׁא הַהוּא דִּיּוּקְנָא, וַהֲוָה יָדַע שְׁלֹמֹה מַלְכָּא, דִּבְשִׁקְרָא קָאֲתֵי. בְּגִין כַּךְ, אֵימָתָא דְּכוּרְסְיֵהּ הֲוָה נָפִיל עַל כֹּלָּא, וְכֻלְּהוּ אִשְׁתְּכָחוּ זַכָּאִין קָמֵיהּ.</p>\n<p>מַלְכָּא מְשִׁיחָא בְּרֵיחָא, כְּמָה דְאַתְּ אָמֵר (ישעיהו י״א:ג׳) וַהֲרִיחוֹ בְּיִרְאַת יְיָ' וְלא לְמַרְאֵה עֵינָיו יִשְׁפּוֹט וְגוֹ'. וּתְלַת אִלֵּין, דָּנוּ עָלְמָא, בְּלָא סָהֲדִין וְהַתְרָאָה. שְׁאַר בְּנֵי עָלְמָא עַל פּוּם סָהֲדִין, עַל מֵימָר אוֹרַיְיתָא. חַכִּימִין דְּאִשְׁתְּמוֹדְעָן בְּאִינּוּן דִּיּוּקְנִין, עָלַיְיהוּ לְאַזְהָרָא לִבְנֵי עָלְמָא, וּלְמֵיהַב אַסְוָותָא לִבְנֵי נָשָׁא, וּלְאַסֵּי נַפְשַׁיְיהוּ. זַכָּאִין אִינּוּן בְּהַאי עָלְמָא, וְזַכָּאִין אִינּוּן בְּעָלְמָא דְּאָתֵי.</p>"]]});
